INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('8d78415a-5401-5b40-a138-25f5296aad7e', 'f333f5c4-95b4-55a1-a42f-f36d3048c6aa', NULL, 27, 27, 'the Jews established, and imposed on themselves, and on their descendants, and on all those who joined themselves to them, so that it should not fail, that they would keep these two days according to what was written, and according to its appointed time, every year;'),
  ('7fbb2c03-4597-54aa-aae3-bfca579e93b9', 'f333f5c4-95b4-55a1-a42f-f36d3048c6aa', NULL, 28, 28, 'and that these days should be remembered and kept throughout every generation, every family, every province, and every city; and that these days of Purim should not fail from among the Jews, nor the memory of them perish from their seed.'),
  ('bb50e3b7-8e3d-59ab-a45a-4835d2ba999c', 'f333f5c4-95b4-55a1-a42f-f36d3048c6aa', NULL, 29, 29, 'Then Esther the queen, the daughter of Abihail, and Mordecai the Jew, wrote with all authority to confirm this second letter of Purim.'),
  ('3ded6cbe-1af1-5fb9-ae51-ecd6b65631ba', 'f333f5c4-95b4-55a1-a42f-f36d3048c6aa', NULL, 30, 30, 'He sent letters to all the Jews, to the hundred twenty-seven provinces of the kingdom of Ahasuerus, with words of peace and truth,'),
  ('f5455e7b-4362-52d4-a7df-acc77a4a2f95', 'f333f5c4-95b4-55a1-a42f-f36d3048c6aa', NULL, 31, 31, 'to confirm these days of Purim in their appointed times, as Mordecai the Jew and Esther the queen had decreed, and as they had imposed upon themselves and their descendants, in the matter of the fastings and their cry.'),
  ('5b5030c6-5319-5c49-ad83-58f366b78328', 'f333f5c4-95b4-55a1-a42f-f36d3048c6aa', NULL, 32, 32, 'The commandment of Esther confirmed these matters of Purim; and it was written in the book.'),
  ('bda5ae18-f55f-5677-a416-b10587ed9c77', 'ac5fcded-b4bd-5c9a-a716-356fbb048679', NULL, 1, 1, 'King Ahasuerus laid a tribute on the land, and on the islands of the sea.'),
  ('11780697-877f-5af2-a9a9-bd03a58f046c', 'ac5fcded-b4bd-5c9a-a716-356fbb048679', NULL, 2, 2, 'All the acts of his power and of his might, and the full account of the greatness of Mordecai, to which the king advanced him, aren''t they written in the book of the chronicles of the kings of Media and Persia?'),
  ('27e57e44-957b-551c-ae29-929b65397745', 'ac5fcded-b4bd-5c9a-a716-356fbb048679', NULL, 3, 3, 'For Mordecai the Jew was next to King Ahasuerus, and great among the Jews, and accepted by the multitude of his brothers, seeking the good of his people, and speaking peace to all his descendants.'),
  ('c6a32d75-b844-5576-a571-7389a7fb3f61', 'de54e79d-9e08-5e40-a335-e715e3ed490d', NULL, 1, 1, 'There was a man in the land of Uz, whose name was Job. That man was blameless and upright, and one who feared God, and turned away from evil.'),
  ('1a389fa2-ad4d-5cf2-a2f6-e81d4f92ffe4', 'de54e79d-9e08-5e40-a335-e715e3ed490d', NULL, 2, 2, 'There were born to him seven sons and three daughters.'),
  ('2ed424dd-3d5b-54f4-a39f-8e1d3b181992', 'de54e79d-9e08-5e40-a335-e715e3ed490d', NULL, 3, 3, 'His possessions also were seven thousand sheep, three thousand camels, five hundred yoke of oxen, five hundred female donkeys, and a very great household; so that this man was the greatest of all the children of the east.'),
  ('1c739929-d2de-5eec-a406-2d86d77d5bc9', 'de54e79d-9e08-5e40-a335-e715e3ed490d', NULL, 4, 4, 'His sons went and held a feast in the house of each one on his birthday; and they sent and called for their three sisters to eat and to drink with them.'),
  ('051ec1c0-4b99-510a-a886-af24ed02cd08', 'de54e79d-9e08-5e40-a335-e715e3ed490d', NULL, 5, 5, 'It was so, when the days of their feasting had run their course, that Job sent and sanctified them, and rose up early in the morning, and offered burnt offerings according to the number of them all. For Job said, "It may be that my sons have sinned, and renounced God in their hearts." Job did so continually.'),
  ('cb1640e5-51f5-5b21-a025-d424ddd25786', 'de54e79d-9e08-5e40-a335-e715e3ed490d', NULL, 6, 6, 'Now it happened on the day when God''s sons came to present themselves before Yahweh, that Satan also came among them.'),
  ('e700021b-8d4b-5084-a7b3-3e7ecd536ae5', 'de54e79d-9e08-5e40-a335-e715e3ed490d', NULL, 7, 7, 'Yahweh said to Satan, "Where have you come from?" Then Satan answered Yahweh, and said, "From going back and forth in the earth, and from walking up and down in it."'),
  ('3780424c-c405-59bc-a7a5-f8e9296a1db8', 'de54e79d-9e08-5e40-a335-e715e3ed490d', NULL, 8, 8, 'Yahweh said to Satan, "Have you considered my servant, Job? For there is none like him in the earth, a blameless and an upright man, one who fears God, and turns away from evil."'),
  ('79fd60d3-27f9-57b4-a201-29622cc50325', 'de54e79d-9e08-5e40-a335-e715e3ed490d', NULL, 9, 9, 'Then Satan answered Yahweh, and said, "Does Job fear God for nothing?'),
  ('7e97d48e-14bb-5686-a117-00869095eaa0', 'de54e79d-9e08-5e40-a335-e715e3ed490d', NULL, 10, 10, 'Haven''t you made a hedge around him, and around his house, and around all that he has, on every side? You have blessed the work of his hands, and his substance is increased in the land.'),
  ('e317b20b-00ca-50a9-a8cc-74cc304af425', 'de54e79d-9e08-5e40-a335-e715e3ed490d', NULL, 11, 11, 'But put forth your hand now, and touch all that he has, and he will renounce you to your face."'),
  ('5d6a54f6-3527-5e1e-a63c-b5598725bbc4', 'de54e79d-9e08-5e40-a335-e715e3ed490d', NULL, 12, 12, 'Yahweh said to Satan, "Behold, all that he has is in your power. Only on himself don''t put forth your hand." So Satan went forth from the presence of Yahweh.'),
  ('e19ce7ca-d473-5f0e-ad8d-142b8aba2207', 'de54e79d-9e08-5e40-a335-e715e3ed490d', NULL, 13, 13, 'It fell on a day when his sons and his daughters were eating and drinking wine in their eldest brother''s house,'),
  ('097fe036-e806-5918-a6d0-65d311c3baa2', 'de54e79d-9e08-5e40-a335-e715e3ed490d', NULL, 14, 14, 'that there came a messenger to Job, and said, "The oxen were plowing, and the donkeys feeding beside them,'),
  ('1b019926-8657-5510-a7fe-c520c5a76218', 'de54e79d-9e08-5e40-a335-e715e3ed490d', NULL, 15, 15, 'and the Sabeans attacked, and took them away. Yes, they have killed the servants with the edge of the sword, and I alone have escaped to tell you."'),
  ('be147df6-7452-5307-a258-6fbae370e5d5', 'de54e79d-9e08-5e40-a335-e715e3ed490d', NULL, 16, 16, 'While he was still speaking, there also came another, and said, "The fire of God has fallen from the sky, and has burned up the sheep and the servants, and consumed them, and I alone have escaped to tell you."'),
  ('81ca5ead-10de-5fde-a9f4-f0c7507771df', 'de54e79d-9e08-5e40-a335-e715e3ed490d', NULL, 17, 17, 'While he was still speaking, there came also another, and said, "The Chaldeans made three bands, and swept down on the camels, and have taken them away, yes, and killed the servants with the edge of the sword; and I alone have escaped to tell you."'),
  ('4b9cf57b-d997-501a-aa3d-2b9a1a3466ea', 'de54e79d-9e08-5e40-a335-e715e3ed490d', NULL, 18, 18, 'While he was still speaking, there came also another, and said, "Your sons and your daughters were eating and drinking wine in their eldest brother''s house,'),
  ('b5617995-efce-55a3-aab1-f31c0c7633bd', 'de54e79d-9e08-5e40-a335-e715e3ed490d', NULL, 19, 19, 'and behold, there came a great wind from the wilderness, and struck the four corners of the house, and it fell on the young men, and they are dead. I alone have escaped to tell you."'),
  ('234da279-9ad6-5a2f-adde-2ca978898222', 'de54e79d-9e08-5e40-a335-e715e3ed490d', NULL, 20, 20, 'Then Job arose, and tore his robe, and shaved his head, and fell down on the ground, and worshiped.'),
  ('a254d6ff-124c-58e9-aa4b-ae4b58ff277e', 'de54e79d-9e08-5e40-a335-e715e3ed490d', NULL, 21, 21, 'He said, "Naked I came out of my mother''s womb, and naked shall I return there. Yahweh gave, and Yahweh has taken away. Blessed be the name of Yahweh."'),
  ('93be9196-4dd1-545b-a1bf-c9255983c978', 'de54e79d-9e08-5e40-a335-e715e3ed490d', NULL, 22, 22, 'In all this, Job did not sin, nor charge God with wrongdoing.'),
  ('274016fb-5968-51e1-ad8c-4df6e9690730', '68c06f50-fe4a-5609-ac24-19a950fff30b', NULL, 1, 1, 'Again it happened on the day when the God''s sons came to present themselves before Yahweh, that Satan came also among them to present himself before Yahweh.'),
  ('bd8cfa02-bbf7-5eee-a436-14a9a1e71711', '68c06f50-fe4a-5609-ac24-19a950fff30b', NULL, 2, 2, 'Yahweh said to Satan, "Where have you come from?" Satan answered Yahweh, and said, "From going back and forth in the earth, and from walking up and down in it."'),
  ('2868a03f-b0d6-5876-ade6-d5862be6fd2e', '68c06f50-fe4a-5609-ac24-19a950fff30b', NULL, 3, 3, 'Yahweh said to Satan, "Have you considered my servant Job? For there is none like him in the earth, a blameless and an upright man, one who fears God, and turns away from evil. He still maintains his integrity, although you incited me against him, to ruin him without cause."'),
  ('1a3ca011-8dd5-5bec-a5a7-37f3d7875e8a', '68c06f50-fe4a-5609-ac24-19a950fff30b', NULL, 4, 4, 'Satan answered Yahweh, and said, "Skin for skin. Yes, all that a man has he will give for his life.'),
  ('4150bbef-4012-5b95-a7aa-5d7f7af7a84e', '68c06f50-fe4a-5609-ac24-19a950fff30b', NULL, 5, 5, 'But put forth your hand now, and touch his bone and his flesh, and he will renounce you to your face."'),
  ('ced4ff9e-03af-51ff-a6d3-278c600ec744', '68c06f50-fe4a-5609-ac24-19a950fff30b', NULL, 6, 6, 'Yahweh said to Satan, "Behold, he is in your hand. Only spare his life."'),
  ('64e73073-9f64-5cc8-a534-362733330603', '68c06f50-fe4a-5609-ac24-19a950fff30b', NULL, 7, 7, 'So Satan went forth from the presence of Yahweh, and struck Job with painful sores from the sole of his foot to his head.'),
  ('d4b5fc02-7577-5c0f-a110-17e08fc95ded', '68c06f50-fe4a-5609-ac24-19a950fff30b', NULL, 8, 8, 'He took for himself a potsherd to scrape himself with, and he sat among the ashes.'),
  ('ef0cf168-d835-59a5-aa7b-32ed7596ab5e', '68c06f50-fe4a-5609-ac24-19a950fff30b', NULL, 9, 9, 'Then his wife said to him, "Do you still maintain your integrity? Renounce God, and die."'),
  ('eac98428-b650-5563-a8fa-b2e9db0de637', '68c06f50-fe4a-5609-ac24-19a950fff30b', NULL, 10, 10, 'But he said to her, "You speak as one of the foolish women would speak. What? Shall we receive good at the hand of God, and shall we not receive evil?" In all this Job didn''t sin with his lips.'),
  ('a422c877-56c8-50eb-ae55-bb1d213b2480', '68c06f50-fe4a-5609-ac24-19a950fff30b', NULL, 11, 11, 'Now when Job''s three friends heard of all this evil that had come on him, they each came from his own place: Eliphaz the Temanite, Bildad the Shuhite, and Zophar the Naamathite, and they made an appointment together to come to sympathize with him and to comfort him.'),
  ('39ea9764-e4ad-5793-af75-6fe2cc8d6696', '68c06f50-fe4a-5609-ac24-19a950fff30b', NULL, 12, 12, 'When they lifted up their eyes from a distance, and didn''t recognize him, they raised their voices, and wept; and they each tore his robe, and sprinkled dust on their heads toward the sky.'),
  ('1d6aa30e-f332-57c9-a9a2-79d2b5f0827d', '68c06f50-fe4a-5609-ac24-19a950fff30b', NULL, 13, 13, 'So they sat down with him on the ground seven days and seven nights, and none spoke a word to him, for they saw that his grief was very great.'),
  ('94b1e4f5-8ae1-500e-acf2-38c1714b9623', '825297e1-149a-57a1-a648-707a4d877824', NULL, 1, 1, 'After this Job opened his mouth, and cursed the day of his birth.'),
  ('1ee9359d-3e3a-581f-a833-feef8e8bfde2', '825297e1-149a-57a1-a648-707a4d877824', NULL, 2, 2, 'Job answered:'),
  ('68880ed7-8f72-5877-af49-531dd3a89ece', '825297e1-149a-57a1-a648-707a4d877824', NULL, 3, 3, '"Let the day perish in which I was born, the night which said, ''There is a boy conceived.'''),
  ('3a751661-94e0-524d-ac4d-68587c0f09db', '825297e1-149a-57a1-a648-707a4d877824', NULL, 4, 4, 'Let that day be darkness. Don''t let God from above seek for it, neither let the light shine on it.'),
  ('d44af530-1362-5556-ab02-613a1d728e4f', '825297e1-149a-57a1-a648-707a4d877824', NULL, 5, 5, 'Let darkness and the shadow of death claim it for their own. Let a cloud dwell on it. Let all that makes black the day terrify it.'),
  ('10fb83b2-aa73-5d4d-a900-26fdfac2a7d6', '825297e1-149a-57a1-a648-707a4d877824', NULL, 6, 6, 'As for that night, let thick darkness seize on it. Let it not rejoice among the days of the year. Let it not come into the number of the months.'),
  ('c3e814fc-32aa-518b-af35-61683900072a', '825297e1-149a-57a1-a648-707a4d877824', NULL, 7, 7, 'Behold, let that night be barren. Let no joyful voice come therein.'),
  ('69fac057-2f79-52fc-a12e-df873a7583ea', '825297e1-149a-57a1-a648-707a4d877824', NULL, 8, 8, 'Let them curse it who curse the day, who are ready to rouse up leviathan.'),
  ('d3e61fcf-5196-584b-a4ec-76f34c57bdc0', '825297e1-149a-57a1-a648-707a4d877824', NULL, 9, 9, 'Let the stars of its twilight be dark. Let it look for light, but have none, neither let it see the eyelids of the morning,'),
  ('a10d6b5a-b048-5961-a1a0-420128338b17', '825297e1-149a-57a1-a648-707a4d877824', NULL, 10, 10, 'because it didn''t shut up the doors of my mother''s womb, nor did it hide trouble from my eyes.'),
  ('2049eaea-8093-5cb1-aace-19b5f6f93d7a', '825297e1-149a-57a1-a648-707a4d877824', NULL, 11, 11, '"Why didn''t I die from the womb? Why didn''t I give up the spirit when my mother bore me?'),
  ('cf5724b7-c0f9-5afa-a52c-a6a6e7506aea', '825297e1-149a-57a1-a648-707a4d877824', NULL, 12, 12, 'Why did the knees receive me? Or why the breast, that I should nurse?'),
  ('a94ac98d-eaf4-5a4a-a9d9-9a97d89d4fba', '825297e1-149a-57a1-a648-707a4d877824', NULL, 13, 13, 'For now should I have lain down and been quiet. I should have slept, then I would have been at rest,'),
  ('1d91f599-5309-572e-a456-23d4408d8398', '825297e1-149a-57a1-a648-707a4d877824', NULL, 14, 14, 'with kings and counselors of the earth, who built up waste places for themselves;'),
  ('44b1656a-f851-5423-ade7-fadb47e3fa9b', '825297e1-149a-57a1-a648-707a4d877824', NULL, 15, 15, 'or with princes who had gold, who filled their houses with silver:'),
  ('cfc8d9a2-a069-5f3b-a5e0-467287b3659f', '825297e1-149a-57a1-a648-707a4d877824', NULL, 16, 16, 'or as a hidden untimely birth I had not been, as infants who never saw light.'),
  ('9d324b1b-78e7-514f-a664-1ee10164fc69', '825297e1-149a-57a1-a648-707a4d877824', NULL, 17, 17, 'There the wicked cease from troubling. There the weary are at rest.'),
  ('c131239e-ff87-5730-ade5-efb2c23ac8dd', '825297e1-149a-57a1-a648-707a4d877824', NULL, 18, 18, 'There the prisoners are at ease together. They don''t hear the voice of the taskmaster.'),
  ('15633570-3eb9-5cf7-afc5-b96bbb6f9792', '825297e1-149a-57a1-a648-707a4d877824', NULL, 19, 19, 'The small and the great are there. The servant is free from his master.'),
  ('2184b911-2aa4-511e-a4cd-d03f07550aa5', '825297e1-149a-57a1-a648-707a4d877824', NULL, 20, 20, '"Why is light given to him who is in misery, life to the bitter in soul,'),
  ('381226b3-ae5b-525c-a17c-a048bfaa3491', '825297e1-149a-57a1-a648-707a4d877824', NULL, 21, 21, 'Who long for death, but it doesn''t come; and dig for it more than for hidden treasures,'),
  ('711e0dc0-acfc-5f47-a90c-34190ee80a2c', '825297e1-149a-57a1-a648-707a4d877824', NULL, 22, 22, 'who rejoice exceedingly, and are glad, when they can find the grave?'),
  ('acd9ba6c-40bf-51fc-a388-0d1a9d5ef9c9', '825297e1-149a-57a1-a648-707a4d877824', NULL, 23, 23, 'Why is light given to a man whose way is hidden, whom God has hedged in?'),
  ('be2b7094-c822-5baa-afc2-5b2d3ce6f728', '825297e1-149a-57a1-a648-707a4d877824', NULL, 24, 24, 'For my sighing comes before I eat. My groanings are poured out like water.'),
  ('2d55da2d-8db9-538f-a4bd-c6d513fa22c1', '825297e1-149a-57a1-a648-707a4d877824', NULL, 25, 25, 'For the thing which I fear comes on me, That which I am afraid of comes to me.'),
  ('59c422fc-414a-5475-a87b-e126f031bcdf', '825297e1-149a-57a1-a648-707a4d877824', NULL, 26, 26, 'I am not at ease, neither am I quiet, neither have I rest; but trouble comes."'),
  ('d7e6a7bd-bc2b-52aa-a7e8-0e6705e9c93a', 'b115d650-3947-5ec9-a5ca-5dff91284ebe', NULL, 1, 1, 'Then Eliphaz the Temanite answered,'),
  ('3f26a212-cf69-5c9e-ae51-c5647e33ed3a', 'b115d650-3947-5ec9-a5ca-5dff91284ebe', NULL, 2, 2, '"If someone ventures to talk with you, will you be grieved? But who can withhold himself from speaking?'),
  ('785adeba-c261-55df-aa98-e34924db1ac9', 'b115d650-3947-5ec9-a5ca-5dff91284ebe', NULL, 3, 3, 'Behold, you have instructed many, you have strengthened the weak hands.'),
  ('9c49842c-ca43-511d-a5bf-7bf9814f4a00', 'b115d650-3947-5ec9-a5ca-5dff91284ebe', NULL, 4, 4, 'Your words have supported him who was falling, You have made firm the feeble knees.'),
  ('12594ffd-175c-5438-a736-2619eaf67d04', 'b115d650-3947-5ec9-a5ca-5dff91284ebe', NULL, 5, 5, 'But now it is come to you, and you faint. It touches you, and you are troubled.'),
  ('1406bf88-b4a5-5789-ab32-48a65a31084b', 'b115d650-3947-5ec9-a5ca-5dff91284ebe', NULL, 6, 6, 'Isn''t your piety your confidence? Isn''t the integrity of your ways your hope?'),
  ('7ac684ae-2839-52b4-aa2f-dbd64f0dd287', 'b115d650-3947-5ec9-a5ca-5dff91284ebe', NULL, 7, 7, '"Remember, now, whoever perished, being innocent? Or where were the upright cut off?'),
  ('21e3fa57-7f14-5285-afbb-1ff83395a3a2', 'b115d650-3947-5ec9-a5ca-5dff91284ebe', NULL, 8, 8, 'According to what I have seen, those who plow iniquity, and sow trouble, reap the same.'),
  ('8aa861a9-9c60-5c7a-a857-cff50a10ff34', 'b115d650-3947-5ec9-a5ca-5dff91284ebe', NULL, 9, 9, 'By the breath of God they perish. By the blast of his anger are they consumed.'),
  ('70a53974-6069-5caa-a66e-d43b7295676b', 'b115d650-3947-5ec9-a5ca-5dff91284ebe', NULL, 10, 10, 'The roaring of the lion, and the voice of the fierce lion, the teeth of the young lions, are broken.'),
  ('d8974d3f-4650-5321-a611-4a679b2bf2d3', 'b115d650-3947-5ec9-a5ca-5dff91284ebe', NULL, 11, 11, 'The old lion perishes for lack of prey. The cubs of the lioness are scattered abroad.'),
  ('4a762338-980e-5370-afe7-3578acea144e', 'b115d650-3947-5ec9-a5ca-5dff91284ebe', NULL, 12, 12, '"Now a thing was secretly brought to me. My ear received a whisper of it.'),
  ('8a4ea3d8-bf68-51f2-a002-2d0833848b07', 'b115d650-3947-5ec9-a5ca-5dff91284ebe', NULL, 13, 13, 'In thoughts from the visions of the night, when deep sleep falls on men,'),
  ('42bc466a-434d-599c-a47c-70cf192441a9', 'b115d650-3947-5ec9-a5ca-5dff91284ebe', NULL, 14, 14, 'fear came on me, and trembling, which made all my bones shake.'),
  ('8b63cab9-da9a-53e7-a6bc-ee776742e252', 'b115d650-3947-5ec9-a5ca-5dff91284ebe', NULL, 15, 15, 'Then a spirit passed before my face. The hair of my flesh stood up.'),
  ('c9c4e716-4615-5b5c-ab79-2d25d9577e46', 'b115d650-3947-5ec9-a5ca-5dff91284ebe', NULL, 16, 16, 'It stood still, but I couldn''t discern its appearance. A form was before my eyes. Silence, then I heard a voice, saying,'),
  ('82c0e65a-0f80-5734-a741-69c9bf4f7a00', 'b115d650-3947-5ec9-a5ca-5dff91284ebe', NULL, 17, 17, '''Shall mortal man be more just than God? Shall a man be more pure than his Maker?'),
  ('358c30b0-512e-5fe6-a786-283d2842fe0e', 'b115d650-3947-5ec9-a5ca-5dff91284ebe', NULL, 18, 18, 'Behold, he puts no trust in his servants. He charges his angels with error.'),
  ('ee1e72cd-0f18-599f-af2c-63397361e6e3', 'b115d650-3947-5ec9-a5ca-5dff91284ebe', NULL, 19, 19, 'How much more, those who dwell in houses of clay, whose foundation is in the dust, who are crushed before the moth!'),
  ('b7e7131c-ab53-5cbc-a0e2-a2705351d159', 'b115d650-3947-5ec9-a5ca-5dff91284ebe', NULL, 20, 20, 'Between morning and evening they are destroyed. They perish forever without any regarding it.'),
  ('7b28ea19-7298-5c72-a01e-ba1e581ba92b', 'b115d650-3947-5ec9-a5ca-5dff91284ebe', NULL, 21, 21, 'Isn''t their tent cord plucked up within them? They die, and that without wisdom.'''),
  ('d5883056-e831-542d-ae6a-c14a1db4df57', '8d46e2ef-6549-5795-a683-96b513f3be8b', NULL, 1, 1, '"Call now; is there any who will answer you? To which of the holy ones will you turn?'),
  ('f12c937b-559f-5f53-ab04-7393c1b71953', '8d46e2ef-6549-5795-a683-96b513f3be8b', NULL, 2, 2, 'For resentment kills the foolish man, and jealousy kills the simple.'),
  ('d54c0147-5405-5c1c-ae5e-9b3462a900e6', '8d46e2ef-6549-5795-a683-96b513f3be8b', NULL, 3, 3, 'I have seen the foolish taking root, but suddenly I cursed his habitation.'),
  ('0fb2169d-f9ea-5acd-a3e4-7d00bb5525ca', '8d46e2ef-6549-5795-a683-96b513f3be8b', NULL, 4, 4, 'His children are far from safety. They are crushed in the gate. Neither is there any to deliver them,'),
  ('5a086e0e-3f2c-5a1a-a499-4ea60a149edc', '8d46e2ef-6549-5795-a683-96b513f3be8b', NULL, 5, 5, 'whose harvest the hungry eats up, and take it even out of the thorns. The snare gapes for their substance.'),
  ('15a53929-1cd1-56e9-a275-26e88b777fd6', '8d46e2ef-6549-5795-a683-96b513f3be8b', NULL, 6, 6, 'For affliction doesn''t come forth from the dust, neither does trouble spring out of the ground;'),
  ('2c92fa1d-a166-5f09-ab24-b4e30cde6407', '8d46e2ef-6549-5795-a683-96b513f3be8b', NULL, 7, 7, 'but man is born to trouble, as the sparks fly upward.'),
  ('19c59d52-8716-5847-a336-a6caeebf0b0f', '8d46e2ef-6549-5795-a683-96b513f3be8b', NULL, 8, 8, '"But as for me, I would seek God. I would commit my cause to God,'),
  ('b341e4ef-6057-56dd-a11a-88ca2bda2388', '8d46e2ef-6549-5795-a683-96b513f3be8b', NULL, 9, 9, 'who does great things that can''t be fathomed, marvelous things without number;'),
  ('f4c8ed4b-9944-5e34-a937-d7f32fd6e94a', '8d46e2ef-6549-5795-a683-96b513f3be8b', NULL, 10, 10, 'who gives rain on the earth, and sends waters on the fields;'),
  ('d1ba2143-6a7f-5897-a1b8-7dc6dc1e75b1', '8d46e2ef-6549-5795-a683-96b513f3be8b', NULL, 11, 11, 'so that he sets up on high those who are low, those who mourn are exalted to safety.'),
  ('4166abb8-071b-578c-adeb-ebb8162db127', '8d46e2ef-6549-5795-a683-96b513f3be8b', NULL, 12, 12, 'He frustrates the devices of the crafty, So that their hands can''t perform their enterprise.'),
  ('31f06574-250d-5744-a0dd-3e282141ce64', '8d46e2ef-6549-5795-a683-96b513f3be8b', NULL, 13, 13, 'He takes the wise in their own craftiness; the counsel of the cunning is carried headlong.'),
  ('729b3be7-a8c3-5977-af4e-ad469056272e', '8d46e2ef-6549-5795-a683-96b513f3be8b', NULL, 14, 14, 'They meet with darkness in the day time, and grope at noonday as in the night.'),
  ('ca08b301-5ec7-55fa-a7e7-ff88816f4990', '8d46e2ef-6549-5795-a683-96b513f3be8b', NULL, 15, 15, 'But he saves from the sword of their mouth, even the needy from the hand of the mighty.'),
  ('a593e488-4221-5935-a7ff-fc9a10e5f4e5', '8d46e2ef-6549-5795-a683-96b513f3be8b', NULL, 16, 16, 'So the poor has hope, and injustice shuts her mouth.'),
  ('21a382cc-d59b-51c0-afb6-2264756aa6c6', '8d46e2ef-6549-5795-a683-96b513f3be8b', NULL, 17, 17, '"Behold, happy is the man whom God corrects. Therefore do not despise the chastening of the Almighty.'),
  ('c07c1f06-c113-5a69-a751-7b03a72e2092', '8d46e2ef-6549-5795-a683-96b513f3be8b', NULL, 18, 18, 'For he wounds, and binds up. He injures, and his hands make whole.'),
  ('582b2852-2a68-5d2c-a990-daa52ff65b6d', '8d46e2ef-6549-5795-a683-96b513f3be8b', NULL, 19, 19, 'He will deliver you in six troubles; yes, in seven no evil shall touch you.'),
  ('32128e9a-0112-57a1-a62d-ebc24d6c39c4', '8d46e2ef-6549-5795-a683-96b513f3be8b', NULL, 20, 20, 'In famine he will redeem you from death; in war, from the power of the sword.'),
  ('cae8ecc0-4434-5dde-ad3f-ea957593c70a', '8d46e2ef-6549-5795-a683-96b513f3be8b', NULL, 21, 21, 'You shall be hidden from the scourge of the tongue, neither shall you be afraid of destruction when it comes.'),
  ('8a48ada8-c857-5904-aa48-a08bb629478d', '8d46e2ef-6549-5795-a683-96b513f3be8b', NULL, 22, 22, 'At destruction and famine you shall laugh, neither shall you be afraid of the animals of the earth.'),
  ('5123ee5a-798f-5be6-a799-d0a3244046f0', '8d46e2ef-6549-5795-a683-96b513f3be8b', NULL, 23, 23, 'For you shall be allied with the stones of the field. The animals of the field shall be at peace with you.'),
  ('10e35c80-195d-5d8f-a419-0bff91673c4e', '8d46e2ef-6549-5795-a683-96b513f3be8b', NULL, 24, 24, 'You shall know that your tent is in peace. You shall visit your fold, and shall miss nothing.'),
  ('9d3ea450-9304-5a1a-ae22-d76479d71aad', '8d46e2ef-6549-5795-a683-96b513f3be8b', NULL, 25, 25, 'You shall know also that your seed shall be great, Your offspring as the grass of the earth.'),
  ('b1b2f299-9207-5c42-aa42-374beb0129d7', '8d46e2ef-6549-5795-a683-96b513f3be8b', NULL, 26, 26, 'You shall come to your grave in a full age, like a shock of grain comes in its season.'),
  ('8556448a-27db-5a93-a854-ec453e0ecf54', '8d46e2ef-6549-5795-a683-96b513f3be8b', NULL, 27, 27, 'Look this, we have searched it, so it is. Hear it, and know it for your good."'),
  ('f52c0bfc-a921-593e-aaeb-9a915b06945c', '1a717cc5-c17c-5153-ad09-24eb3b66fe19', NULL, 1, 1, 'Then Job answered,'),
  ('51ff257a-0f3e-5b65-ad94-e67f59f12edc', '1a717cc5-c17c-5153-ad09-24eb3b66fe19', NULL, 2, 2, '"Oh that my anguish were weighed, and all my calamity laid in the balances!'),
  ('47a4d63b-550f-5fca-a22e-abae640fd7a9', '1a717cc5-c17c-5153-ad09-24eb3b66fe19', NULL, 3, 3, 'For now it would be heavier than the sand of the seas, therefore have my words been rash.'),
  ('522d4bac-5875-5ff9-a9c8-cc184955e571', '1a717cc5-c17c-5153-ad09-24eb3b66fe19', NULL, 4, 4, 'For the arrows of the Almighty are within me. My spirit drinks up their poison. The terrors of God set themselves in array against me.'),
  ('c5772f2e-6de7-5257-a9b6-e6407d992c88', '1a717cc5-c17c-5153-ad09-24eb3b66fe19', NULL, 5, 5, 'Does the wild donkey bray when he has grass? Or does the ox low over his fodder?'),
  ('547c4ca8-317d-51aa-a731-e58e60245277', '1a717cc5-c17c-5153-ad09-24eb3b66fe19', NULL, 6, 6, 'Can that which has no flavor be eaten without salt? Or is there any taste in the white of an egg?'),
  ('06298afd-6444-5880-aa41-bde9f6cf2c03', '1a717cc5-c17c-5153-ad09-24eb3b66fe19', NULL, 7, 7, 'My soul refuses to touch them. They are as loathsome food to me.'),
  ('2ec167f1-7608-5ad8-a135-ff4a182e7ef2', '1a717cc5-c17c-5153-ad09-24eb3b66fe19', NULL, 8, 8, '"Oh that I might have my request, that God would grant the thing that I long for,'),
  ('0bf86c6e-748f-513e-a611-a12da13511ee', '1a717cc5-c17c-5153-ad09-24eb3b66fe19', NULL, 9, 9, 'even that it would please God to crush me; that he would let loose his hand, and cut me off!'),
  ('8425d83f-7ab2-5c97-a4ed-7b66c8917110', '1a717cc5-c17c-5153-ad09-24eb3b66fe19', NULL, 10, 10, 'Be it still my consolation, yes, let me exult in pain that doesn''t spare, that I have not denied the words of the Holy One.'),
  ('4d311565-627d-5a52-afdc-087fdd554e4e', '1a717cc5-c17c-5153-ad09-24eb3b66fe19', NULL, 11, 11, 'What is my strength, that I should wait? What is my end, that I should be patient?'),
  ('7e5ec458-f9c9-5c8c-ac38-85bed09bfef3', '1a717cc5-c17c-5153-ad09-24eb3b66fe19', NULL, 12, 12, 'Is my strength the strength of stones? Or is my flesh of brass?'),
  ('563872e8-37da-50d3-a299-e140797ceec7', '1a717cc5-c17c-5153-ad09-24eb3b66fe19', NULL, 13, 13, 'Isn''t it that I have no help in me, That wisdom is driven quite from me?'),
  ('7718d991-7f68-5284-a7f7-02527964f88e', '1a717cc5-c17c-5153-ad09-24eb3b66fe19', NULL, 14, 14, '"To him who is ready to faint, kindness should be shown from his friend; even to him who forsakes the fear of the Almighty.'),
  ('651db46a-3c3a-57cf-aba1-64ace7880c23', '1a717cc5-c17c-5153-ad09-24eb3b66fe19', NULL, 15, 15, 'My brothers have dealt deceitfully as a brook, as the channel of brooks that pass away;'),
  ('ab8ae0d3-5daa-5219-a6a9-c2328815ab63', '1a717cc5-c17c-5153-ad09-24eb3b66fe19', NULL, 16, 16, 'Which are black by reason of the ice, in which the snow hides itself.'),
  ('cc82e40d-bb4a-5dde-a7f1-0a2e2be6df49', '1a717cc5-c17c-5153-ad09-24eb3b66fe19', NULL, 17, 17, 'In the dry season, they vanish. When it is hot, they are consumed out of their place.'),
  ('536c3190-219d-5a8a-a08f-6c32fada355f', '1a717cc5-c17c-5153-ad09-24eb3b66fe19', NULL, 18, 18, 'The caravans that travel beside them turn aside. They go up into the waste, and perish.'),
  ('c4750e48-68ae-5fbd-a6b6-4fc9b51334eb', '1a717cc5-c17c-5153-ad09-24eb3b66fe19', NULL, 19, 19, 'The caravans of Tema looked. The companies of Sheba waited for them.'),
  ('30317e06-e64a-5ab2-a5dc-d395a8c925a4', '1a717cc5-c17c-5153-ad09-24eb3b66fe19', NULL, 20, 20, 'They were distressed because they were confident. They came there, and were confounded.'),
  ('443c1897-ca24-5533-aaa1-504e63e6613a', '1a717cc5-c17c-5153-ad09-24eb3b66fe19', NULL, 21, 21, 'For now you are nothing. You see a terror, and are afraid.'),
  ('ef049e75-dde9-516f-a00a-be0267ee296f', '1a717cc5-c17c-5153-ad09-24eb3b66fe19', NULL, 22, 22, 'Did I say, ''Give to me?'' or, ''Offer a present for me from your substance?'''),
  ('13071e97-ae7e-51c1-aa4d-ce7cd8c2b3a1', '1a717cc5-c17c-5153-ad09-24eb3b66fe19', NULL, 23, 23, 'or, ''Deliver me from the adversary''s hand?'' or, ''Redeem me from the hand of the oppressors?'''),
  ('d5583c04-24f3-5724-af30-5f3a867f0d81', '1a717cc5-c17c-5153-ad09-24eb3b66fe19', NULL, 24, 24, '"Teach me, and I will hold my peace. Cause me to understand wherein I have erred.'),
  ('914f6cbe-34a9-51b7-af9c-242ca670a802', '1a717cc5-c17c-5153-ad09-24eb3b66fe19', NULL, 25, 25, 'How forcible are words of uprightness! But your reproof, what does it reprove?'),
  ('d15b40ff-3319-5987-a40f-96508db2e412', '1a717cc5-c17c-5153-ad09-24eb3b66fe19', NULL, 26, 26, 'Do you intend to reprove words, since the speeches of one who is desperate are as wind?'),
  ('45fd03ff-bb08-51aa-a6ec-8919966f6b30', '1a717cc5-c17c-5153-ad09-24eb3b66fe19', NULL, 27, 27, 'Yes, you would even cast lots for the fatherless, and make merchandise of your friend.'),
  ('8c52384c-6040-5a5a-aa0d-491256e45a63', '1a717cc5-c17c-5153-ad09-24eb3b66fe19', NULL, 28, 28, 'Now therefore be pleased to look at me, for surely I shall not lie to your face.'),
  ('3ae6b107-460d-53f2-a401-1b361301a82d', '1a717cc5-c17c-5153-ad09-24eb3b66fe19', NULL, 29, 29, 'Please return. Let there be no injustice. Yes, return again. My cause is righteous.'),
  ('931f148a-9b96-5790-acb8-c2359f4e5946', '1a717cc5-c17c-5153-ad09-24eb3b66fe19', NULL, 30, 30, 'Is there injustice on my tongue? Can''t my taste discern mischievous things?'),
  ('afa0d31b-0584-5ef4-a6a6-9b6a8a6cc856', 'd7583b8a-9891-5f4a-ada4-71acc1d86d9d', NULL, 1, 1, '"Isn''t a man forced to labor on earth? Aren''t his days like the days of a hired hand?'),
  ('9ab702ea-a354-53ea-a4f7-3058e3b5ca29', 'd7583b8a-9891-5f4a-ada4-71acc1d86d9d', NULL, 2, 2, 'As a servant who earnestly desires the shadow, as a hireling who looks for his wages,'),
  ('3d0f2074-8c2c-5668-ad26-d7c5bc97b118', 'd7583b8a-9891-5f4a-ada4-71acc1d86d9d', NULL, 3, 3, 'so am I made to possess months of misery, wearisome nights are appointed to me.'),
  ('3255c268-ae36-5016-a9cc-7d3096ec5db5', 'd7583b8a-9891-5f4a-ada4-71acc1d86d9d', NULL, 4, 4, 'When I lie down, I say, ''When shall I arise, and the night be gone?'' I toss and turn until the dawning of the day.'),
  ('855b7844-adda-5c8a-ab34-d490b8670c31', 'd7583b8a-9891-5f4a-ada4-71acc1d86d9d', NULL, 5, 5, 'My flesh is clothed with worms and clods of dust. My skin closes up, and breaks out afresh.'),
  ('35da0def-0c1b-5973-acdd-d8840738e5ab', 'd7583b8a-9891-5f4a-ada4-71acc1d86d9d', NULL, 6, 6, 'My days are swifter than a weaver''s shuttle, and are spent without hope.'),
  ('e1ff25ae-5786-53be-a87e-7a07e90be74c', 'd7583b8a-9891-5f4a-ada4-71acc1d86d9d', NULL, 7, 7, 'Oh remember that my life is a breath. My eye shall no more see good.'),
  ('cd44e7b0-ed17-5096-ad1f-efb795c20d64', 'd7583b8a-9891-5f4a-ada4-71acc1d86d9d', NULL, 8, 8, 'The eye of him who sees me shall see me no more. Your eyes shall be on me, but I shall not be.'),
  ('03103e72-ad1d-56bd-afaa-5e2707f9914a', 'd7583b8a-9891-5f4a-ada4-71acc1d86d9d', NULL, 9, 9, 'As the cloud is consumed and vanishes away, so he who goes down to Sheol shall come up no more.'),
  ('97faac4d-a38e-5bea-ad54-9ab80595f797', 'd7583b8a-9891-5f4a-ada4-71acc1d86d9d', NULL, 10, 10, 'He shall return no more to his house, neither shall his place know him any more.'),
  ('54f2844a-0289-5933-a674-b8bafb248f23', 'd7583b8a-9891-5f4a-ada4-71acc1d86d9d', NULL, 11, 11, '"Therefore I will not keep silent. I will speak in the anguish of my spirit. I will complain in the bitterness of my soul.'),
  ('d26fbc62-1e7c-50b9-ab1b-4b3a2a22fc92', 'd7583b8a-9891-5f4a-ada4-71acc1d86d9d', NULL, 12, 12, 'Am I a sea, or a sea monster, that you put a guard over me?'),
  ('f15fb728-821a-59cf-a112-7b298bc63d75', 'd7583b8a-9891-5f4a-ada4-71acc1d86d9d', NULL, 13, 13, 'When I say, ''My bed shall comfort me. My couch shall ease my complaint;'''),
  ('bd39c6c0-7f86-567c-ae2c-4168ab1ec85f', 'd7583b8a-9891-5f4a-ada4-71acc1d86d9d', NULL, 14, 14, 'then you scare me with dreams, and terrify me through visions:'),
  ('1ae89231-b08f-5de0-a343-9a358c1542b4', 'd7583b8a-9891-5f4a-ada4-71acc1d86d9d', NULL, 15, 15, 'so that my soul chooses strangling, death rather than my bones.'),
  ('d7775ee8-80ba-56f2-a7c1-665e0373bd7a', 'd7583b8a-9891-5f4a-ada4-71acc1d86d9d', NULL, 16, 16, 'I loathe my life. I don''t want to live forever. Leave me alone, for my days are but a breath.'),
  ('ddd57522-d657-5b88-a26e-78bc4b1b61c0', 'd7583b8a-9891-5f4a-ada4-71acc1d86d9d', NULL, 17, 17, 'What is man, that you should magnify him, that you should set your mind on him,'),
  ('e114f593-30e6-5026-a5c2-8afd30b1da8b', 'd7583b8a-9891-5f4a-ada4-71acc1d86d9d', NULL, 18, 18, 'that you should visit him every morning, and test him every moment?'),
  ('c1170cc8-6550-5ae2-a4cf-4a25056c6527', 'd7583b8a-9891-5f4a-ada4-71acc1d86d9d', NULL, 19, 19, 'How long will you not look away from me, nor leave me alone until I swallow down my spittle?'),
  ('ee859c1d-1b9c-50c8-a968-d7c58c9620e4', 'd7583b8a-9891-5f4a-ada4-71acc1d86d9d', NULL, 20, 20, 'If I have sinned, what do I do to you, you watcher of men? Why have you set me as a mark for you, so that I am a burden to myself?'),
  ('894195f7-f51a-55d6-abf3-5613b192be90', 'd7583b8a-9891-5f4a-ada4-71acc1d86d9d', NULL, 21, 21, 'Why do you not pardon my disobedience, and take away my iniquity? For now shall I lie down in the dust. You will seek me diligently, but I shall not be."'),
  ('8ec83cc7-18c4-56f9-a364-e53a2b611ce9', '72327e98-38ea-5ed3-a6dd-8752894bec04', NULL, 1, 1, 'Then Bildad the Shuhite answered,'),
  ('ff5000cf-f917-5e3e-aa80-46f033fd4bd8', '72327e98-38ea-5ed3-a6dd-8752894bec04', NULL, 2, 2, '"How long will you speak these things? Shall the words of your mouth be a mighty wind?'),
  ('0b9d418d-aa68-5ac9-a419-96ee83116120', '72327e98-38ea-5ed3-a6dd-8752894bec04', NULL, 3, 3, 'Does God pervert justice? Or does the Almighty pervert righteousness?'),
  ('d011069d-f33d-5b57-a34c-07131e8926af', '72327e98-38ea-5ed3-a6dd-8752894bec04', NULL, 4, 4, 'If your children have sinned against him, He has delivered them into the hand of their disobedience.'),
  ('b0cc3e14-ab45-542a-ae7c-12ff55b9b2f3', '72327e98-38ea-5ed3-a6dd-8752894bec04', NULL, 5, 5, 'If you want to seek God diligently, make your supplication to the Almighty.'),
  ('dcdccf78-ffa3-5e30-a6a2-15e16e2ac25c', '72327e98-38ea-5ed3-a6dd-8752894bec04', NULL, 6, 6, 'If you were pure and upright, surely now he would awaken for you, and make the habitation of your righteousness prosperous.'),
  ('5ea53727-4069-5227-a01c-70d6192a2b16', '72327e98-38ea-5ed3-a6dd-8752894bec04', NULL, 7, 7, 'Though your beginning was small, yet your latter end would greatly increase.'),
  ('56066635-7694-58b0-a051-64dab015d2dc', '72327e98-38ea-5ed3-a6dd-8752894bec04', NULL, 8, 8, '"Please inquire of past generations. Find out about the learning of their fathers.'),
  ('bdce26d5-030c-548b-a823-aea9180e76ca', '72327e98-38ea-5ed3-a6dd-8752894bec04', NULL, 9, 9, '(For we are but of yesterday, and know nothing, because our days on earth are a shadow.)'),
  ('45748f52-853b-55aa-a1ba-b6879588c969', '72327e98-38ea-5ed3-a6dd-8752894bec04', NULL, 10, 10, 'Shall they not teach you, tell you, and utter words out of their heart?'),
  ('32ecf550-93b1-5c02-ae5a-883c8dd5f6fb', '72327e98-38ea-5ed3-a6dd-8752894bec04', NULL, 11, 11, '"Can the papyrus grow up without mire? Can the rushes grow without water?'),
  ('92766293-0a59-52dc-a70f-9be483a9afe7', '72327e98-38ea-5ed3-a6dd-8752894bec04', NULL, 12, 12, 'While it is yet in its greenness, not cut down, it withers before any other reed.'),
  ('93e386be-989d-582e-af1b-e28ac3e106ed', '72327e98-38ea-5ed3-a6dd-8752894bec04', NULL, 13, 13, 'So are the paths of all who forget God. The hope of the godless man shall perish,'),
  ('eb7d46b3-b506-56fe-ac6d-816173819f2b', '72327e98-38ea-5ed3-a6dd-8752894bec04', NULL, 14, 14, 'Whose confidence shall break apart, Whose trust is a spider''s web.'),
  ('dc1c83c4-8971-53f2-ae1f-c4505e572f95', '72327e98-38ea-5ed3-a6dd-8752894bec04', NULL, 15, 15, 'He shall lean on his house, but it shall not stand. He shall cling to it, but it shall not endure.'),
  ('a65e67e0-d1ce-5cfa-ae81-f4f01a645b56', '72327e98-38ea-5ed3-a6dd-8752894bec04', NULL, 16, 16, 'He is green before the sun. His shoots go forth over his garden.'),
  ('0c78d1f4-fca3-5a92-a598-e7079351a658', '72327e98-38ea-5ed3-a6dd-8752894bec04', NULL, 17, 17, 'His roots are wrapped around the rock pile. He sees the place of stones.'),
  ('db0cbf3e-8128-58c8-aa29-6853e84c02ba', '72327e98-38ea-5ed3-a6dd-8752894bec04', NULL, 18, 18, 'If he is destroyed from his place, then it shall deny him, saying, ''I have not seen you.'''),
  ('d0174222-11d1-5b16-ae15-0f5e51b50ccb', '72327e98-38ea-5ed3-a6dd-8752894bec04', NULL, 19, 19, 'Behold, this is the joy of his way: out of the earth, others shall spring.'),
  ('730a0ef3-aa80-5515-a673-71b79d01c888', '72327e98-38ea-5ed3-a6dd-8752894bec04', NULL, 20, 20, '"Behold, God will not cast away a blameless man, neither will he uphold the evildoers.'),
  ('a684fe9e-4121-534e-a108-a18008c5db3b', '72327e98-38ea-5ed3-a6dd-8752894bec04', NULL, 21, 21, 'He will still fill your mouth with laughter, your lips with shouting.'),
  ('dd65eda9-55b5-5cf6-a101-943d108dcd1d', '72327e98-38ea-5ed3-a6dd-8752894bec04', NULL, 22, 22, 'Those who hate you shall be clothed with shame. The tent of the wicked shall be no more."'),
  ('0211f3bc-84ef-5851-aabc-d2bbf53ba8ad', 'b803ca73-6fd6-5101-ac55-1f18768e843a', NULL, 1, 1, 'Then Job answered,'),
  ('8a9bf049-f6d3-55ba-a349-9fe7c68e0105', 'b803ca73-6fd6-5101-ac55-1f18768e843a', NULL, 2, 2, '"Truly I know that it is so, but how can man be just with God?'),
  ('5d23c73d-9d6f-5976-ac66-abedad899204', 'b803ca73-6fd6-5101-ac55-1f18768e843a', NULL, 3, 3, 'If he is pleased to contend with him, he can''t answer him one time in a thousand.'),
  ('0469da42-ab6e-57aa-ad53-3c581acb4282', 'b803ca73-6fd6-5101-ac55-1f18768e843a', NULL, 4, 4, 'God who is wise in heart, and mighty in strength: who has hardened himself against him, and prospered?'),
  ('dbb70173-094a-57fb-ac31-b3b141c05469', 'b803ca73-6fd6-5101-ac55-1f18768e843a', NULL, 5, 5, 'He removes the mountains, and they don''t know it, when he overturns them in his anger.'),
  ('ad2308ac-f620-5a8f-a505-f585de405141', 'b803ca73-6fd6-5101-ac55-1f18768e843a', NULL, 6, 6, 'He shakes the earth out of its place. Its pillars tremble.'),
  ('21d9bb49-2503-5563-a27a-3cb80bec518d', 'b803ca73-6fd6-5101-ac55-1f18768e843a', NULL, 7, 7, 'He commands the sun, and it doesn''t rise, and seals up the stars.'),
  ('017894b3-dc67-5b45-a733-ae3ac561cf5c', 'b803ca73-6fd6-5101-ac55-1f18768e843a', NULL, 8, 8, 'He alone stretches out the heavens, and treads on the waves of the sea.'),
  ('9733ad1f-b475-5f81-acb5-a14d45c20696', 'b803ca73-6fd6-5101-ac55-1f18768e843a', NULL, 9, 9, 'He makes the Bear, Orion, and the Pleiades, and the rooms of the south.'),
  ('6a240a70-7783-57bd-a925-3b21b310923b', 'b803ca73-6fd6-5101-ac55-1f18768e843a', NULL, 10, 10, 'He does great things past finding out; yes, marvelous things without number.'),
  ('0024e237-9dd8-54c2-ad77-c4a87aa53c2d', 'b803ca73-6fd6-5101-ac55-1f18768e843a', NULL, 11, 11, 'Behold, he goes by me, and I don''t see him. He passes on also, but I don''t perceive him.'),
  ('fa527680-d474-5df9-aa1f-5b042de40e1a', 'b803ca73-6fd6-5101-ac55-1f18768e843a', NULL, 12, 12, 'Behold, he snatches away. Who can hinder him? Who will ask him, ''What are you doing?'''),
  ('81c4a486-5fe2-5c71-ab92-8bd20d58cd12', 'b803ca73-6fd6-5101-ac55-1f18768e843a', NULL, 13, 13, '"God will not withdraw his anger. The helpers of Rahab stoop under him.'),
  ('09e95bdd-851d-5717-a406-01105fe84674', 'b803ca73-6fd6-5101-ac55-1f18768e843a', NULL, 14, 14, 'How much less shall I answer him, And choose my words to argue with him?'),
  ('40785aa5-fd9e-5ea8-af96-dfba06e44071', 'b803ca73-6fd6-5101-ac55-1f18768e843a', NULL, 15, 15, 'Though I were righteous, yet I wouldn''t answer him. I would make supplication to my judge.'),
  ('04ec86cf-2d63-5e99-ac37-63b4677098d0', 'b803ca73-6fd6-5101-ac55-1f18768e843a', NULL, 16, 16, 'If I had called, and he had answered me, yet I wouldn''t believe that he listened to my voice.'),
  ('c531bfff-a6b7-598c-ac63-8edc7a29b19e', 'b803ca73-6fd6-5101-ac55-1f18768e843a', NULL, 17, 17, 'For he breaks me with a storm, and multiplies my wounds without cause.'),
  ('c5fb3c48-316e-537d-a85c-34d60eb4a058', 'b803ca73-6fd6-5101-ac55-1f18768e843a', NULL, 18, 18, 'He will not allow me to catch my breath, but fills me with bitterness.'),
  ('8e167019-b8e5-58d7-ad7f-d63b7d257cc7', 'b803ca73-6fd6-5101-ac55-1f18768e843a', NULL, 19, 19, 'If it is a matter of strength, behold, he is mighty! If of justice, ''Who,'' says he, ''will summon me?'''),
  ('d88a58e1-401f-5def-aae3-cfa4b1e0acf8', 'b803ca73-6fd6-5101-ac55-1f18768e843a', NULL, 20, 20, 'Though I am righteous, my own mouth shall condemn me. Though I am blameless, it shall prove me perverse.'),
  ('a19c5f37-3698-5710-a4a4-792b731e65be', 'b803ca73-6fd6-5101-ac55-1f18768e843a', NULL, 21, 21, 'I am blameless. I don''t respect myself. I despise my life.'),
  ('ebbff9df-28ce-5b75-a2e5-f9e173e53295', 'b803ca73-6fd6-5101-ac55-1f18768e843a', NULL, 22, 22, '"It is all the same. Therefore I say he destroys the blameless and the wicked.'),
  ('32c19d04-1d35-5ba3-a823-9b112acdf8b3', 'b803ca73-6fd6-5101-ac55-1f18768e843a', NULL, 23, 23, 'If the scourge kills suddenly, he will mock at the trial of the innocent.'),
  ('730d7373-07a0-51f2-aacf-46ec8be2a46c', 'b803ca73-6fd6-5101-ac55-1f18768e843a', NULL, 24, 24, 'The earth is given into the hand of the wicked. He covers the faces of its judges. If not he, then who is it?'),
  ('48ccfcf0-b4a7-53bc-ac2d-263f7acc2e24', 'b803ca73-6fd6-5101-ac55-1f18768e843a', NULL, 25, 25, '"Now my days are swifter than a runner. They flee away, they see no good,'),
  ('54e1112f-6f82-5ae4-a584-25eb49abe1b4', 'b803ca73-6fd6-5101-ac55-1f18768e843a', NULL, 26, 26, 'They have passed away as the swift ships, as the eagle that swoops on the prey.'),
  ('7c00c72f-8315-59db-a783-04889d594137', 'b803ca73-6fd6-5101-ac55-1f18768e843a', NULL, 27, 27, 'If I say, ''I will forget my complaint, I will put off my sad face, and cheer up;'''),
  ('d17e3205-6a12-5711-abf9-acf7b3503e41', 'b803ca73-6fd6-5101-ac55-1f18768e843a', NULL, 28, 28, 'I am afraid of all my sorrows, I know that you will not hold me innocent.'),
  ('18f013be-f097-507f-a1d8-051ecafcd4af', 'b803ca73-6fd6-5101-ac55-1f18768e843a', NULL, 29, 29, 'I shall be condemned. Why then do I labor in vain?'),
  ('f49f0e18-026a-5822-a819-bff452965be7', 'b803ca73-6fd6-5101-ac55-1f18768e843a', NULL, 30, 30, 'If I wash myself with snow, and cleanse my hands with lye,'),
  ('cb3a527c-5074-556b-a7d7-3c55e4606698', 'b803ca73-6fd6-5101-ac55-1f18768e843a', NULL, 31, 31, 'yet you will plunge me in the ditch. My own clothes shall abhor me.'),
  ('cbae48aa-9685-5e50-a934-7a137da688a6', 'b803ca73-6fd6-5101-ac55-1f18768e843a', NULL, 32, 32, 'For he is not a man, as I am, that I should answer him, that we should come together in judgment.'),
  ('bda02e8b-c0d4-5aa9-a385-183ef74b0578', 'b803ca73-6fd6-5101-ac55-1f18768e843a', NULL, 33, 33, 'There is no umpire between us, that might lay his hand on us both.'),
  ('46981a41-6047-553b-a44b-5487b13de4f8', 'b803ca73-6fd6-5101-ac55-1f18768e843a', NULL, 34, 34, 'Let him take his rod away from me. Let his terror not make me afraid;'),
  ('5597d4f7-6093-555b-ab78-8f70de2f168a', 'b803ca73-6fd6-5101-ac55-1f18768e843a', NULL, 35, 35, 'then I would speak, and not fear him, for I am not so in myself.'),
  ('25092c50-1ada-5f93-a9c1-e4ac1cf673bd', '2a58b37d-7db1-5432-ab1c-89a58f91d375', NULL, 1, 1, '"My soul is weary of my life. I will give free course to my complaint. I will speak in the bitterness of my soul.'),
  ('769f7909-5d1c-5931-ad4f-f04e829bd08e', '2a58b37d-7db1-5432-ab1c-89a58f91d375', NULL, 2, 2, 'I will tell God, ''Do not condemn me. Show me why you contend with me.'),
  ('bf264589-fb63-5973-a6cd-c97613900e92', '2a58b37d-7db1-5432-ab1c-89a58f91d375', NULL, 3, 3, 'Is it good to you that you should oppress, that you should despise the work of your hands, and smile on the counsel of the wicked?'),
  ('cc877915-f6af-508a-a55d-3b1f8e6e8d72', '2a58b37d-7db1-5432-ab1c-89a58f91d375', NULL, 4, 4, 'Do you have eyes of flesh? Or do you see as man sees?'),
  ('f950deb4-fe46-502b-af29-a6c6f757a716', '2a58b37d-7db1-5432-ab1c-89a58f91d375', NULL, 5, 5, 'Are your days as the days of mortals, or your years as man''s years,'),
  ('3f3a21a2-e6cf-5db6-a442-a65e484d3387', '2a58b37d-7db1-5432-ab1c-89a58f91d375', NULL, 6, 6, 'that you inquire after my iniquity, and search after my sin?'),
  ('defcd58b-9aa6-578d-aea5-c21317873035', '2a58b37d-7db1-5432-ab1c-89a58f91d375', NULL, 7, 7, 'Although you know that I am not wicked, there is no one who can deliver out of your hand.'),
  ('45911416-e522-5dbd-a8da-dcb3b3d932b7', '2a58b37d-7db1-5432-ab1c-89a58f91d375', NULL, 8, 8, '"''Your hands have framed me and fashioned me altogether, yet you destroy me.'),
  ('df7ce93e-87f2-50a6-ad5d-78fc3532ffce', '2a58b37d-7db1-5432-ab1c-89a58f91d375', NULL, 9, 9, 'Remember, I beg you, that you have fashioned me as clay. Will you bring me into dust again?'),
  ('1dfed594-75d6-52ca-ae62-1e2c80a4b948', '2a58b37d-7db1-5432-ab1c-89a58f91d375', NULL, 10, 10, 'Haven''t you poured me out like milk, and curdled me like cheese?'),
  ('899d2fd6-5cf7-5acd-a7c4-5d3d99f6eacd', '2a58b37d-7db1-5432-ab1c-89a58f91d375', NULL, 11, 11, 'You have clothed me with skin and flesh, and knit me together with bones and sinews.'),
  ('bf3d642c-ce79-5eeb-ae96-2b407db35f85', '2a58b37d-7db1-5432-ab1c-89a58f91d375', NULL, 12, 12, 'You have granted me life and loving kindness. Your visitation has preserved my spirit.'),
  ('3d8808ea-17d2-58b8-af8a-3f9384e1ff78', '2a58b37d-7db1-5432-ab1c-89a58f91d375', NULL, 13, 13, 'Yet you hid these things in your heart. I know that this is with you:'),
  ('e88f9bac-f787-59bc-ad22-887f9d02ee60', '2a58b37d-7db1-5432-ab1c-89a58f91d375', NULL, 14, 14, 'if I sin, then you mark me. You will not acquit me from my iniquity.'),
  ('bdd58cd0-7cd8-5dfc-aa99-9a71475c85ed', '2a58b37d-7db1-5432-ab1c-89a58f91d375', NULL, 15, 15, 'If I am wicked, woe to me. If I am righteous, I still shall not lift up my head, being filled with disgrace, and conscious of my affliction.'),
  ('a71f4e13-19e5-5673-a076-24e900f18d46', '2a58b37d-7db1-5432-ab1c-89a58f91d375', NULL, 16, 16, 'If my head is held high, you hunt me like a lion. Again you show yourself powerful to me.'),
  ('33943b44-6de6-5a9d-a269-940f27c3ffe9', '2a58b37d-7db1-5432-ab1c-89a58f91d375', NULL, 17, 17, 'You renew your witnesses against me, and increase your indignation on me. Changes and warfare are with me.'),
  ('c462ced3-b12f-5657-aefa-595d5040581e', '2a58b37d-7db1-5432-ab1c-89a58f91d375', NULL, 18, 18, '"''Why, then, have you brought me forth out of the womb? I wish I had given up the spirit, and no eye had seen me.'),
  ('3bf58547-7d7c-537f-a207-dcd6b6429ca0', '2a58b37d-7db1-5432-ab1c-89a58f91d375', NULL, 19, 19, 'I should have been as though I had not been. I should have been carried from the womb to the grave.'),
  ('cbae300f-b16f-5d98-a552-f9b726f537f5', '2a58b37d-7db1-5432-ab1c-89a58f91d375', NULL, 20, 20, 'Aren''t my days few? Cease then. Leave me alone, that I may find a little comfort,'),
  ('d6f6ee18-574c-5980-a0fa-28d5c7ac0ba0', '2a58b37d-7db1-5432-ab1c-89a58f91d375', NULL, 21, 21, 'before I go where I shall not return from, to the land of darkness and of the shadow of death;'),
  ('f0c63c8c-e8b4-5b34-a0de-6864a70c41af', '2a58b37d-7db1-5432-ab1c-89a58f91d375', NULL, 22, 22, 'the land dark as midnight, of the shadow of death, without any order, where the light is as midnight.''"'),
  ('e710d294-e081-5eb6-acec-a0c5e738bd0b', 'aac59e0b-4c86-5f48-a59b-46d317a8ec2d', NULL, 1, 1, 'Then Zophar, the Naamathite, answered,'),
  ('e7d11c9d-b18f-5fe9-a27d-c0e2945a30df', 'aac59e0b-4c86-5f48-a59b-46d317a8ec2d', NULL, 2, 2, '"Shouldn''t the multitude of words be answered? Should a man full of talk be justified?')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('71a3630d-d57d-53ca-acca-d52941c0fdb2', 'aac59e0b-4c86-5f48-a59b-46d317a8ec2d', NULL, 3, 3, 'Should your boastings make men hold their peace? When you mock, shall no man make you ashamed?'),
  ('ba955d55-64eb-54bf-ad7b-bb0aa531812f', 'aac59e0b-4c86-5f48-a59b-46d317a8ec2d', NULL, 4, 4, 'For you say, ''My doctrine is pure. I am clean in your eyes.'''),
  ('8d923ba7-4ae2-53bc-a765-5ceb29ed6134', 'aac59e0b-4c86-5f48-a59b-46d317a8ec2d', NULL, 5, 5, 'But oh that God would speak, and open his lips against you,'),
  ('64637848-0dc9-5e62-a0b2-157c9fcd66ed', 'aac59e0b-4c86-5f48-a59b-46d317a8ec2d', NULL, 6, 6, 'that he would show you the secrets of wisdom! For true wisdom has two sides. Know therefore that God exacts of you less than your iniquity deserves.'),
  ('60dce84c-8097-5e77-adfc-d169950a3b28', 'aac59e0b-4c86-5f48-a59b-46d317a8ec2d', NULL, 7, 7, '"Can you fathom the mystery of God? Or can you probe the limits of the Almighty?'),
  ('42f9403a-c3a4-5735-a1a6-ef1e82e1dace', 'aac59e0b-4c86-5f48-a59b-46d317a8ec2d', NULL, 8, 8, 'They are high as heaven. What can you do? They are deeper than Sheol. What can you know?'),
  ('ba9af0ec-f908-59e8-a219-239adf09d91b', 'aac59e0b-4c86-5f48-a59b-46d317a8ec2d', NULL, 9, 9, 'Its measure is longer than the earth, and broader than the sea.'),
  ('a4939add-f476-5da6-adaa-8221e6e01819', 'aac59e0b-4c86-5f48-a59b-46d317a8ec2d', NULL, 10, 10, 'If he passes by, or confines, or convenes a court, then who can oppose him?'),
  ('10cbe2ce-a657-583d-a24e-df3d57e16d8e', 'aac59e0b-4c86-5f48-a59b-46d317a8ec2d', NULL, 11, 11, 'For he knows false men. He sees iniquity also, even though he doesn''t consider it.'),
  ('e15e9bf7-c871-5b3a-a2ef-6479f3a41abb', 'aac59e0b-4c86-5f48-a59b-46d317a8ec2d', NULL, 12, 12, 'An empty-headed man becomes wise when a man is born as a wild donkey''s colt.'),
  ('e5ea411d-a6b1-5654-a3f3-dde57ee88225', 'aac59e0b-4c86-5f48-a59b-46d317a8ec2d', NULL, 13, 13, '"If you set your heart aright, stretch out your hands toward him.'),
  ('d2d036de-3521-50ab-a7bf-dbad1d1567fd', 'aac59e0b-4c86-5f48-a59b-46d317a8ec2d', NULL, 14, 14, 'If iniquity is in your hand, put it far away. Don''t let unrighteousness dwell in your tents.'),
  ('96708b25-7897-50b5-ae14-bf791a38b4f0', 'aac59e0b-4c86-5f48-a59b-46d317a8ec2d', NULL, 15, 15, 'Surely then you shall lift up your face without spot; Yes, you shall be steadfast, and shall not fear:'),
  ('cc0baac3-1cb9-5bb5-a065-38439b330f6f', 'aac59e0b-4c86-5f48-a59b-46d317a8ec2d', NULL, 16, 16, 'for you shall forget your misery. You shall remember it as waters that are passed away.'),
  ('d40d350b-bd1a-5f2b-a53b-17cda2e6cfc3', 'aac59e0b-4c86-5f48-a59b-46d317a8ec2d', NULL, 17, 17, 'Life shall be clearer than the noonday. Though there is darkness, it shall be as the morning.'),
  ('2f707d44-a8d5-5a3c-ade2-837abddb0aa7', 'aac59e0b-4c86-5f48-a59b-46d317a8ec2d', NULL, 18, 18, 'You shall be secure, because there is hope. Yes, you shall search, and shall take your rest in safety.'),
  ('5b0bfda5-91cf-59c7-a8f3-2903727ce0bb', 'aac59e0b-4c86-5f48-a59b-46d317a8ec2d', NULL, 19, 19, 'Also you shall lie down, and none shall make you afraid. Yes, many shall court your favor.'),
  ('41dd9b35-290a-5e81-aae8-bffc016ff12b', 'aac59e0b-4c86-5f48-a59b-46d317a8ec2d', NULL, 20, 20, 'But the eyes of the wicked shall fail. They shall have no way to flee. Their hope shall be the giving up of the spirit."'),
  ('f80f643f-6ecb-5386-a8d5-d1d3d0fe7fd9', '47751bed-3089-5fd8-aa89-0535fde15950', NULL, 1, 1, 'Then Job answered,'),
  ('9699aafc-cfb4-5370-ad22-636601b41d52', '47751bed-3089-5fd8-aa89-0535fde15950', NULL, 2, 2, '"No doubt, but you are the people, and wisdom shall die with you.'),
  ('b225c994-1c34-5588-adf3-79ef493d6ea8', '47751bed-3089-5fd8-aa89-0535fde15950', NULL, 3, 3, 'But I have understanding as well as you; I am not inferior to you. Yes, who doesn''t know such things as these?'),
  ('5f43a18c-c38d-58e1-ad32-91a26c897c31', '47751bed-3089-5fd8-aa89-0535fde15950', NULL, 4, 4, 'I am like one who is a joke to his neighbor, I, who called on God, and he answered. The just, the blameless man is a joke.'),
  ('7aedf60d-e004-5a80-ab62-2d8b9a635cf7', '47751bed-3089-5fd8-aa89-0535fde15950', NULL, 5, 5, 'In the thought of him who is at ease there is contempt for misfortune. It is ready for them whose foot slips.'),
  ('d51982ba-1c79-5feb-a10e-27ac27a1fd0f', '47751bed-3089-5fd8-aa89-0535fde15950', NULL, 6, 6, 'The tents of robbers prosper. Those who provoke God are secure, who carry their God in their hands.'),
  ('373727b3-230a-5c76-ab7d-aa4e6b3e9161', '47751bed-3089-5fd8-aa89-0535fde15950', NULL, 7, 7, '"But ask the animals, now, and they shall teach you; the birds of the sky, and they shall tell you.'),
  ('b4ac8d9f-500c-5dc8-af40-5bb63e470a52', '47751bed-3089-5fd8-aa89-0535fde15950', NULL, 8, 8, 'Or speak to the earth, and it shall teach you. The fish of the sea shall declare to you.'),
  ('98abca3c-6f45-5e7c-a0bf-b1829981eeb6', '47751bed-3089-5fd8-aa89-0535fde15950', NULL, 9, 9, 'Who doesn''t know that in all these, the hand of Yahweh has done this,'),
  ('bba20a69-1bbe-5b21-a8ff-0eeb32d5ebaa', '47751bed-3089-5fd8-aa89-0535fde15950', NULL, 10, 10, 'in whose hand is the life of every living thing, and the breath of all mankind?'),
  ('cfe35e30-542f-58c6-ad05-00f5c04a5ca2', '47751bed-3089-5fd8-aa89-0535fde15950', NULL, 11, 11, 'Doesn''t the ear try words, even as the palate tastes its food?'),
  ('e49ce333-f0a0-59c7-a6ce-3ebf8d92b5c5', '47751bed-3089-5fd8-aa89-0535fde15950', NULL, 12, 12, 'With aged men is wisdom, in length of days understanding.'),
  ('6dfedcce-5190-5833-abc4-e6f0ef42af90', '47751bed-3089-5fd8-aa89-0535fde15950', NULL, 13, 13, '"With God is wisdom and might. He has counsel and understanding.'),
  ('a680ff9d-e13a-5e1e-a178-84f1d08ed990', '47751bed-3089-5fd8-aa89-0535fde15950', NULL, 14, 14, 'Behold, he breaks down, and it can''t be built again. He imprisons a man, and there can be no release.'),
  ('d288ab64-bcdf-5d05-a553-b3d9a964d775', '47751bed-3089-5fd8-aa89-0535fde15950', NULL, 15, 15, 'Behold, he withholds the waters, and they dry up. Again, he sends them out, and they overturn the earth.'),
  ('90b4958a-2fc6-536d-a3a4-64534a1cb52a', '47751bed-3089-5fd8-aa89-0535fde15950', NULL, 16, 16, 'With him is strength and wisdom. The deceived and the deceiver are his.'),
  ('5660b564-03be-5014-acda-1ca68407a101', '47751bed-3089-5fd8-aa89-0535fde15950', NULL, 17, 17, 'He leads counselors away stripped. He makes judges fools.'),
  ('d54d1d5d-fc50-5bbc-afc4-c010be564ba8', '47751bed-3089-5fd8-aa89-0535fde15950', NULL, 18, 18, 'He loosens the bond of kings. He binds their waist with a belt.'),
  ('c2f154a2-a6f5-5678-a592-eb34d2a0f0af', '47751bed-3089-5fd8-aa89-0535fde15950', NULL, 19, 19, 'He leads priests away stripped, and overthrows the mighty.'),
  ('5fb91185-5718-578b-a72a-3f81edf590cf', '47751bed-3089-5fd8-aa89-0535fde15950', NULL, 20, 20, 'He removes the speech of those who are trusted, and takes away the understanding of the elders.'),
  ('1337567d-016d-5dd8-a295-9a914e1f3c8e', '47751bed-3089-5fd8-aa89-0535fde15950', NULL, 21, 21, 'He pours contempt on princes, and loosens the belt of the strong.'),
  ('cef1d5b9-81a9-5076-ad80-acb418d0dce5', '47751bed-3089-5fd8-aa89-0535fde15950', NULL, 22, 22, 'He uncovers deep things out of darkness, and brings out to light the shadow of death.'),
  ('b7028ec0-890b-5807-a6c4-13fee77b967e', '47751bed-3089-5fd8-aa89-0535fde15950', NULL, 23, 23, 'He increases the nations, and he destroys them. He enlarges the nations, and he leads them captive.'),
  ('cde59e5e-47ac-5801-aaed-bcd89a9bfcb3', '47751bed-3089-5fd8-aa89-0535fde15950', NULL, 24, 24, 'He takes away understanding from the chiefs of the people of the earth, and causes them to wander in a wilderness where there is no way.'),
  ('9bbe8478-b69d-59b8-a0ab-5813dba9dbd7', '47751bed-3089-5fd8-aa89-0535fde15950', NULL, 25, 25, 'They grope in the dark without light. He makes them stagger like a drunken man.'),
  ('98b9555c-b058-5fec-a72a-da5d17e72cb0', '02f36c2b-0f8d-5ef8-aa81-ebbdc334dba4', NULL, 1, 1, '"Behold, my eye has seen all this. My ear has heard and understood it.'),
  ('0bdcca4c-5640-5baf-a47c-53e7e5a82508', '02f36c2b-0f8d-5ef8-aa81-ebbdc334dba4', NULL, 2, 2, 'What you know, I know also. I am not inferior to you.'),
  ('600ad4c6-a8f8-5e26-a32d-44fa5018c10f', '02f36c2b-0f8d-5ef8-aa81-ebbdc334dba4', NULL, 3, 3, '"Surely I would speak to the Almighty. I desire to reason with God.'),
  ('851f57ac-027d-5c78-a394-f38a43fbaf8b', '02f36c2b-0f8d-5ef8-aa81-ebbdc334dba4', NULL, 4, 4, 'But you are forgers of lies. You are all physicians of no value.'),
  ('956cebe5-bfad-5c66-ad56-2df72496a0d1', '02f36c2b-0f8d-5ef8-aa81-ebbdc334dba4', NULL, 5, 5, 'Oh that you would be completely silent! Then you would be wise.'),
  ('852268c8-e443-5269-af4a-3fdbdac7bba0', '02f36c2b-0f8d-5ef8-aa81-ebbdc334dba4', NULL, 6, 6, 'Hear now my reasoning. Listen to the pleadings of my lips.'),
  ('1d17a8d1-1bbd-5acc-abaf-39d69f4ddf06', '02f36c2b-0f8d-5ef8-aa81-ebbdc334dba4', NULL, 7, 7, 'Will you speak unrighteously for God, and talk deceitfully for him?'),
  ('d88bac7b-3626-5d76-a76b-a573f3682ca9', '02f36c2b-0f8d-5ef8-aa81-ebbdc334dba4', NULL, 8, 8, 'Will you show partiality to him? Will you contend for God?'),
  ('fc99665b-59c1-58a0-a595-8b4f45a69370', '02f36c2b-0f8d-5ef8-aa81-ebbdc334dba4', NULL, 9, 9, 'Is it good that he should search you out? Or as one deceives a man, will you deceive him?'),
  ('21c1be9a-8224-58f3-ab58-cb2124790122', '02f36c2b-0f8d-5ef8-aa81-ebbdc334dba4', NULL, 10, 10, 'He will surely reprove you if you secretly show partiality.'),
  ('15f23ca8-0352-5155-aca2-8f2f84572ae8', '02f36c2b-0f8d-5ef8-aa81-ebbdc334dba4', NULL, 11, 11, 'Shall not his majesty make you afraid, And his dread fall on you?'),
  ('1a82767f-452e-5b09-ad7f-8487260e4d2a', '02f36c2b-0f8d-5ef8-aa81-ebbdc334dba4', NULL, 12, 12, 'Your memorable sayings are proverbs of ashes, Your defenses are defenses of clay.'),
  ('a9e54cd9-1718-5fbb-a597-cd2371f1f6ce', '02f36c2b-0f8d-5ef8-aa81-ebbdc334dba4', NULL, 13, 13, '"Be silent, leave me alone, that I may speak. Let come on me what will.'),
  ('120765a0-574c-527a-a93f-abf05c54daf5', '02f36c2b-0f8d-5ef8-aa81-ebbdc334dba4', NULL, 14, 14, 'Why should I take my flesh in my teeth, and put my life in my hand?'),
  ('21b8e4c3-8996-5950-a4e9-dc65906869da', '02f36c2b-0f8d-5ef8-aa81-ebbdc334dba4', NULL, 15, 15, 'Behold, he will kill me. I have no hope. Nevertheless, I will maintain my ways before him.'),
  ('540ebbf6-5704-50ea-a76a-8c9fc0b8a99f', '02f36c2b-0f8d-5ef8-aa81-ebbdc334dba4', NULL, 16, 16, 'This also shall be my salvation, that a godless man shall not come before him.'),
  ('295d7729-7c7d-5855-a090-74509605602e', '02f36c2b-0f8d-5ef8-aa81-ebbdc334dba4', NULL, 17, 17, 'Hear diligently my speech. Let my declaration be in your ears.'),
  ('6a8a22b8-7520-53db-aef9-b48ed07a7243', '02f36c2b-0f8d-5ef8-aa81-ebbdc334dba4', NULL, 18, 18, 'See now, I have set my cause in order. I know that I am righteous.'),
  ('af4c329e-5541-5f40-aa31-91f7aad0de81', '02f36c2b-0f8d-5ef8-aa81-ebbdc334dba4', NULL, 19, 19, 'Who is he who will contend with me? For then would I hold my peace and give up the spirit.'),
  ('411295e4-b9a2-5171-addd-78fc259acb06', '02f36c2b-0f8d-5ef8-aa81-ebbdc334dba4', NULL, 20, 20, '"Only don''t do two things to me; then I will not hide myself from your face:'),
  ('90fb4990-e13a-5baf-a1d9-ea67f50c916c', '02f36c2b-0f8d-5ef8-aa81-ebbdc334dba4', NULL, 21, 21, 'withdraw your hand far from me; and don''t let your terror make me afraid.'),
  ('ed6a6a89-20f2-53be-afaa-dd2cc4db2704', '02f36c2b-0f8d-5ef8-aa81-ebbdc334dba4', NULL, 22, 22, 'Then call, and I will answer; or let me speak, and you answer me.'),
  ('36938b98-0ce1-5283-a153-93695770c4d9', '02f36c2b-0f8d-5ef8-aa81-ebbdc334dba4', NULL, 23, 23, 'How many are my iniquities and sins? Make me know my disobedience and my sin.'),
  ('9122d225-b853-5e24-af34-ba585ded3e47', '02f36c2b-0f8d-5ef8-aa81-ebbdc334dba4', NULL, 24, 24, 'Why hide you your face, and hold me for your enemy?'),
  ('e6072c03-a8bd-57e1-a30c-cc0a48a4e8b1', '02f36c2b-0f8d-5ef8-aa81-ebbdc334dba4', NULL, 25, 25, 'Will you harass a driven leaf? Will you pursue the dry stubble?'),
  ('dccd61b1-4f0a-5cbb-ac7d-8386410c96da', '02f36c2b-0f8d-5ef8-aa81-ebbdc334dba4', NULL, 26, 26, 'For you write bitter things against me, and make me inherit the iniquities of my youth:'),
  ('faad8391-05be-57ea-ae32-f2d7f764ff5c', '02f36c2b-0f8d-5ef8-aa81-ebbdc334dba4', NULL, 27, 27, 'You also put my feet in the stocks, and mark all my paths. You set a bound to the soles of my feet,'),
  ('ead636ce-6e0e-505d-adc3-e4d59d0db15c', '02f36c2b-0f8d-5ef8-aa81-ebbdc334dba4', NULL, 28, 28, 'though I am decaying like a rotten thing, like a garment that is moth-eaten.'),
  ('15ca8d03-ea35-557f-adb6-58dd141f8041', 'ceebdfac-d592-5fa8-a57a-cb2a3f953373', NULL, 1, 1, '"Man, who is born of a woman, is of few days, and full of trouble.'),
  ('ee5ca24e-3f50-5f07-ace5-f8e6793e4558', 'ceebdfac-d592-5fa8-a57a-cb2a3f953373', NULL, 2, 2, 'He comes forth like a flower, and is cut down. He also flees like a shadow, and doesn''t continue.'),
  ('62387412-817d-5fd5-a675-ef741c70ccdd', 'ceebdfac-d592-5fa8-a57a-cb2a3f953373', NULL, 3, 3, 'Do you open your eyes on such a one, and bring me into judgment with you?'),
  ('4e789e48-31d7-5aea-a3bd-f9744b30d3cd', 'ceebdfac-d592-5fa8-a57a-cb2a3f953373', NULL, 4, 4, 'Who can bring a clean thing out of an unclean? Not one.'),
  ('006e3840-7bf9-523c-a8f2-de952dbba659', 'ceebdfac-d592-5fa8-a57a-cb2a3f953373', NULL, 5, 5, 'Seeing his days are determined, the number of his months is with you, and you have appointed his bounds that he can''t pass;'),
  ('9949eaf3-0deb-54c0-a837-08a8eb07b117', 'ceebdfac-d592-5fa8-a57a-cb2a3f953373', NULL, 6, 6, 'Look away from him, that he may rest, until he shall accomplish, as a hireling, his day.'),
  ('bf26e0c6-ad2c-5900-a224-62cdf5b14d29', 'ceebdfac-d592-5fa8-a57a-cb2a3f953373', NULL, 7, 7, '"For there is hope for a tree, If it is cut down, that it will sprout again, that the tender branch of it will not cease.'),
  ('78758a99-0f81-5c86-a625-5168a0aa2652', 'ceebdfac-d592-5fa8-a57a-cb2a3f953373', NULL, 8, 8, 'Though its root grows old in the earth, and its stock dies in the ground,'),
  ('07f8c40c-37d4-5a9d-a5b0-ae9b7e886ef3', 'ceebdfac-d592-5fa8-a57a-cb2a3f953373', NULL, 9, 9, 'yet through the scent of water it will bud, and put forth boughs like a plant.'),
  ('3c805215-d700-5d0e-a5a6-ac0f3f92528d', 'ceebdfac-d592-5fa8-a57a-cb2a3f953373', NULL, 10, 10, 'But man dies, and is laid low. Yes, man gives up the spirit, and where is he?'),
  ('4f2df4ac-6bc2-54df-a143-eb9d0d49170b', 'ceebdfac-d592-5fa8-a57a-cb2a3f953373', NULL, 11, 11, 'As the waters fail from the sea, and the river wastes and dries up,'),
  ('0a508609-17ec-5260-a1ab-138cca085bf0', 'ceebdfac-d592-5fa8-a57a-cb2a3f953373', NULL, 12, 12, 'so man lies down and doesn''t rise. Until the heavens are no more, they shall not awake, nor be roused out of their sleep.'),
  ('0b322748-641b-547d-a60d-b42e1e2f9f87', 'ceebdfac-d592-5fa8-a57a-cb2a3f953373', NULL, 13, 13, '"Oh that you would hide me in Sheol, that you would keep me secret, until your wrath is past, that you would appoint me a set time, and remember me!'),
  ('6282143b-8019-5c8d-aa1a-637f6442c3d4', 'ceebdfac-d592-5fa8-a57a-cb2a3f953373', NULL, 14, 14, 'If a man dies, shall he live again? All the days of my warfare would I wait, until my release should come.'),
  ('8d9be35e-08d6-5f40-a9cc-62a86b52332a', 'ceebdfac-d592-5fa8-a57a-cb2a3f953373', NULL, 15, 15, 'You would call, and I would answer you. You would have a desire to the work of your hands.'),
  ('08b85382-38d4-5c95-a228-2615cbf89175', 'ceebdfac-d592-5fa8-a57a-cb2a3f953373', NULL, 16, 16, 'But now you number my steps. Don''t you watch over my sin?'),
  ('1597befc-d2aa-5233-a21a-31aab5f777ff', 'ceebdfac-d592-5fa8-a57a-cb2a3f953373', NULL, 17, 17, 'My disobedience is sealed up in a bag. You fasten up my iniquity.'),
  ('588e2994-7bff-5be0-a5e0-232253b9554e', 'ceebdfac-d592-5fa8-a57a-cb2a3f953373', NULL, 18, 18, '"But the mountain falling comes to nothing. The rock is removed out of its place;'),
  ('2bde09ff-55af-5e6c-a9ee-2e3f52194c5a', 'ceebdfac-d592-5fa8-a57a-cb2a3f953373', NULL, 19, 19, 'The waters wear the stones. The torrents of it wash away the dust of the earth. So you destroy the hope of man.'),
  ('1027c7d2-def7-5852-a14c-fe1379521f08', 'ceebdfac-d592-5fa8-a57a-cb2a3f953373', NULL, 20, 20, 'You forever prevail against him, and he departs. You change his face, and send him away.'),
  ('6ab424a9-6764-5512-ae8e-ce5ee109b267', 'ceebdfac-d592-5fa8-a57a-cb2a3f953373', NULL, 21, 21, 'His sons come to honor, and he doesn''t know it. They are brought low, but he doesn''t perceive it of them.'),
  ('062b9979-b157-5ece-a051-d8cc3023eaa2', 'ceebdfac-d592-5fa8-a57a-cb2a3f953373', NULL, 22, 22, 'But his flesh on him has pain, and his soul within him mourns."'),
  ('9d57ad1c-80f1-538a-ab60-a87afdb267cb', '8469289a-e7a6-5a37-aa3a-0c6d33fad110', NULL, 1, 1, 'Then Eliphaz the Temanite answered,'),
  ('27476e8c-15dc-50e2-aa42-c7dc61409aa6', '8469289a-e7a6-5a37-aa3a-0c6d33fad110', NULL, 2, 2, '"Should a wise man answer with vain knowledge, and fill himself with the east wind?'),
  ('b3d4e6fb-82ce-5faa-a84e-0f0b16ac2ee9', '8469289a-e7a6-5a37-aa3a-0c6d33fad110', NULL, 3, 3, 'Should he reason with unprofitable talk, or with speeches with which he can do no good?'),
  ('2ee38f51-d2fc-59a4-a1d9-7b4969fd317c', '8469289a-e7a6-5a37-aa3a-0c6d33fad110', NULL, 4, 4, 'Yes, you do away with fear, and hinder devotion before God.'),
  ('292d0d2b-9b19-54ac-ac2c-2fae180545aa', '8469289a-e7a6-5a37-aa3a-0c6d33fad110', NULL, 5, 5, 'For your iniquity teaches your mouth, and you choose the language of the crafty.'),
  ('55d35037-eafe-5e55-a27f-57b5bfdd7631', '8469289a-e7a6-5a37-aa3a-0c6d33fad110', NULL, 6, 6, 'Your own mouth condemns you, and not I. Yes, your own lips testify against you.'),
  ('d3053b96-2892-5e3f-a75e-550fa5052bc0', '8469289a-e7a6-5a37-aa3a-0c6d33fad110', NULL, 7, 7, '"Are you the first man who was born? Or were you brought forth before the hills?'),
  ('f19b67a2-d8f7-530a-a5de-23d4369dcaf4', '8469289a-e7a6-5a37-aa3a-0c6d33fad110', NULL, 8, 8, 'Have you heard the secret counsel of God? Do you limit wisdom to yourself?'),
  ('c7667506-52b8-5abd-a777-4c841cc81df1', '8469289a-e7a6-5a37-aa3a-0c6d33fad110', NULL, 9, 9, 'What do you know, that we don''t know? What do you understand, which is not in us?'),
  ('c6a514e4-ff73-5003-ab36-f7080c941b67', '8469289a-e7a6-5a37-aa3a-0c6d33fad110', NULL, 10, 10, 'With us are both the gray-headed and the very aged men, much elder than your father.'),
  ('dec9cc6d-900b-5368-a084-fafc724ebd8d', '8469289a-e7a6-5a37-aa3a-0c6d33fad110', NULL, 11, 11, 'Are the consolations of God too small for you, even the word that is gentle toward you?'),
  ('259d526c-cb8f-5a01-a764-64fabe6de516', '8469289a-e7a6-5a37-aa3a-0c6d33fad110', NULL, 12, 12, 'Why does your heart carry you away? Why do your eyes flash,'),
  ('0139c744-0484-5d3d-a68e-fa38a375be63', '8469289a-e7a6-5a37-aa3a-0c6d33fad110', NULL, 13, 13, 'That you turn your spirit against God, and let such words go out of your mouth?'),
  ('dedcdd2c-57ef-5eb2-ac98-99b7bcf92376', '8469289a-e7a6-5a37-aa3a-0c6d33fad110', NULL, 14, 14, 'What is man, that he should be clean? What is he who is born of a woman, that he should be righteous?'),
  ('08e29e06-4a04-5222-a44c-142f2984e02d', '8469289a-e7a6-5a37-aa3a-0c6d33fad110', NULL, 15, 15, 'Behold, he puts no trust in his holy ones. Yes, the heavens are not clean in his sight;'),
  ('428a60e1-da68-5c66-afe7-b0b1dfe798fc', '8469289a-e7a6-5a37-aa3a-0c6d33fad110', NULL, 16, 16, 'how much less one who is abominable and corrupt, a man who drinks iniquity like water!'),
  ('97baedd2-b546-5062-a9df-aeb4de95dc41', '8469289a-e7a6-5a37-aa3a-0c6d33fad110', NULL, 17, 17, '"I will show you, listen to me; that which I have seen I will declare:'),
  ('70b5f001-b728-5452-a553-ac683675a986', '8469289a-e7a6-5a37-aa3a-0c6d33fad110', NULL, 18, 18, '(Which wise men have told by their fathers, and have not hidden it;'),
  ('78d0432b-f3ea-514c-a6d7-bc8cdae6ae62', '8469289a-e7a6-5a37-aa3a-0c6d33fad110', NULL, 19, 19, 'to whom alone the land was given, and no stranger passed among them):'),
  ('f72d126c-ce18-5302-a1e5-75f17e7b444f', '8469289a-e7a6-5a37-aa3a-0c6d33fad110', NULL, 20, 20, 'the wicked man writhes in pain all his days, even the number of years that are laid up for the oppressor.'),
  ('78faf49b-02d5-5763-aac8-98b5574edd71', '8469289a-e7a6-5a37-aa3a-0c6d33fad110', NULL, 21, 21, 'A sound of terrors is in his ears. In prosperity the destroyer shall come on him.'),
  ('b8cc0666-ea62-512d-a42f-04adf31dae3e', '8469289a-e7a6-5a37-aa3a-0c6d33fad110', NULL, 22, 22, 'He doesn''t believe that he shall return out of darkness. He is waited for by the sword.'),
  ('96ed4ee8-8a01-5316-a8bd-47abbdd28479', '8469289a-e7a6-5a37-aa3a-0c6d33fad110', NULL, 23, 23, 'He wanders abroad for bread, saying, ''Where is it?'' He knows that the day of darkness is ready at his hand.'),
  ('da59d66f-c951-5d19-a425-170e2cef27cb', '8469289a-e7a6-5a37-aa3a-0c6d33fad110', NULL, 24, 24, 'Distress and anguish make him afraid. They prevail against him, as a king ready to the battle.'),
  ('5651cab4-0bd4-51b6-a8b1-caaa1eb28360', '8469289a-e7a6-5a37-aa3a-0c6d33fad110', NULL, 25, 25, 'Because he has stretched out his hand against God, and behaves himself proudly against the Almighty;'),
  ('70caeb84-9b16-5c6b-a208-6d9b10a5f3d1', '8469289a-e7a6-5a37-aa3a-0c6d33fad110', NULL, 26, 26, 'he runs at him with a stiff neck, with the thick shields of his bucklers;'),
  ('c1d2fb56-6049-58ca-abb7-2101c143f6d2', '8469289a-e7a6-5a37-aa3a-0c6d33fad110', NULL, 27, 27, 'because he has covered his face with his fatness, and gathered fat on his thighs.'),
  ('a16b009e-9ab0-57bb-aa71-fb84db2422d2', '8469289a-e7a6-5a37-aa3a-0c6d33fad110', NULL, 28, 28, 'He has lived in desolate cities, in houses which no one inhabited, which were ready to become heaps.'),
  ('f081c701-0c6c-5839-a3ef-07ae65a3943a', '8469289a-e7a6-5a37-aa3a-0c6d33fad110', NULL, 29, 29, 'He shall not be rich, neither shall his substance continue, neither shall their possessions be extended on the earth.'),
  ('19d31544-f887-5491-abde-134b932051e4', '8469289a-e7a6-5a37-aa3a-0c6d33fad110', NULL, 30, 30, 'He shall not depart out of darkness. The flame shall dry up his branches. By the breath of God''s mouth shall he go away.'),
  ('1d5c906f-eafb-5967-a5b3-c76d2f36c766', '8469289a-e7a6-5a37-aa3a-0c6d33fad110', NULL, 31, 31, 'Let him not trust in emptiness, deceiving himself; for emptiness shall be his reward.'),
  ('b5c464f7-56b5-5664-a9fe-1bb67cc67472', '8469289a-e7a6-5a37-aa3a-0c6d33fad110', NULL, 32, 32, 'It shall be accomplished before his time. His branch shall not be green.'),
  ('c7bb1b80-5163-540a-a804-04bff75bb73f', '8469289a-e7a6-5a37-aa3a-0c6d33fad110', NULL, 33, 33, 'He shall shake off his unripe grape as the vine, and shall cast off his flower as the olive tree.'),
  ('76119329-75a5-5c2b-a18a-fdaa5bdfe149', '8469289a-e7a6-5a37-aa3a-0c6d33fad110', NULL, 34, 34, 'For the company of the godless shall be barren, and fire shall consume the tents of bribery.'),
  ('7f7e3d17-0fdd-5fad-a9c8-5fa9e5d5accb', '8469289a-e7a6-5a37-aa3a-0c6d33fad110', NULL, 35, 35, 'They conceive mischief, and bring forth iniquity. Their heart prepares deceit."'),
  ('d45ef559-1583-5f4e-a9fb-59bb00f11832', 'b659743b-e416-54d8-a20b-a72754073fd7', NULL, 1, 1, 'Then Job answered,'),
  ('423c0157-7976-5662-a62a-7a97e0ce2cf7', 'b659743b-e416-54d8-a20b-a72754073fd7', NULL, 2, 2, '"I have heard many such things. You are all miserable comforters!'),
  ('e2b9f7f9-f1e5-5e94-a6bc-f3e4b19bf8e3', 'b659743b-e416-54d8-a20b-a72754073fd7', NULL, 3, 3, 'Shall vain words have an end? Or what provokes you that you answer?'),
  ('3c9fe82a-5272-553a-ab1e-b7a82e726834', 'b659743b-e416-54d8-a20b-a72754073fd7', NULL, 4, 4, 'I also could speak as you do. If your soul were in my soul''s place, I could join words together against you, and shake my head at you,'),
  ('77b2b7a3-4ed7-5dfb-a2ff-0045882fb1c0', 'b659743b-e416-54d8-a20b-a72754073fd7', NULL, 5, 5, 'but I would strengthen you with my mouth. The solace of my lips would relieve you.'),
  ('cabbe4c1-cf83-5f9c-aa0d-f855aa89054d', 'b659743b-e416-54d8-a20b-a72754073fd7', NULL, 6, 6, '"Though I speak, my grief is not subsided. Though I forbear, what am I eased?'),
  ('f1c82e9d-25b9-5a63-aca2-63afbef44111', 'b659743b-e416-54d8-a20b-a72754073fd7', NULL, 7, 7, 'But now, God, you have surely worn me out. You have made desolate all my company.'),
  ('4b92f0bf-8916-5375-af91-b6c2b2820377', 'b659743b-e416-54d8-a20b-a72754073fd7', NULL, 8, 8, 'You have shriveled me up. This is a witness against me. My leanness rises up against me. It testifies to my face.'),
  ('91fdcf7a-3577-5a91-ac1c-e12c2ea9a414', 'b659743b-e416-54d8-a20b-a72754073fd7', NULL, 9, 9, 'He has torn me in his wrath, and persecuted me. He has gnashed on me with his teeth. My adversary sharpens his eyes on me.'),
  ('ff8ca98e-ef05-592e-ac51-c21677e23b34', 'b659743b-e416-54d8-a20b-a72754073fd7', NULL, 10, 10, 'They have gaped on me with their mouth. They have struck me on the cheek reproachfully. They gather themselves together against me.'),
  ('ff6b7786-ddaf-546d-a40e-15130877eccb', 'b659743b-e416-54d8-a20b-a72754073fd7', NULL, 11, 11, 'God delivers me to the ungodly, and casts me into the hands of the wicked.'),
  ('f155c3b0-78f6-5d77-ab6f-ba0a7e4cc785', 'b659743b-e416-54d8-a20b-a72754073fd7', NULL, 12, 12, 'I was at ease, and he broke me apart. Yes, he has taken me by the neck, and dashed me to pieces. He has also set me up for his target.'),
  ('60a7292a-b386-57df-aac1-f39cb132da8e', 'b659743b-e416-54d8-a20b-a72754073fd7', NULL, 13, 13, 'His archers surround me. He splits my kidneys apart, and does not spare. He pours out my gall on the ground.'),
  ('906b3240-6e1e-5d9a-af51-ac233ad14f39', 'b659743b-e416-54d8-a20b-a72754073fd7', NULL, 14, 14, 'He breaks me with breach on breach. He runs on me like a giant.'),
  ('3e54cf47-2129-573f-aadc-ff0902857f42', 'b659743b-e416-54d8-a20b-a72754073fd7', NULL, 15, 15, 'I have sewed sackcloth on my skin, and have thrust my horn in the dust.'),
  ('7844023d-f209-544c-a063-70d7e583d750', 'b659743b-e416-54d8-a20b-a72754073fd7', NULL, 16, 16, 'My face is red with weeping. Deep darkness is on my eyelids.'),
  ('63d922e7-4003-5c60-a662-00705c7647e2', 'b659743b-e416-54d8-a20b-a72754073fd7', NULL, 17, 17, 'Although there is no violence in my hands, and my prayer is pure.'),
  ('4925befa-3b99-5199-ade4-7cc6b061825b', 'b659743b-e416-54d8-a20b-a72754073fd7', NULL, 18, 18, '"Earth, don''t cover my blood. Let my cry have no place to rest.'),
  ('c15815cc-7368-5e60-a466-57a095b78848', 'b659743b-e416-54d8-a20b-a72754073fd7', NULL, 19, 19, 'Even now, behold, my witness is in heaven. He who vouches for me is on high.'),
  ('8aa2901b-b1db-572a-a7d5-4d9a29d0c602', 'b659743b-e416-54d8-a20b-a72754073fd7', NULL, 20, 20, 'My friends scoff at me. My eyes pour out tears to God,'),
  ('da5b4a06-4769-5acc-a4e6-77a79925c4ca', 'b659743b-e416-54d8-a20b-a72754073fd7', NULL, 21, 21, 'that he would maintain the right of a man with God, of a son of man with his neighbor!'),
  ('5db796b5-b627-5acb-a3f3-953fdfd3eb8e', 'b659743b-e416-54d8-a20b-a72754073fd7', NULL, 22, 22, 'For when a few years are come, I shall go the way of no return.'),
  ('1aee2316-781a-5413-a22b-d60803cf06f8', '59f3ea29-4e0b-513d-ac0d-a3a28f9cbd93', NULL, 1, 1, '"My spirit is consumed. My days are extinct, And the grave is ready for me.'),
  ('824f6157-cf8f-5ecd-ae5c-ec02a72c9fd5', '59f3ea29-4e0b-513d-ac0d-a3a28f9cbd93', NULL, 2, 2, 'Surely there are mockers with me. My eye dwells on their provocation.'),
  ('f3b27072-a6c8-54c8-abd6-491049ac7cab', '59f3ea29-4e0b-513d-ac0d-a3a28f9cbd93', NULL, 3, 3, '"Now give a pledge, be collateral for me with yourself. Who is there who will strike hands with me?'),
  ('7badc175-798e-5b4b-acb0-88a061c3a35f', '59f3ea29-4e0b-513d-ac0d-a3a28f9cbd93', NULL, 4, 4, 'For you have hidden their heart from understanding, Therefore you shall not exalt them.'),
  ('1f29286a-186c-5f32-aab4-78402884587b', '59f3ea29-4e0b-513d-ac0d-a3a28f9cbd93', NULL, 5, 5, 'He who denounces his friends for a prey, Even the eyes of his children shall fail.'),
  ('cc8932b5-1e61-5223-a62b-f827f6e4b0e3', '59f3ea29-4e0b-513d-ac0d-a3a28f9cbd93', NULL, 6, 6, '"But he has made me a byword of the people. They spit in my face.'),
  ('1144ebe6-cbc3-5032-a0e8-642de0c6a016', '59f3ea29-4e0b-513d-ac0d-a3a28f9cbd93', NULL, 7, 7, 'My eye also is dim by reason of sorrow. All my members are as a shadow.'),
  ('0a8c54f6-ab68-56ef-aa64-351c47c328c1', '59f3ea29-4e0b-513d-ac0d-a3a28f9cbd93', NULL, 8, 8, 'Upright men shall be astonished at this. The innocent shall stir up himself against the godless.'),
  ('06430800-52ed-5ae9-a322-57d02b5af046', '59f3ea29-4e0b-513d-ac0d-a3a28f9cbd93', NULL, 9, 9, 'Yet shall the righteous hold on his way. He who has clean hands shall grow stronger and stronger.'),
  ('f1380133-7a9d-5338-a261-a9b11237b10a', '59f3ea29-4e0b-513d-ac0d-a3a28f9cbd93', NULL, 10, 10, 'But as for you all, come on now again; I shall not find a wise man among you.'),
  ('d8654e92-a033-53bf-ad73-cf6970fa5e01', '59f3ea29-4e0b-513d-ac0d-a3a28f9cbd93', NULL, 11, 11, 'My days are past, my plans are broken off, as are the thoughts of my heart.'),
  ('60c07819-a0fe-5fe9-af91-ae2c2de8ce86', '59f3ea29-4e0b-513d-ac0d-a3a28f9cbd93', NULL, 12, 12, 'They change the night into day, saying ''The light is near'' in the presence of darkness.'),
  ('95729d8e-c105-5ca8-a86c-e190858c46c7', '59f3ea29-4e0b-513d-ac0d-a3a28f9cbd93', NULL, 13, 13, 'If I look for Sheol as my house, if I have spread my couch in the darkness,'),
  ('f853f41f-e1c3-51ab-adf8-1ea6657b2258', '59f3ea29-4e0b-513d-ac0d-a3a28f9cbd93', NULL, 14, 14, 'If I have said to corruption, ''You are my father;'' to the worm, ''My mother,'' and ''my sister;'''),
  ('500e1ec7-7983-5124-a65d-24a70e3935aa', '59f3ea29-4e0b-513d-ac0d-a3a28f9cbd93', NULL, 15, 15, 'where then is my hope? as for my hope, who shall see it?'),
  ('763cfb57-c0e9-5b34-a876-a5165a46da8c', '59f3ea29-4e0b-513d-ac0d-a3a28f9cbd93', NULL, 16, 16, 'Shall it go down with me to the gates of Sheol, or descend together into the dust?"'),
  ('16089924-0512-56b3-a802-323df8c2b559', '8ee42f81-2459-5600-a0fd-f5091bc13cb7', NULL, 1, 1, 'Then Bildad the Shuhite answered,'),
  ('107a1bd7-ac22-5cbc-ac9f-26630eda0f45', '8ee42f81-2459-5600-a0fd-f5091bc13cb7', NULL, 2, 2, '"How long will you hunt for words? Consider, and afterwards we will speak.'),
  ('a053d588-0b4d-53be-a778-4c8236beb75f', '8ee42f81-2459-5600-a0fd-f5091bc13cb7', NULL, 3, 3, 'Why are we counted as animals, which have become unclean in your sight?'),
  ('7c54c074-cb81-5611-aaec-3ce935dca843', '8ee42f81-2459-5600-a0fd-f5091bc13cb7', NULL, 4, 4, 'You who tear yourself in your anger, shall the earth be forsaken for you? Or shall the rock be removed out of its place?'),
  ('37e9d3b0-ce76-5ca6-a9a7-87b35d1cefa9', '8ee42f81-2459-5600-a0fd-f5091bc13cb7', NULL, 5, 5, '"Yes, the light of the wicked shall be put out, The spark of his fire shall not shine.'),
  ('4be03ac4-98ee-5d78-af5f-6d4e0c1dd18e', '8ee42f81-2459-5600-a0fd-f5091bc13cb7', NULL, 6, 6, 'The light shall be dark in his tent. His lamp above him shall be put out.'),
  ('1a6596f1-05d2-56af-a83d-52ec075ff463', '8ee42f81-2459-5600-a0fd-f5091bc13cb7', NULL, 7, 7, 'The steps of his strength shall be shortened. His own counsel shall cast him down.'),
  ('401a956e-ceb0-5f64-ae37-3a3de72db866', '8ee42f81-2459-5600-a0fd-f5091bc13cb7', NULL, 8, 8, 'For he is cast into a net by his own feet, and he wanders into its mesh.'),
  ('15d8c019-3640-51ac-aa7c-3545d3e92671', '8ee42f81-2459-5600-a0fd-f5091bc13cb7', NULL, 9, 9, 'A snare will take him by the heel. A trap will catch him.'),
  ('c22e5a66-2d8e-50e6-ad8a-8699797d1dfb', '8ee42f81-2459-5600-a0fd-f5091bc13cb7', NULL, 10, 10, 'A noose is hidden for him in the ground, a trap for him in the way.'),
  ('576d725d-8d56-59d5-af4f-e2d25b97af8f', '8ee42f81-2459-5600-a0fd-f5091bc13cb7', NULL, 11, 11, 'Terrors shall make him afraid on every side, and shall chase him at his heels.'),
  ('cd48aacc-1d2e-5fa9-ab4a-9fe6aa6c6393', '8ee42f81-2459-5600-a0fd-f5091bc13cb7', NULL, 12, 12, 'His strength shall be famished. Calamity shall be ready at his side.'),
  ('70061388-d166-5bec-a939-42ca961f22c5', '8ee42f81-2459-5600-a0fd-f5091bc13cb7', NULL, 13, 13, 'The members of his body shall be devoured. The firstborn of death shall devour his members.'),
  ('e8cda660-0f06-5fd6-a7e8-bf9b141e4d23', '8ee42f81-2459-5600-a0fd-f5091bc13cb7', NULL, 14, 14, 'He shall be rooted out of his tent where he trusts. He shall be brought to the king of terrors.'),
  ('6b2e0f39-93af-5261-a902-5ff7d51e3035', '8ee42f81-2459-5600-a0fd-f5091bc13cb7', NULL, 15, 15, 'There shall dwell in his tent that which is none of his. Sulfur shall be scattered on his habitation.'),
  ('f46de9fd-a84c-51f1-a5a6-449933907f6d', '8ee42f81-2459-5600-a0fd-f5091bc13cb7', NULL, 16, 16, 'His roots shall be dried up beneath. Above shall his branch be cut off.'),
  ('932b6d44-1709-527a-a7bc-fb54fa146f97', '8ee42f81-2459-5600-a0fd-f5091bc13cb7', NULL, 17, 17, 'His memory shall perish from the earth. He shall have no name in the street.'),
  ('fcd75258-3ee7-53ec-af81-53a933b566ad', '8ee42f81-2459-5600-a0fd-f5091bc13cb7', NULL, 18, 18, 'He shall be driven from light into darkness, and chased out of the world.'),
  ('2e9ca7cb-6039-534d-a754-ccdd94b59108', '8ee42f81-2459-5600-a0fd-f5091bc13cb7', NULL, 19, 19, 'He shall have neither son nor grandson among his people, nor any remaining where he lived.'),
  ('6b06fd2c-42c6-5155-a324-660ad2bfb8f8', '8ee42f81-2459-5600-a0fd-f5091bc13cb7', NULL, 20, 20, 'Those who come after shall be astonished at his day, as those who went before were frightened.'),
  ('9e49c841-e9bd-50db-af91-5c9721d477d9', '8ee42f81-2459-5600-a0fd-f5091bc13cb7', NULL, 21, 21, 'Surely such are the dwellings of the unrighteous. This is the place of him who doesn''t know God."'),
  ('f2502ac5-afd0-5678-a53a-4a8135c19acc', 'b7eb7029-d44c-5c8b-a925-557930b3b294', NULL, 1, 1, 'Then Job answered,'),
  ('bf1aef47-5b0a-5132-ad54-eb07763152bf', 'b7eb7029-d44c-5c8b-a925-557930b3b294', NULL, 2, 2, '"How long will you torment me, and crush me with words?'),
  ('b80d5d88-daf7-53dc-a970-f4fd21f4ca15', 'b7eb7029-d44c-5c8b-a925-557930b3b294', NULL, 3, 3, 'You have reproached me ten times. You aren''t ashamed that you attack me.'),
  ('893adbcc-155b-5209-a87e-0efc103a2c62', 'b7eb7029-d44c-5c8b-a925-557930b3b294', NULL, 4, 4, 'If it is true that I have erred, my error remains with myself.'),
  ('e590d944-9de4-5e1f-a1e3-8f24a4b71b5b', 'b7eb7029-d44c-5c8b-a925-557930b3b294', NULL, 5, 5, 'If indeed you will magnify yourselves against me, and plead against me my reproach;'),
  ('6a2b4e38-47b5-5843-a208-e7f3dec77a3c', 'b7eb7029-d44c-5c8b-a925-557930b3b294', NULL, 6, 6, 'know now that God has subverted me, and has surrounded me with his net.'),
  ('c2d6342e-c9eb-5323-acbf-bb006bd40144', 'b7eb7029-d44c-5c8b-a925-557930b3b294', NULL, 7, 7, '"Behold, I cry out of wrong, but I am not heard. I cry for help, but there is no justice.'),
  ('3f84cb57-f32c-5080-ab16-49261aebe784', 'b7eb7029-d44c-5c8b-a925-557930b3b294', NULL, 8, 8, 'He has walled up my way so that I can''t pass, and has set darkness in my paths.'),
  ('917ce98b-fe81-5f28-a3c9-7c8f8a6661a4', 'b7eb7029-d44c-5c8b-a925-557930b3b294', NULL, 9, 9, 'He has stripped me of my glory, and taken the crown from my head.'),
  ('26ccf170-df7e-5eef-a4c2-6b8ae0d3194a', 'b7eb7029-d44c-5c8b-a925-557930b3b294', NULL, 10, 10, 'He has broken me down on every side, and I am gone. My hope he has plucked up like a tree.'),
  ('47122e51-43b9-5db5-a88c-07538619592c', 'b7eb7029-d44c-5c8b-a925-557930b3b294', NULL, 11, 11, 'He has also kindled his wrath against me. He counts me among his adversaries.'),
  ('b59bbc92-0863-5f84-a555-85a09cae3cd6', 'b7eb7029-d44c-5c8b-a925-557930b3b294', NULL, 12, 12, 'His troops come on together, build a siege ramp against me, and encamp around my tent.'),
  ('66287b03-112b-54d9-a6cc-301aa6e4deb3', 'b7eb7029-d44c-5c8b-a925-557930b3b294', NULL, 13, 13, '"He has put my brothers far from me. My acquaintances are wholly estranged from me.'),
  ('40a58c74-d906-5f56-ad7f-b105c7945d99', 'b7eb7029-d44c-5c8b-a925-557930b3b294', NULL, 14, 14, 'My relatives have gone away. My familiar friends have forgotten me.'),
  ('e66651e0-80cf-5d1e-ab50-fcc6259c34e8', 'b7eb7029-d44c-5c8b-a925-557930b3b294', NULL, 15, 15, 'Those who dwell in my house, and my maids, count me for a stranger. I am an alien in their sight.'),
  ('4b4cd59b-7aff-5163-ac87-135414206936', 'b7eb7029-d44c-5c8b-a925-557930b3b294', NULL, 16, 16, 'I call to my servant, and he gives me no answer. I beg him with my mouth.'),
  ('f44adb19-3575-5ac6-a1a2-76685a45b623', 'b7eb7029-d44c-5c8b-a925-557930b3b294', NULL, 17, 17, 'My breath is offensive to my wife. I am loathsome to the children of my own mother.'),
  ('0d415865-a84a-514a-a119-f4bc5bce812a', 'b7eb7029-d44c-5c8b-a925-557930b3b294', NULL, 18, 18, 'Even young children despise me. If I arise, they speak against me.'),
  ('4a1cec92-67b4-56cb-a6e0-b27b1ee947d7', 'b7eb7029-d44c-5c8b-a925-557930b3b294', NULL, 19, 19, 'All my familiar friends abhor me. They whom I loved have turned against me.'),
  ('e01b505a-7896-5c8f-a079-8c4c771bba93', 'b7eb7029-d44c-5c8b-a925-557930b3b294', NULL, 20, 20, 'My bones stick to my skin and to my flesh. I have escaped by the skin of my teeth.'),
  ('f40a778c-5418-5e48-ad68-8d86436c6ae4', 'b7eb7029-d44c-5c8b-a925-557930b3b294', NULL, 21, 21, '"Have pity on me, have pity on me, you my friends; for the hand of God has touched me.'),
  ('b8fe1084-17a2-5bc2-a262-d03dd09bd1d1', 'b7eb7029-d44c-5c8b-a925-557930b3b294', NULL, 22, 22, 'Why do you persecute me as God, and are not satisfied with my flesh?'),
  ('268d7be7-287d-5079-a2fe-9bea8013ddf2', 'b7eb7029-d44c-5c8b-a925-557930b3b294', NULL, 23, 23, '"Oh that my words were now written! Oh that they were inscribed in a book!'),
  ('c8e25944-c715-5d30-a99f-4012bfca2038', 'b7eb7029-d44c-5c8b-a925-557930b3b294', NULL, 24, 24, 'That with an iron pen and lead they were engraved in the rock forever!'),
  ('9c00b975-6a49-541b-aaa4-340ba2ca2220', 'b7eb7029-d44c-5c8b-a925-557930b3b294', NULL, 25, 25, 'But as for me, I know that my Redeemer lives. In the end, he will stand upon the earth.'),
  ('a0698fbf-6d0a-5153-aef1-f1e4242979dc', 'b7eb7029-d44c-5c8b-a925-557930b3b294', NULL, 26, 26, 'After my skin is destroyed, then in my flesh shall I see God,'),
  ('8f38ffe4-22f4-50ac-a906-550d9e6f7094', 'b7eb7029-d44c-5c8b-a925-557930b3b294', NULL, 27, 27, 'Whom I, even I, shall see on my side. My eyes shall see, and not as a stranger. "My heart is consumed within me.'),
  ('515bc4d3-7dcf-51eb-a623-54669bdcaad6', 'b7eb7029-d44c-5c8b-a925-557930b3b294', NULL, 28, 28, 'If you say, ''How we will persecute him!'' because the root of the matter is found in me,'),
  ('d955d345-1818-56c1-a2c8-77757af6fd22', 'b7eb7029-d44c-5c8b-a925-557930b3b294', NULL, 29, 29, 'be afraid of the sword, for wrath brings the punishments of the sword, that you may know there is a judgment."'),
  ('5cdf7f4a-25dd-5e01-a7cc-080e996d71ec', '64f52ede-1ca1-5ce5-acc7-e9b0356460dc', NULL, 1, 1, 'Then Zophar the Naamathite answered,'),
  ('893f79e7-5cac-5a5b-a3a5-dd3ddcfbcf5f', '64f52ede-1ca1-5ce5-acc7-e9b0356460dc', NULL, 2, 2, '"Therefore do my thoughts give answer to me, even by reason of my haste that is in me.'),
  ('ca9d8aad-83a4-5e02-a6aa-8c24cce2b39d', '64f52ede-1ca1-5ce5-acc7-e9b0356460dc', NULL, 3, 3, 'I have heard the reproof which puts me to shame. The spirit of my understanding answers me.'),
  ('6accca23-df00-59d0-a27c-6922fd56d70b', '64f52ede-1ca1-5ce5-acc7-e9b0356460dc', NULL, 4, 4, 'Don''t you know this from old time, since man was placed on earth,'),
  ('98ad4f4b-e790-5d91-a519-6257894b382f', '64f52ede-1ca1-5ce5-acc7-e9b0356460dc', NULL, 5, 5, 'that the triumphing of the wicked is short, the joy of the godless but for a moment?'),
  ('d329baae-7d04-5a26-a16e-07865ad89192', '64f52ede-1ca1-5ce5-acc7-e9b0356460dc', NULL, 6, 6, 'Though his height mount up to the heavens, and his head reach to the clouds,'),
  ('c925f1d2-47e7-58fe-a7a5-30d25337f0d7', '64f52ede-1ca1-5ce5-acc7-e9b0356460dc', NULL, 7, 7, 'yet he shall perish forever like his own dung. Those who have seen him shall say, ''Where is he?'''),
  ('c8768849-1a47-56b6-a383-38cc7c7670ba', '64f52ede-1ca1-5ce5-acc7-e9b0356460dc', NULL, 8, 8, 'He shall fly away as a dream, and shall not be found. Yes, he shall be chased away like a vision of the night.'),
  ('1cbf693d-7e73-59da-a2a9-7e95b4adb085', '64f52ede-1ca1-5ce5-acc7-e9b0356460dc', NULL, 9, 9, 'The eye which saw him shall see him no more, neither shall his place any more see him.'),
  ('3b5fa282-282f-529d-a106-185721de81b3', '64f52ede-1ca1-5ce5-acc7-e9b0356460dc', NULL, 10, 10, 'His children shall seek the favor of the poor. His hands shall give back his wealth.'),
  ('3e9f3b65-735c-54ed-a971-d2da7cfc3e7e', '64f52ede-1ca1-5ce5-acc7-e9b0356460dc', NULL, 11, 11, 'His bones are full of his youth, but youth shall lie down with him in the dust.'),
  ('a748bacb-a7d9-52dc-a702-fe5c778dfc93', '64f52ede-1ca1-5ce5-acc7-e9b0356460dc', NULL, 12, 12, '"Though wickedness is sweet in his mouth, though he hide it under his tongue,'),
  ('a22fc9d5-2620-5a95-a6b4-d89b98b87c87', '64f52ede-1ca1-5ce5-acc7-e9b0356460dc', NULL, 13, 13, 'though he spare it, and will not let it go, but keep it still within his mouth;'),
  ('a3941b1b-1a9d-5376-a2e7-737d5f216e83', '64f52ede-1ca1-5ce5-acc7-e9b0356460dc', NULL, 14, 14, 'yet his food in his bowels is turned. It is cobra venom within him.'),
  ('3a819a7d-51f5-52d1-afe7-9f72c2914405', '64f52ede-1ca1-5ce5-acc7-e9b0356460dc', NULL, 15, 15, 'He has swallowed down riches, and he shall vomit them up again. God will cast them out of his belly.'),
  ('abeb429b-45b6-5513-a761-3a25152e7c7c', '64f52ede-1ca1-5ce5-acc7-e9b0356460dc', NULL, 16, 16, 'He shall suck cobra venom. The viper''s tongue shall kill him.'),
  ('4e17952f-a6bb-561b-a7b3-140c4d6f50f5', '64f52ede-1ca1-5ce5-acc7-e9b0356460dc', NULL, 17, 17, 'He shall not look at the rivers, the flowing streams of honey and butter.'),
  ('77b81e76-eeb0-590c-a4a2-d7e15a224533', '64f52ede-1ca1-5ce5-acc7-e9b0356460dc', NULL, 18, 18, 'That for which he labored he shall restore, and shall not swallow it down. According to the substance that he has gotten, he shall not rejoice.'),
  ('9d945c52-a511-5110-a209-df4756129564', '64f52ede-1ca1-5ce5-acc7-e9b0356460dc', NULL, 19, 19, 'For he has oppressed and forsaken the poor. He has violently taken away a house, and he shall not build it up.'),
  ('abc6e9ad-60de-530d-a598-b36271116aa7', '64f52ede-1ca1-5ce5-acc7-e9b0356460dc', NULL, 20, 20, '"Because he knew no quietness within him, he shall not save anything of that in which he delights.'),
  ('f688e20e-5e22-5afc-a70c-28e929f8afe5', '64f52ede-1ca1-5ce5-acc7-e9b0356460dc', NULL, 21, 21, 'There was nothing left that he didn''t devour, therefore his prosperity shall not endure.'),
  ('c78ffea7-fc18-571d-ade7-bf380523a771', '64f52ede-1ca1-5ce5-acc7-e9b0356460dc', NULL, 22, 22, 'In the fullness of his sufficiency, distress shall overtake him. The hand of everyone who is in misery shall come on him.'),
  ('d4861451-31b3-58b4-ad35-e7cfe9c139ac', '64f52ede-1ca1-5ce5-acc7-e9b0356460dc', NULL, 23, 23, 'When he is about to fill his belly, God will cast the fierceness of his wrath on him. It will rain on him while he is eating.'),
  ('df10b235-e729-52a9-a870-6c6e0b0dfe20', '64f52ede-1ca1-5ce5-acc7-e9b0356460dc', NULL, 24, 24, 'He shall flee from the iron weapon. The bronze arrow shall strike him through.'),
  ('777d90c3-a4be-5875-a58b-86f6948b541b', '64f52ede-1ca1-5ce5-acc7-e9b0356460dc', NULL, 25, 25, 'He draws it forth, and it comes out of his body. Yes, the glittering point comes out of his liver. Terrors are on him.'),
  ('6bbcef95-4c6f-54df-a396-40d2d746ebc2', '64f52ede-1ca1-5ce5-acc7-e9b0356460dc', NULL, 26, 26, 'All darkness is laid up for his treasures. An unfanned fire shall devour him. It shall consume that which is left in his tent.'),
  ('839bcfc8-e3e3-5d96-a265-6850ba510e2d', '64f52ede-1ca1-5ce5-acc7-e9b0356460dc', NULL, 27, 27, 'The heavens shall reveal his iniquity. The earth shall rise up against him.'),
  ('ff7080df-e2e2-5e25-af3e-b8c1f1b288e7', '64f52ede-1ca1-5ce5-acc7-e9b0356460dc', NULL, 28, 28, 'The increase of his house shall depart. They shall rush away in the day of his wrath.'),
  ('20066997-bbab-5367-a60f-058aaaba4afb', '64f52ede-1ca1-5ce5-acc7-e9b0356460dc', NULL, 29, 29, 'This is the portion of a wicked man from God, the heritage appointed to him by God."'),
  ('33c1c99a-7f29-57a5-aa0e-ef22e7572aac', 'd235e156-be24-56a1-a4ac-23bed602bbeb', NULL, 1, 1, 'Then Job answered,'),
  ('40b8950a-8c4d-5fbb-ad9b-165d7ee14d21', 'd235e156-be24-56a1-a4ac-23bed602bbeb', NULL, 2, 2, '"Listen diligently to my speech. Let this be your consolation.'),
  ('58be0342-18ed-5953-af94-73e2448ba372', 'd235e156-be24-56a1-a4ac-23bed602bbeb', NULL, 3, 3, 'Allow me, and I also will speak; After I have spoken, mock on.'),
  ('1d346011-a174-56b4-ab11-7d55a6331fcf', 'd235e156-be24-56a1-a4ac-23bed602bbeb', NULL, 4, 4, 'As for me, is my complaint to man? Why shouldn''t I be impatient?'),
  ('21717ddf-b9e3-5473-a782-4c8619385002', 'd235e156-be24-56a1-a4ac-23bed602bbeb', NULL, 5, 5, 'Look at me, and be astonished. Lay your hand on your mouth.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('8fc56866-fb05-5136-a2ba-9ba0c63577f7', 'd235e156-be24-56a1-a4ac-23bed602bbeb', NULL, 6, 6, 'When I remember, I am troubled. Horror takes hold of my flesh.'),
  ('cdc700be-689d-57cb-aa92-ef5cf1bbdf7a', 'd235e156-be24-56a1-a4ac-23bed602bbeb', NULL, 7, 7, '"Why do the wicked live, become old, yes, and grow mighty in power?'),
  ('91b4d6e5-00f6-5438-adb4-8b1a0f1f2a4e', 'd235e156-be24-56a1-a4ac-23bed602bbeb', NULL, 8, 8, 'Their child is established with them in their sight, their offspring before their eyes.'),
  ('8ef9c39d-2f1c-5a19-adc7-4826b61712bd', 'd235e156-be24-56a1-a4ac-23bed602bbeb', NULL, 9, 9, 'Their houses are safe from fear, neither is the rod of God upon them.'),
  ('ce3ec649-95cc-5ed0-a703-7731dfe8facc', 'd235e156-be24-56a1-a4ac-23bed602bbeb', NULL, 10, 10, 'Their bulls breed without fail. Their cows calve, and don''t miscarry.'),
  ('17b6a023-f5ea-56f6-aec4-3d20e4052c75', 'd235e156-be24-56a1-a4ac-23bed602bbeb', NULL, 11, 11, 'They send forth their little ones like a flock. Their children dance.'),
  ('5b5e23ea-942d-5c6b-ac18-9b9ca858d24e', 'd235e156-be24-56a1-a4ac-23bed602bbeb', NULL, 12, 12, 'They sing to the tambourine and harp, and rejoice at the sound of the pipe.'),
  ('fa4c1f3b-1c61-5497-a668-e3eaeae56d74', 'd235e156-be24-56a1-a4ac-23bed602bbeb', NULL, 13, 13, 'They spend their days in prosperity. In an instant they go down to Sheol.'),
  ('daddd4aa-1ea6-5e92-a094-9d979d1c119c', 'd235e156-be24-56a1-a4ac-23bed602bbeb', NULL, 14, 14, 'They tell God, ''Depart from us, for we don''t want to know about your ways.'),
  ('50315671-0d5c-5a06-aa0f-42e68e3040ba', 'd235e156-be24-56a1-a4ac-23bed602bbeb', NULL, 15, 15, 'What is the Almighty, that we should serve him? What profit should we have, if we pray to him?'''),
  ('83aa4c3a-e419-5595-a2ff-78a8a7e3a3ae', 'd235e156-be24-56a1-a4ac-23bed602bbeb', NULL, 16, 16, 'Behold, their prosperity is not in their hand. The counsel of the wicked is far from me.'),
  ('f1cc8255-fb84-5938-ae2e-f025fd045c3a', 'd235e156-be24-56a1-a4ac-23bed602bbeb', NULL, 17, 17, '"How often is it that the lamp of the wicked is put out, that their calamity comes on them, that God distributes sorrows in his anger?'),
  ('274e7cb4-e13d-5a71-a339-60f1231cb894', 'd235e156-be24-56a1-a4ac-23bed602bbeb', NULL, 18, 18, 'How often is it that they are as stubble before the wind, as chaff that the storm carries away?'),
  ('356fad9c-5a9d-5011-a088-986b92790bbe', 'd235e156-be24-56a1-a4ac-23bed602bbeb', NULL, 19, 19, 'You say, ''God lays up his iniquity for his children.'' Let him recompense it to himself, that he may know it.'),
  ('8bd10f22-7648-51a5-ae38-d29fc9afa032', 'd235e156-be24-56a1-a4ac-23bed602bbeb', NULL, 20, 20, 'Let his own eyes see his destruction. Let him drink of the wrath of the Almighty.'),
  ('e457bb92-86db-5a7a-abc6-f1f81d8f47d6', 'd235e156-be24-56a1-a4ac-23bed602bbeb', NULL, 21, 21, 'For what does he care for his house after him, when the number of his months is cut off?'),
  ('28e636df-1940-52d4-a1a3-25430ee1a022', 'd235e156-be24-56a1-a4ac-23bed602bbeb', NULL, 22, 22, '"Shall any teach God knowledge, since he judges those who are high?'),
  ('3f451e93-4a71-5969-abba-ef6a21d13cf0', 'd235e156-be24-56a1-a4ac-23bed602bbeb', NULL, 23, 23, 'One dies in his full strength, being wholly at ease and quiet.'),
  ('b950536d-766b-5994-a4fd-511b573b94c9', 'd235e156-be24-56a1-a4ac-23bed602bbeb', NULL, 24, 24, 'His pails are full of milk. The marrow of his bones is moistened.'),
  ('60107c47-a572-57e3-ac86-36ebea4635fc', 'd235e156-be24-56a1-a4ac-23bed602bbeb', NULL, 25, 25, 'Another dies in bitterness of soul, and never tastes of good.'),
  ('09d9e388-ad42-5173-a067-d3c722bda2f1', 'd235e156-be24-56a1-a4ac-23bed602bbeb', NULL, 26, 26, 'They lie down alike in the dust. The worm covers them.'),
  ('6fd48297-9870-5a12-ae2e-3d4a3d9f0471', 'd235e156-be24-56a1-a4ac-23bed602bbeb', NULL, 27, 27, '"Behold, I know your thoughts, the devices with which you would wrong me.'),
  ('8feafa8d-09c8-5adf-ae3b-ddc92fbc1593', 'd235e156-be24-56a1-a4ac-23bed602bbeb', NULL, 28, 28, 'For you say, ''Where is the house of the prince? Where is the tent in which the wicked lived?'''),
  ('0dbdeef4-1ac8-52b6-aee6-a31e7c9cc61a', 'd235e156-be24-56a1-a4ac-23bed602bbeb', NULL, 29, 29, 'Haven''t you asked wayfaring men? Don''t you know their evidences,'),
  ('83535280-0bf9-5e52-a8fb-e1e46379446c', 'd235e156-be24-56a1-a4ac-23bed602bbeb', NULL, 30, 30, 'that the evil man is reserved to the day of calamity, That they are led forth to the day of wrath?'),
  ('d6a959a2-7a0b-5368-a025-062b14a8017f', 'd235e156-be24-56a1-a4ac-23bed602bbeb', NULL, 31, 31, 'Who shall declare his way to his face? Who shall repay him what he has done?'),
  ('5ced3078-b99d-5ff9-aef0-55452b819b79', 'd235e156-be24-56a1-a4ac-23bed602bbeb', NULL, 32, 32, 'Yet he will be borne to the grave. Men shall keep watch over the tomb.'),
  ('7f67b79f-c440-599e-a3ec-6e7364f3d5f0', 'd235e156-be24-56a1-a4ac-23bed602bbeb', NULL, 33, 33, 'The clods of the valley shall be sweet to him. All men shall draw after him, as there were innumerable before him.'),
  ('1d01a25a-d277-5c86-a823-4b427f39f927', 'd235e156-be24-56a1-a4ac-23bed602bbeb', NULL, 34, 34, 'So how can you comfort me with nonsense, because in your answers there remains only falsehood?"'),
  ('59f7538c-6b2f-5b1c-aa90-2cd9d6cabcc0', '4b723637-4baa-509c-a11b-0a4876f60394', NULL, 1, 1, 'Then Eliphaz the Temanite answered,'),
  ('168232b6-fa81-54cc-a667-13a6b2b9dbac', '4b723637-4baa-509c-a11b-0a4876f60394', NULL, 2, 2, '"Can a man be profitable to God? Surely he who is wise is profitable to himself.'),
  ('1517989a-29c9-5696-a1f4-aa9a14a2fe5a', '4b723637-4baa-509c-a11b-0a4876f60394', NULL, 3, 3, 'Is it any pleasure to the Almighty, that you are righteous? Or does it benefit him, that you make your ways perfect?'),
  ('a20926e6-ecbe-5bab-ad3f-1cc50b66c69a', '4b723637-4baa-509c-a11b-0a4876f60394', NULL, 4, 4, 'Is it for your piety that he reproves you, that he enters with you into judgment?'),
  ('1b2773dd-5d76-5b61-a79b-2f9af81b7057', '4b723637-4baa-509c-a11b-0a4876f60394', NULL, 5, 5, 'Isn''t your wickedness great? Neither is there any end to your iniquities.'),
  ('f5cbef57-baf0-52dc-a314-ead2fcab7c58', '4b723637-4baa-509c-a11b-0a4876f60394', NULL, 6, 6, 'For you have taken pledges from your brother for nothing, and stripped the naked of their clothing.'),
  ('b8348b53-8b3d-57bf-a4de-5989816415d5', '4b723637-4baa-509c-a11b-0a4876f60394', NULL, 7, 7, 'You haven''t given water to the weary to drink, and you have withheld bread from the hungry.'),
  ('0f578c61-1da7-51df-a636-0de40459d59c', '4b723637-4baa-509c-a11b-0a4876f60394', NULL, 8, 8, 'But as for the mighty man, he had the earth. The honorable man, he lived in it.'),
  ('2d53f697-2ef0-5cba-a463-a83e6394f66b', '4b723637-4baa-509c-a11b-0a4876f60394', NULL, 9, 9, 'You have sent widows away empty, and the arms of the fatherless have been broken.'),
  ('2fe13e06-1988-5eb3-a782-4ceebd328e51', '4b723637-4baa-509c-a11b-0a4876f60394', NULL, 10, 10, 'Therefore snares are around you. Sudden fear troubles you,'),
  ('d4bad532-8f75-5c00-a89d-932dd92d4ba9', '4b723637-4baa-509c-a11b-0a4876f60394', NULL, 11, 11, 'or darkness, so that you can not see, and floods of waters cover you.'),
  ('93777a51-6629-59c2-a9d8-6ef01a475c18', '4b723637-4baa-509c-a11b-0a4876f60394', NULL, 12, 12, '"Isn''t God in the heights of heaven? See the height of the stars, how high they are!'),
  ('c6a006c1-e47b-535f-aa79-fd9ed073901c', '4b723637-4baa-509c-a11b-0a4876f60394', NULL, 13, 13, 'You say, ''What does God know? Can he judge through the thick darkness?'),
  ('9c0d98a0-fede-56d6-a00e-c5d52370052d', '4b723637-4baa-509c-a11b-0a4876f60394', NULL, 14, 14, 'Thick clouds are a covering to him, so that he doesn''t see. He walks on the vault of the sky.'''),
  ('20e9cb42-0874-5f73-aa9d-d554644a33d0', '4b723637-4baa-509c-a11b-0a4876f60394', NULL, 15, 15, 'Will you keep the old way, which wicked men have trodden,'),
  ('957cee51-0fd0-5376-ad45-af3f57a58e34', '4b723637-4baa-509c-a11b-0a4876f60394', NULL, 16, 16, 'who were snatched away before their time, whose foundation was poured out as a stream,'),
  ('8a95351a-755d-5e85-a4a4-2eb9b905dbe7', '4b723637-4baa-509c-a11b-0a4876f60394', NULL, 17, 17, 'who said to God, ''Depart from us;'' and, ''What can the Almighty do for us?'''),
  ('dc86ecc9-35a9-5ad4-a8b0-aa91d572266a', '4b723637-4baa-509c-a11b-0a4876f60394', NULL, 18, 18, 'Yet he filled their houses with good things, but the counsel of the wicked is far from me.'),
  ('6a464797-9384-52a8-a87e-e68bde4af57c', '4b723637-4baa-509c-a11b-0a4876f60394', NULL, 19, 19, 'The righteous see it, and are glad. The innocent ridicule them,'),
  ('18ee294d-0eae-5be3-aec7-4975011bd4ed', '4b723637-4baa-509c-a11b-0a4876f60394', NULL, 20, 20, 'saying, ''Surely those who rose up against us are cut off. The fire has consumed the remnant of them.'''),
  ('19703951-6b95-5c68-a0cc-d9487203e0be', '4b723637-4baa-509c-a11b-0a4876f60394', NULL, 21, 21, '"Acquaint yourself with him, now, and be at peace. Thereby good shall come to you.'),
  ('1b993180-5950-547f-afe5-39ad7458ff55', '4b723637-4baa-509c-a11b-0a4876f60394', NULL, 22, 22, 'Please receive instruction from his mouth, and lay up his words in your heart.'),
  ('665f6f02-b140-59c8-a0ef-55f63aaa6e3b', '4b723637-4baa-509c-a11b-0a4876f60394', NULL, 23, 23, 'If you return to the Almighty, you shall be built up, if you put away unrighteousness far from your tents.'),
  ('c9fedbe3-08c1-5b8b-a0fc-5f44d26e64cb', '4b723637-4baa-509c-a11b-0a4876f60394', NULL, 24, 24, 'Lay your treasure in the dust, the gold of Ophir among the stones of the brooks.'),
  ('22e92757-08df-5d01-a6e1-3fc7721d45e6', '4b723637-4baa-509c-a11b-0a4876f60394', NULL, 25, 25, 'The Almighty will be your treasure, and precious silver to you.'),
  ('86aeecdb-e72d-54ed-affa-012e9f69554b', '4b723637-4baa-509c-a11b-0a4876f60394', NULL, 26, 26, 'For then you will delight yourself in the Almighty, and shall lift up your face to God.'),
  ('76f37acd-1543-5cfc-af14-5be329b8fd5d', '4b723637-4baa-509c-a11b-0a4876f60394', NULL, 27, 27, 'You shall make your prayer to him, and he will hear you. You shall pay your vows.'),
  ('c5be1bc2-e68e-577e-acf6-a0e3471232d3', '4b723637-4baa-509c-a11b-0a4876f60394', NULL, 28, 28, 'You shall also decree a thing, and it shall be established to you. Light shall shine on your ways.'),
  ('50048766-b810-5a6b-aeee-955ca9272204', '4b723637-4baa-509c-a11b-0a4876f60394', NULL, 29, 29, 'When they cast down, you shall say, ''be lifted up.'' He will save the humble person.'),
  ('fda8fe94-4e9b-52f2-a968-52d1f1a14abe', '4b723637-4baa-509c-a11b-0a4876f60394', NULL, 30, 30, 'He will even deliver him who is not innocent. Yes, he shall be delivered through the cleanness of your hands."'),
  ('c7c6967c-c218-5e25-a543-80c975da7d03', '7c542d61-0cb5-5c17-aa33-cfc9b8900a2d', NULL, 1, 1, 'Then Job answered,'),
  ('18ded46c-e240-5ddb-a479-37cd3ccded97', '7c542d61-0cb5-5c17-aa33-cfc9b8900a2d', NULL, 2, 2, '"Even today my complaint is rebellious. His hand is heavy in spite of my groaning.'),
  ('5d737fbf-812c-5401-ad0f-e1a68bb76538', '7c542d61-0cb5-5c17-aa33-cfc9b8900a2d', NULL, 3, 3, 'Oh that I knew where I might find him! That I might come even to his seat!'),
  ('a074b97d-7574-579d-a7a6-32b89f294963', '7c542d61-0cb5-5c17-aa33-cfc9b8900a2d', NULL, 4, 4, 'I would set my cause in order before him, and fill my mouth with arguments.'),
  ('52f42a45-8159-5a96-ae84-2b0b3e0cf7e9', '7c542d61-0cb5-5c17-aa33-cfc9b8900a2d', NULL, 5, 5, 'I would know the words which he would answer me, and understand what he would tell me.'),
  ('fbedaa71-89ec-50f7-a7d6-6ce16b6b1b66', '7c542d61-0cb5-5c17-aa33-cfc9b8900a2d', NULL, 6, 6, 'Would he contend with me in the greatness of his power? No, but he would listen to me.'),
  ('c63c3a39-98b0-5b06-adda-4cb07860af4b', '7c542d61-0cb5-5c17-aa33-cfc9b8900a2d', NULL, 7, 7, 'There the upright might reason with him, so I should be delivered forever from my judge.'),
  ('aca0cd1d-2a67-5224-acae-52e81e6a99ab', '7c542d61-0cb5-5c17-aa33-cfc9b8900a2d', NULL, 8, 8, '"If I go east, he is not there; if west, I can''t find him;'),
  ('e2bafacf-bfd0-56e3-a314-b8d5dfe2f900', '7c542d61-0cb5-5c17-aa33-cfc9b8900a2d', NULL, 9, 9, 'He works to the north, but I can''t see him. He turns south, but I can''t catch a glimpse of him.'),
  ('bf06c3e0-736a-599b-a78b-e2e2ab62fb25', '7c542d61-0cb5-5c17-aa33-cfc9b8900a2d', NULL, 10, 10, 'But he knows the way that I take. When he has tried me, I shall come forth like gold.'),
  ('edefc9dd-21b9-55d1-aeab-1902b4f25dde', '7c542d61-0cb5-5c17-aa33-cfc9b8900a2d', NULL, 11, 11, 'My foot has held fast to his steps. I have kept his way, and not turned aside.'),
  ('17d50115-5254-5865-ad78-251d082109e7', '7c542d61-0cb5-5c17-aa33-cfc9b8900a2d', NULL, 12, 12, 'I haven''t gone back from the commandment of his lips. I have treasured up the words of his mouth more than my necessary food.'),
  ('09dc3f99-a589-5f86-a03a-1414c46ff113', '7c542d61-0cb5-5c17-aa33-cfc9b8900a2d', NULL, 13, 13, 'But he stands alone, and who can oppose him? What his soul desires, even that he does.'),
  ('eb27b727-feeb-5047-adb4-96dec35055d6', '7c542d61-0cb5-5c17-aa33-cfc9b8900a2d', NULL, 14, 14, 'For he performs that which is appointed for me. Many such things are with him.'),
  ('09ec5377-1ea8-567d-ad3c-ab7e280aa73a', '7c542d61-0cb5-5c17-aa33-cfc9b8900a2d', NULL, 15, 15, 'Therefore I am terrified at his presence. When I consider, I am afraid of him.'),
  ('3aee735f-f1b0-5cea-a4d8-a56a3bbff419', '7c542d61-0cb5-5c17-aa33-cfc9b8900a2d', NULL, 16, 16, 'For God has made my heart faint. The Almighty has terrified me.'),
  ('86fdd09d-a932-5ae4-a50b-cbebfe014be5', '7c542d61-0cb5-5c17-aa33-cfc9b8900a2d', NULL, 17, 17, 'Because I was not cut off before the darkness, neither did he cover the thick darkness from my face.'),
  ('4722a99f-c808-52eb-a4cb-1fa798801068', '643c4653-4478-51db-a08d-389f7a3be3df', NULL, 1, 1, '"Why aren''t times laid up by the Almighty? Why don''t those who know him see his days?'),
  ('784edc40-f30e-5ff2-aaf2-544fdd9bf0bf', '643c4653-4478-51db-a08d-389f7a3be3df', NULL, 2, 2, 'There are people who remove the landmarks. They violently take away flocks, and feed them.'),
  ('0b5e403b-bbca-597c-aee3-03aa55517ab3', '643c4653-4478-51db-a08d-389f7a3be3df', NULL, 3, 3, 'They drive away the donkey of the fatherless, and they take the widow''s ox for a pledge.'),
  ('e2975548-2602-5bcf-a712-9c1b088223aa', '643c4653-4478-51db-a08d-389f7a3be3df', NULL, 4, 4, 'They turn the needy out of the way. The poor of the earth all hide themselves.'),
  ('625c6666-5984-5512-a068-4b9574f096ca', '643c4653-4478-51db-a08d-389f7a3be3df', NULL, 5, 5, 'Behold, as wild donkeys in the desert, they go forth to their work, seeking diligently for food. The wilderness yields them bread for their children.'),
  ('5eb82b6d-845d-529b-ae6c-4cc945bf998b', '643c4653-4478-51db-a08d-389f7a3be3df', NULL, 6, 6, 'They cut their provender in the field. They glean the vineyard of the wicked.'),
  ('a53b719f-ba83-5461-a82b-d9d3ed5e4c18', '643c4653-4478-51db-a08d-389f7a3be3df', NULL, 7, 7, 'They lie all night naked without clothing, and have no covering in the cold.'),
  ('020c9e55-aa58-5b69-a841-006eaee7a2d2', '643c4653-4478-51db-a08d-389f7a3be3df', NULL, 8, 8, 'They are wet with the showers of the mountains, and embrace the rock for lack of a shelter.'),
  ('dc6669f6-3218-5643-a325-36694918bb6e', '643c4653-4478-51db-a08d-389f7a3be3df', NULL, 9, 9, 'There are those who pluck the fatherless from the breast, and take a pledge of the poor,'),
  ('01ef0d21-6766-5702-aaf3-874ca6579fdd', '643c4653-4478-51db-a08d-389f7a3be3df', NULL, 10, 10, 'So that they go around naked without clothing. Being hungry, they carry the sheaves.'),
  ('7157599f-9f91-5fa9-ad0a-59ed5d45a9df', '643c4653-4478-51db-a08d-389f7a3be3df', NULL, 11, 11, 'They make oil within the walls of these men. They tread wine presses, and suffer thirst.'),
  ('ac213875-21b9-53bf-a56b-738873d1124c', '643c4653-4478-51db-a08d-389f7a3be3df', NULL, 12, 12, 'From out of the populous city, men groan. The soul of the wounded cries out, yet God doesn''t regard the folly.'),
  ('af77affa-bd3b-55f6-aed0-713375b0d1d3', '643c4653-4478-51db-a08d-389f7a3be3df', NULL, 13, 13, '"These are of those who rebel against the light. They don''t know its ways, nor stay in its paths.'),
  ('036e4d50-cead-5297-aa3b-465e670e18e6', '643c4653-4478-51db-a08d-389f7a3be3df', NULL, 14, 14, 'The murderer rises with the light. He kills the poor and needy. In the night he is like a thief.'),
  ('09bb3171-af88-54b7-a4f9-0e4f58029f13', '643c4653-4478-51db-a08d-389f7a3be3df', NULL, 15, 15, 'The eye also of the adulterer waits for the twilight, saying, ''No eye shall see me.'' He disguises his face.'),
  ('80513fb2-d392-5b56-ae04-4e446312e9f2', '643c4653-4478-51db-a08d-389f7a3be3df', NULL, 16, 16, 'In the dark they dig through houses. They shut themselves up in the daytime. They don''t know the light.'),
  ('e9aabc24-295c-5a6c-acab-eadaebb9612e', '643c4653-4478-51db-a08d-389f7a3be3df', NULL, 17, 17, 'For the morning is to all of them like thick darkness, for they know the terrors of the thick darkness.'),
  ('a8713e71-58c6-57de-aab9-fd60ecc1d199', '643c4653-4478-51db-a08d-389f7a3be3df', NULL, 18, 18, '"They are foam on the surface of the waters. Their portion is cursed in the earth. They don''t turn into the way of the vineyards.'),
  ('a5ed81a4-ef87-5b91-a2bd-0f70f801c9d7', '643c4653-4478-51db-a08d-389f7a3be3df', NULL, 19, 19, 'Drought and heat consume the snow waters, so does Sheol those who have sinned.'),
  ('51fd7d47-4dae-5f23-afcc-3ebb4255d56e', '643c4653-4478-51db-a08d-389f7a3be3df', NULL, 20, 20, 'The womb shall forget him. The worm shall feed sweetly on him. He shall be no more remembered. Unrighteousness shall be broken as a tree.'),
  ('55863d5f-98e2-5ea2-ac7a-457e020e4e12', '643c4653-4478-51db-a08d-389f7a3be3df', NULL, 21, 21, 'He devours the barren who don''t bear. He shows no kindness to the widow.'),
  ('15fb95d6-c733-5a19-a64b-d3a2af16304e', '643c4653-4478-51db-a08d-389f7a3be3df', NULL, 22, 22, 'Yet God preserves the mighty by his power. He rises up who has no assurance of life.'),
  ('6d01f9eb-d34e-58a6-a25d-d4529b258825', '643c4653-4478-51db-a08d-389f7a3be3df', NULL, 23, 23, 'God gives them security, and they rest in it. His eyes are on their ways.'),
  ('aad788c9-0a75-5e0c-a391-b93a826b05e2', '643c4653-4478-51db-a08d-389f7a3be3df', NULL, 24, 24, 'They are exalted; yet a little while, and they are gone. Yes, they are brought low, they are taken out of the way as all others, and are cut off as the tops of the ears of grain.'),
  ('e9ffee27-45a8-554a-a32f-0acf72d82831', '643c4653-4478-51db-a08d-389f7a3be3df', NULL, 25, 25, 'If it isn''t so now, who will prove me a liar, and make my speech worth nothing?"'),
  ('a310c2e4-0004-544c-a0aa-8e949a45cc4f', '1acdd87d-4a45-591b-a1ee-a8c48cb6c45f', NULL, 1, 1, 'Then Bildad the Shuhite answered,'),
  ('3dc5c11f-6f0c-5237-aaef-1a600d0d9b21', '1acdd87d-4a45-591b-a1ee-a8c48cb6c45f', NULL, 2, 2, '"Dominion and fear are with him. He makes peace in his high places.'),
  ('1a7ddcca-54f0-5d21-a6ff-78ab7413d0b9', '1acdd87d-4a45-591b-a1ee-a8c48cb6c45f', NULL, 3, 3, 'Can his armies be counted? On whom does his light not arise?'),
  ('f6f22667-eff9-5b92-ad14-c9f0b96d6293', '1acdd87d-4a45-591b-a1ee-a8c48cb6c45f', NULL, 4, 4, 'How then can man be just with God? Or how can he who is born of a woman be clean?'),
  ('f4507384-c380-513b-ad14-beffd51c15f9', '1acdd87d-4a45-591b-a1ee-a8c48cb6c45f', NULL, 5, 5, 'Behold, even the moon has no brightness, and the stars are not pure in his sight;'),
  ('b70ee210-8a6c-51f4-a4c8-c30ebde1c21f', '1acdd87d-4a45-591b-a1ee-a8c48cb6c45f', NULL, 6, 6, 'How much less man, who is a worm, the son of man, who is a worm!"'),
  ('23eb841e-a7e1-589e-adf4-446585180465', 'ecf7a70f-3260-55a8-a431-291524bb5dea', NULL, 1, 1, 'Then Job answered,'),
  ('85dfe5d3-7c3a-5449-af8a-19b108ab9d38', 'ecf7a70f-3260-55a8-a431-291524bb5dea', NULL, 2, 2, '"How have you helped him who is without power! How have you saved the arm that has no strength!'),
  ('80c54ebc-4b15-5e64-a02d-33f1b8438c17', 'ecf7a70f-3260-55a8-a431-291524bb5dea', NULL, 3, 3, 'How have you counseled him who has no wisdom, and plentifully declared sound knowledge!'),
  ('ffaa01c8-8f86-5c3e-a637-db6acf52d2f7', 'ecf7a70f-3260-55a8-a431-291524bb5dea', NULL, 4, 4, 'To whom have you uttered words? Whose spirit came forth from you?'),
  ('9c825a4b-4930-53cf-ae19-d79fdc7467e9', 'ecf7a70f-3260-55a8-a431-291524bb5dea', NULL, 5, 5, '"Those who are deceased tremble, those beneath the waters and all that live in them.'),
  ('79ffe6e4-3378-531a-ae85-55687fc546db', 'ecf7a70f-3260-55a8-a431-291524bb5dea', NULL, 6, 6, 'Sheol is naked before God, and Abaddon has no covering.'),
  ('c4f94fe5-76b7-5fd9-ac65-e4a98d021a5f', 'ecf7a70f-3260-55a8-a431-291524bb5dea', NULL, 7, 7, 'He stretches out the north over empty space, and hangs the earth on nothing.'),
  ('a7488cf0-14f6-54d9-a12b-4fcf0431be50', 'ecf7a70f-3260-55a8-a431-291524bb5dea', NULL, 8, 8, 'He binds up the waters in his thick clouds, and the cloud is not burst under them.'),
  ('7f0c5040-5ced-58a6-aaf6-2dbca68d2510', 'ecf7a70f-3260-55a8-a431-291524bb5dea', NULL, 9, 9, 'He encloses the face of his throne, and spreads his cloud on it.'),
  ('6e9caa49-b67e-5dcb-afe7-46e4222e9317', 'ecf7a70f-3260-55a8-a431-291524bb5dea', NULL, 10, 10, 'He has described a boundary on the surface of the waters, and to the confines of light and darkness.'),
  ('28aa313b-5332-5964-a38c-d5a6b7eca405', 'ecf7a70f-3260-55a8-a431-291524bb5dea', NULL, 11, 11, 'The pillars of heaven tremble and are astonished at his rebuke.'),
  ('b9672579-2d57-52b8-a2ba-601330b0fd83', 'ecf7a70f-3260-55a8-a431-291524bb5dea', NULL, 12, 12, 'He stirs up the sea with his power, and by his understanding he strikes through Rahab.'),
  ('9d0f8cd3-7741-5f58-a401-11b0453cb9b4', 'ecf7a70f-3260-55a8-a431-291524bb5dea', NULL, 13, 13, 'By his Spirit the heavens are garnished. His hand has pierced the swift serpent.'),
  ('960cbe6d-6abd-5627-a5b3-f7a0bdb1e780', 'ecf7a70f-3260-55a8-a431-291524bb5dea', NULL, 14, 14, 'Behold, these are but the outskirts of his ways. How small a whisper do we hear of him! But the thunder of his power who can understand?"'),
  ('68abb1a1-342b-5fc4-a32d-e78c2b497787', '87b6b6de-8936-51d7-aa02-5db572d95323', NULL, 1, 1, 'Job again took up his parable, and said,'),
  ('5219b9e2-daeb-5034-a53d-59d9217451d3', '87b6b6de-8936-51d7-aa02-5db572d95323', NULL, 2, 2, '"As God lives, who has taken away my right, the Almighty, who has made my soul bitter.'),
  ('fbe2c812-4659-533d-a89f-fe9e04411056', '87b6b6de-8936-51d7-aa02-5db572d95323', NULL, 3, 3, '(For the length of my life is still in me, and the spirit of God is in my nostrils);'),
  ('848435f6-20da-5693-a42a-af7ebec32535', '87b6b6de-8936-51d7-aa02-5db572d95323', NULL, 4, 4, 'surely my lips shall not speak unrighteousness, neither shall my tongue utter deceit.'),
  ('dba3e1de-6513-5b1d-aabd-e0b9a022a749', '87b6b6de-8936-51d7-aa02-5db572d95323', NULL, 5, 5, 'Far be it from me that I should justify you. Until I die I will not put away my integrity from me.'),
  ('b6438911-1515-5c71-af81-432005923663', '87b6b6de-8936-51d7-aa02-5db572d95323', NULL, 6, 6, 'I hold fast to my righteousness, and will not let it go. My heart shall not reproach me so long as I live.'),
  ('79821b46-bf25-57b7-ae33-9e45cc86d84e', '87b6b6de-8936-51d7-aa02-5db572d95323', NULL, 7, 7, '"Let my enemy be as the wicked. Let him who rises up against me be as the unrighteous.'),
  ('d1a05bea-6ce6-5fc5-af06-8d15370025eb', '87b6b6de-8936-51d7-aa02-5db572d95323', NULL, 8, 8, 'For what is the hope of the godless, when he is cut off, when God takes away his life?'),
  ('61ecf95b-2216-5551-a803-f75074be7c88', '87b6b6de-8936-51d7-aa02-5db572d95323', NULL, 9, 9, 'Will God hear his cry when trouble comes on him?'),
  ('0b7281d0-b281-512e-a124-cf138d825e39', '87b6b6de-8936-51d7-aa02-5db572d95323', NULL, 10, 10, 'Will he delight himself in the Almighty, and call on God at all times?'),
  ('4aec33de-c20a-5f56-ac4e-ba6634e2bef9', '87b6b6de-8936-51d7-aa02-5db572d95323', NULL, 11, 11, 'I will teach you about the hand of God. That which is with the Almighty will I not conceal.'),
  ('1130fc57-c1e8-5a74-a31a-de5f69df4a13', '87b6b6de-8936-51d7-aa02-5db572d95323', NULL, 12, 12, 'Behold, all of you have seen it yourselves; why then have you become altogether vain?'),
  ('03bc2333-3a55-52e3-ab7e-c836c63a9519', '87b6b6de-8936-51d7-aa02-5db572d95323', NULL, 13, 13, '"This is the portion of a wicked man with God, the heritage of oppressors, which they receive from the Almighty.'),
  ('ec93a968-72ff-5079-a434-d47e88e56a0d', '87b6b6de-8936-51d7-aa02-5db572d95323', NULL, 14, 14, 'If his children are multiplied, it is for the sword. His offspring shall not be satisfied with bread.'),
  ('20701200-51a6-5162-a170-9148c0717ff3', '87b6b6de-8936-51d7-aa02-5db572d95323', NULL, 15, 15, 'Those who remain of him shall be buried in death. His widows shall make no lamentation.'),
  ('00edd8a9-f5a0-51ad-a34a-31101eb197cb', '87b6b6de-8936-51d7-aa02-5db572d95323', NULL, 16, 16, 'Though he heap up silver as the dust, and prepare clothing as the clay;'),
  ('2cd2119b-4c73-5b23-ad5e-47eaae257d88', '87b6b6de-8936-51d7-aa02-5db572d95323', NULL, 17, 17, 'he may prepare it, but the just shall put it on, and the innocent shall divide the silver.'),
  ('5d63c967-9d20-5bb6-a571-2b59cd708cbb', '87b6b6de-8936-51d7-aa02-5db572d95323', NULL, 18, 18, 'He builds his house as the moth, as a booth which the watchman makes.'),
  ('b219518c-784a-5525-a7f0-66962fb0b525', '87b6b6de-8936-51d7-aa02-5db572d95323', NULL, 19, 19, 'He lies down rich, but he shall not do so again. He opens his eyes, and he is not.'),
  ('241ca3b4-7f90-5860-a7e8-8d0aec58f0ba', '87b6b6de-8936-51d7-aa02-5db572d95323', NULL, 20, 20, 'Terrors overtake him like waters. A storm steals him away in the night.'),
  ('87607a21-3974-5941-a1ad-1dd41e089f0e', '87b6b6de-8936-51d7-aa02-5db572d95323', NULL, 21, 21, 'The east wind carries him away, and he departs. It sweeps him out of his place.'),
  ('8ed0a1de-6469-58b8-a321-855ad20c7c42', '87b6b6de-8936-51d7-aa02-5db572d95323', NULL, 22, 22, 'For it hurls at him, and does not spare, as he flees away from his hand.'),
  ('ae655146-4b25-54bb-a36f-11b6f9a49ca4', '87b6b6de-8936-51d7-aa02-5db572d95323', NULL, 23, 23, 'Men shall clap their hands at him, and shall hiss him out of his place.'),
  ('d68c0ee9-ad23-552a-a111-21050acbe949', '35e08749-c7ab-517f-a6f7-155b6352b09e', NULL, 1, 1, '"Surely there is a mine for silver, and a place for gold which they refine.'),
  ('d6fd4a95-e3ea-5d29-aad3-bb0757536119', '35e08749-c7ab-517f-a6f7-155b6352b09e', NULL, 2, 2, 'Iron is taken out of the earth, and copper is smelted out of the ore.'),
  ('56d635b5-9de0-5b6f-a64d-86fc7ba39259', '35e08749-c7ab-517f-a6f7-155b6352b09e', NULL, 3, 3, 'Man sets an end to darkness, and searches out, to the furthest bound, the stones of obscurity and of thick darkness.'),
  ('ff299dd4-e135-5857-ad62-5b38f2f85b82', '35e08749-c7ab-517f-a6f7-155b6352b09e', NULL, 4, 4, 'He breaks open a shaft away from where people live. They are forgotten by the foot. They hang far from men, they swing back and forth.'),
  ('7294bf65-1ecc-546f-a8de-5acb626c7e16', '35e08749-c7ab-517f-a6f7-155b6352b09e', NULL, 5, 5, 'As for the earth, out of it comes bread; Underneath it is turned up as it were by fire.'),
  ('2e843999-de53-5dd0-a9df-5f2675970395', '35e08749-c7ab-517f-a6f7-155b6352b09e', NULL, 6, 6, 'Sapphires come from its rocks. It has dust of gold.'),
  ('6e2a12f4-abf3-5095-a69a-e815c5e85edd', '35e08749-c7ab-517f-a6f7-155b6352b09e', NULL, 7, 7, 'That path no bird of prey knows, neither has the falcon''s eye seen it.'),
  ('a45bf377-d84a-5562-a076-44ea139e01fc', '35e08749-c7ab-517f-a6f7-155b6352b09e', NULL, 8, 8, 'The proud animals have not trodden it, nor has the fierce lion passed by there.'),
  ('65dee618-27ce-5f23-afc0-1bcc3ce1f2cd', '35e08749-c7ab-517f-a6f7-155b6352b09e', NULL, 9, 9, 'He puts forth his hand on the flinty rock, and he overturns the mountains by the roots.'),
  ('a5289fcb-d135-5e0c-a77f-fca1e047d134', '35e08749-c7ab-517f-a6f7-155b6352b09e', NULL, 10, 10, 'He cuts out channels among the rocks. His eye sees every precious thing.'),
  ('ef22ea3a-04b8-5f4a-a6c8-d6c3a6d81de5', '35e08749-c7ab-517f-a6f7-155b6352b09e', NULL, 11, 11, 'He binds the streams that they don''t trickle. The thing that is hidden he brings forth to light.'),
  ('6150b7bd-a035-5b16-ab37-49af9c69dbfa', '35e08749-c7ab-517f-a6f7-155b6352b09e', NULL, 12, 12, '"But where shall wisdom be found? Where is the place of understanding?'),
  ('041c3cf3-c79e-5566-acd4-5fc82c1cbba8', '35e08749-c7ab-517f-a6f7-155b6352b09e', NULL, 13, 13, 'Man doesn''t know its price; Neither is it found in the land of the living.'),
  ('ccb8495c-75e7-5273-a44e-37e519fabce8', '35e08749-c7ab-517f-a6f7-155b6352b09e', NULL, 14, 14, 'The deep says, ''It isn''t in me.'' The sea says, ''It isn''t with me.'''),
  ('7e4f4f03-38ca-595d-af4a-98ebeb39a849', '35e08749-c7ab-517f-a6f7-155b6352b09e', NULL, 15, 15, 'It can''t be gotten for gold, neither shall silver be weighed for its price.'),
  ('442bdb9d-0f8e-56e4-a3e3-4dfea6b91d37', '35e08749-c7ab-517f-a6f7-155b6352b09e', NULL, 16, 16, 'It can''t be valued with the gold of Ophir, with the precious onyx, or the sapphire.'),
  ('08d9a88f-64cd-5c40-ad03-af10796ca09f', '35e08749-c7ab-517f-a6f7-155b6352b09e', NULL, 17, 17, 'Gold and glass can''t equal it, neither shall it be exchanged for jewels of fine gold.'),
  ('480ced53-1ebe-5583-afcb-a516533695fa', '35e08749-c7ab-517f-a6f7-155b6352b09e', NULL, 18, 18, 'No mention shall be made of coral or of crystal. Yes, the price of wisdom is above rubies.'),
  ('da9dbf1e-131f-56e3-a002-223d4804300e', '35e08749-c7ab-517f-a6f7-155b6352b09e', NULL, 19, 19, 'The topaz of Ethiopia shall not equal it, Neither shall it be valued with pure gold.'),
  ('18dd6f0e-e31b-55de-a398-16f741d4fef2', '35e08749-c7ab-517f-a6f7-155b6352b09e', NULL, 20, 20, 'Where then does wisdom come from? Where is the place of understanding?'),
  ('57ce512d-9223-5aba-a885-2206ab505bcc', '35e08749-c7ab-517f-a6f7-155b6352b09e', NULL, 21, 21, 'Seeing it is hidden from the eyes of all living, and kept close from the birds of the sky.'),
  ('eb6c9f92-f3c4-5410-a0fd-6bdfbd043695', '35e08749-c7ab-517f-a6f7-155b6352b09e', NULL, 22, 22, 'Destruction and Death say, ''We have heard a rumor of it with our ears.'''),
  ('f0b21c70-7574-56d5-aa5c-d261d4edd300', '35e08749-c7ab-517f-a6f7-155b6352b09e', NULL, 23, 23, '"God understands its way, and he knows its place.'),
  ('3939439c-a91c-57e8-a1b0-54356fd67370', '35e08749-c7ab-517f-a6f7-155b6352b09e', NULL, 24, 24, 'For he looks to the ends of the earth, and sees under the whole sky.'),
  ('90695901-f0d9-5662-ae25-0afd80e953cf', '35e08749-c7ab-517f-a6f7-155b6352b09e', NULL, 25, 25, 'He establishes the force of the wind. Yes, he measures out the waters by measure.'),
  ('a61b509c-b00e-5115-aafc-2307bdb53eb9', '35e08749-c7ab-517f-a6f7-155b6352b09e', NULL, 26, 26, 'When he made a decree for the rain, and a way for the lightning of the thunder;'),
  ('d7fbf6a8-7fac-5a43-abf1-ebba4aea2518', '35e08749-c7ab-517f-a6f7-155b6352b09e', NULL, 27, 27, 'then he saw it, and declared it. He established it, yes, and searched it out.'),
  ('d4fed3cc-b546-51b8-af0b-b4dde60b9ff1', '35e08749-c7ab-517f-a6f7-155b6352b09e', NULL, 28, 28, 'To man he said, ''Behold, the fear of the Lord, that is wisdom. To depart from evil is understanding.''"'),
  ('4b5cd76d-0f95-5130-a176-0eac9a574169', '52b078b3-97b6-5f0d-a653-9ec75574acf9', NULL, 1, 1, 'Job again took up his parable, and said,'),
  ('864209db-0649-5c5a-a618-833adb109b39', '52b078b3-97b6-5f0d-a653-9ec75574acf9', NULL, 2, 2, '"Oh that I were as in the months of old, as in the days when God watched over me;'),
  ('1e1efa3c-cfea-58f3-ad7d-6bd5d60f29a6', '52b078b3-97b6-5f0d-a653-9ec75574acf9', NULL, 3, 3, 'when his lamp shone on my head, and by his light I walked through darkness,'),
  ('bb776339-0c01-5b35-ad14-641e0fd6bb95', '52b078b3-97b6-5f0d-a653-9ec75574acf9', NULL, 4, 4, 'as I was in the ripeness of my days, when the friendship of God was in my tent,'),
  ('c442bae0-1d9d-54b9-a681-eec2c5aa4a46', '52b078b3-97b6-5f0d-a653-9ec75574acf9', NULL, 5, 5, 'when the Almighty was yet with me, and my children were around me,'),
  ('4183d834-9cd3-554b-a224-0a193b70824a', '52b078b3-97b6-5f0d-a653-9ec75574acf9', NULL, 6, 6, 'when my steps were washed with butter, and the rock poured out streams of oil for me,'),
  ('cc2dc3a1-908d-5668-a2cd-a8c66a0b52ab', '52b078b3-97b6-5f0d-a653-9ec75574acf9', NULL, 7, 7, 'when I went forth to the city gate, when I prepared my seat in the street.'),
  ('2dd20749-74b9-55a7-af83-ebc9d19ac5c7', '52b078b3-97b6-5f0d-a653-9ec75574acf9', NULL, 8, 8, 'The young men saw me and hid themselves. The aged rose up and stood.'),
  ('f64e3d82-7af5-5feb-affb-3c78545df055', '52b078b3-97b6-5f0d-a653-9ec75574acf9', NULL, 9, 9, 'The princes refrained from talking, and laid their hand on their mouth.'),
  ('2d8a3792-faa6-5cf1-aeff-b56202eef238', '52b078b3-97b6-5f0d-a653-9ec75574acf9', NULL, 10, 10, 'The voice of the nobles was hushed, and their tongue stuck to the roof of their mouth.'),
  ('7f4eebf0-301e-59f5-ac87-da44ffa4fc46', '52b078b3-97b6-5f0d-a653-9ec75574acf9', NULL, 11, 11, 'For when the ear heard me, then it blessed me; and when the eye saw me, it commended me:'),
  ('16748177-85d7-54c2-af5a-440a7689a84e', '52b078b3-97b6-5f0d-a653-9ec75574acf9', NULL, 12, 12, 'Because I delivered the poor who cried, and the fatherless also, who had none to help him,'),
  ('409bdb9d-af93-5007-a12c-bc4a35c34eeb', '52b078b3-97b6-5f0d-a653-9ec75574acf9', NULL, 13, 13, 'the blessing of him who was ready to perish came on me, and I caused the widow''s heart to sing for joy.'),
  ('c7bcd447-9fc7-5675-adae-babc29f59f78', '52b078b3-97b6-5f0d-a653-9ec75574acf9', NULL, 14, 14, 'I put on righteousness, and it clothed me. My justice was as a robe and a diadem.'),
  ('dc15f20c-4d66-5260-a056-43270d104110', '52b078b3-97b6-5f0d-a653-9ec75574acf9', NULL, 15, 15, 'I was eyes to the blind, and feet to the lame.'),
  ('2ae5fa36-7b4c-5dbb-a524-a676a088ad66', '52b078b3-97b6-5f0d-a653-9ec75574acf9', NULL, 16, 16, 'I was a father to the needy. The cause of him who I didn''t know, I searched out.'),
  ('c1fb683d-a48c-55f0-ada5-2ce4eacb601e', '52b078b3-97b6-5f0d-a653-9ec75574acf9', NULL, 17, 17, 'I broke the jaws of the unrighteous, and plucked the prey out of his teeth.'),
  ('d6ec5a68-9c1b-5711-af85-ccd2ed04b563', '52b078b3-97b6-5f0d-a653-9ec75574acf9', NULL, 18, 18, 'Then I said, ''I shall die in my own house, I shall number my days as the sand.'),
  ('d7210607-5c73-5d23-a266-54d72017a978', '52b078b3-97b6-5f0d-a653-9ec75574acf9', NULL, 19, 19, 'My root is spread out to the waters. The dew lies all night on my branch.'),
  ('5291a15a-7cbd-5d3b-ae0e-08c5b7afbb30', '52b078b3-97b6-5f0d-a653-9ec75574acf9', NULL, 20, 20, 'My glory is fresh in me. My bow is renewed in my hand.'''),
  ('2318d2ee-de65-5b83-ab82-a3b7879ad980', '52b078b3-97b6-5f0d-a653-9ec75574acf9', NULL, 21, 21, '"Men listened to me, waited, and kept silence for my counsel.'),
  ('f4867646-3e6c-5f37-ad29-93e187875bb5', '52b078b3-97b6-5f0d-a653-9ec75574acf9', NULL, 22, 22, 'After my words they didn''t speak again. My speech fell on them.'),
  ('b0c4064f-8061-5148-adad-f122f2656187', '52b078b3-97b6-5f0d-a653-9ec75574acf9', NULL, 23, 23, 'They waited for me as for the rain. Their mouths drank as with the spring rain.'),
  ('d9957917-2598-5b1f-a3cc-201bc1df5a68', '52b078b3-97b6-5f0d-a653-9ec75574acf9', NULL, 24, 24, 'I smiled on them when they had no confidence. They didn''t reject the light of my face.'),
  ('9033bfee-7700-55da-a32e-1aa15a391c6b', '52b078b3-97b6-5f0d-a653-9ec75574acf9', NULL, 25, 25, 'I chose out their way, and sat as chief. I lived as a king in the army, as one who comforts the mourners.'),
  ('1203c7ca-9189-52f5-ab02-9fca101ef203', '28e9dec6-9489-5205-a173-b3a2087c44ee', NULL, 1, 1, '"But now those who are younger than I have me in derision, whose fathers I would have disdained to put with my sheep dogs.'),
  ('db603329-1143-5b8e-a0e9-4d838eb171ce', '28e9dec6-9489-5205-a173-b3a2087c44ee', NULL, 2, 2, 'Of what use is the strength of their hands to me, men in whom ripe age has perished?'),
  ('e3340650-e4a5-52bd-a845-d12bdc349395', '28e9dec6-9489-5205-a173-b3a2087c44ee', NULL, 3, 3, 'They are gaunt from lack and famine. They gnaw the dry ground, in the gloom of waste and desolation.'),
  ('f96c00aa-4ae1-5704-a843-83e63308131e', '28e9dec6-9489-5205-a173-b3a2087c44ee', NULL, 4, 4, 'They pluck salt herbs by the bushes. The roots of the broom are their food.'),
  ('9186b854-10cf-54be-a684-acd2ce86c0e0', '28e9dec6-9489-5205-a173-b3a2087c44ee', NULL, 5, 5, 'They are driven out from the midst of men. They cry after them as after a thief;'),
  ('4e1f15bb-ab62-536f-a140-592054bba0e6', '28e9dec6-9489-5205-a173-b3a2087c44ee', NULL, 6, 6, 'So that they dwell in frightful valleys, and in holes of the earth and of the rocks.'),
  ('8757884e-efc6-5741-ae39-ae6a808d4048', '28e9dec6-9489-5205-a173-b3a2087c44ee', NULL, 7, 7, 'Among the bushes they bray; and under the nettles they are gathered together.'),
  ('84001272-80dd-5096-ae95-d69799aa1e9f', '28e9dec6-9489-5205-a173-b3a2087c44ee', NULL, 8, 8, 'They are children of fools, yes, children of base men. They were flogged out of the land.'),
  ('c05adbe6-de59-5b66-a518-0d3ecafb2b84', '28e9dec6-9489-5205-a173-b3a2087c44ee', NULL, 9, 9, '"Now I have become their song. Yes, I am a byword to them.'),
  ('d57b5c07-e693-5f6d-a7a3-a772c6f4fbcc', '28e9dec6-9489-5205-a173-b3a2087c44ee', NULL, 10, 10, 'They abhor me, they stand aloof from me, and don''t hesitate to spit in my face.'),
  ('f4b5cefc-cfd8-5700-a57a-4a11176a1a0c', '28e9dec6-9489-5205-a173-b3a2087c44ee', NULL, 11, 11, 'For he has untied his cord, and afflicted me; and they have thrown off restraint before me.'),
  ('057a89b0-af2c-5adf-a8dd-928c31c8c480', '28e9dec6-9489-5205-a173-b3a2087c44ee', NULL, 12, 12, 'On my right hand rise the rabble. They thrust aside my feet, They cast up against me their ways of destruction.'),
  ('7a581e8c-6e81-57b2-a277-00c239bba435', '28e9dec6-9489-5205-a173-b3a2087c44ee', NULL, 13, 13, 'They mar my path, They set forward my calamity, without anyone''s help.'),
  ('dfc5c551-d388-569d-a5d9-39751a88aa36', '28e9dec6-9489-5205-a173-b3a2087c44ee', NULL, 14, 14, 'As through a wide breach they come, in the midst of the ruin they roll themselves in.'),
  ('55be848a-4a6f-55e6-afa8-c29228366e82', '28e9dec6-9489-5205-a173-b3a2087c44ee', NULL, 15, 15, 'Terrors have turned on me. They chase my honor as the wind. My welfare has passed away as a cloud.'),
  ('03e6faf8-b606-51dd-ab59-37001642b37b', '28e9dec6-9489-5205-a173-b3a2087c44ee', NULL, 16, 16, '"Now my soul is poured out within me. Days of affliction have taken hold on me.'),
  ('d2e46ec9-e8a7-5740-a89c-09e32208a725', '28e9dec6-9489-5205-a173-b3a2087c44ee', NULL, 17, 17, 'In the night season my bones are pierced in me, and the pains that gnaw me take no rest.'),
  ('2dec540d-64b7-56ae-ab4c-ec07566d5b93', '28e9dec6-9489-5205-a173-b3a2087c44ee', NULL, 18, 18, 'By great force is my garment disfigured. It binds me about as the collar of my coat.'),
  ('a61f77e3-4f06-5206-af60-ed0dc3d68be7', '28e9dec6-9489-5205-a173-b3a2087c44ee', NULL, 19, 19, 'He has cast me into the mire. I have become like dust and ashes.'),
  ('50396845-dd51-50f9-ad4a-95c4c4ba7282', '28e9dec6-9489-5205-a173-b3a2087c44ee', NULL, 20, 20, 'I cry to you, and you do not answer me. I stand up, and you gaze at me.'),
  ('7c3346c1-133b-56d9-a69b-aaefb7cd791b', '28e9dec6-9489-5205-a173-b3a2087c44ee', NULL, 21, 21, 'You have turned to be cruel to me. With the might of your hand you persecute me.'),
  ('6816e852-946d-513f-a046-b009bb7350ff', '28e9dec6-9489-5205-a173-b3a2087c44ee', NULL, 22, 22, 'You lift me up to the wind, and drive me with it. You dissolve me in the storm.'),
  ('0e9b0d83-3618-5a90-a3fe-dba58d169ac8', '28e9dec6-9489-5205-a173-b3a2087c44ee', NULL, 23, 23, 'For I know that you will bring me to death, To the house appointed for all living.'),
  ('1b88e06f-ffcd-57e0-aca2-4f39abe6145e', '28e9dec6-9489-5205-a173-b3a2087c44ee', NULL, 24, 24, '"However doesn''t one stretch out a hand in his fall? Or in his calamity therefore cry for help?'),
  ('4e589e88-b747-579f-a1b6-e202c0f86bec', '28e9dec6-9489-5205-a173-b3a2087c44ee', NULL, 25, 25, 'Didn''t I weep for him who was in trouble? Wasn''t my soul grieved for the needy?'),
  ('9751a69f-547c-5fa9-aeb5-242fa24c913b', '28e9dec6-9489-5205-a173-b3a2087c44ee', NULL, 26, 26, 'When I looked for good, then evil came; When I waited for light, there came darkness.'),
  ('52bcf1de-b1ec-5604-a734-483a3420510e', '28e9dec6-9489-5205-a173-b3a2087c44ee', NULL, 27, 27, 'My heart is troubled, and doesn''t rest. Days of affliction have come on me.'),
  ('fe2af787-1dc9-5b41-ae6d-496d29dfe25d', '28e9dec6-9489-5205-a173-b3a2087c44ee', NULL, 28, 28, 'I go mourning without the sun. I stand up in the assembly, and cry for help.'),
  ('910041d0-cdc6-531a-a5a3-cf1f50481217', '28e9dec6-9489-5205-a173-b3a2087c44ee', NULL, 29, 29, 'I am a brother to jackals, and a companion to ostriches.'),
  ('5272ecd4-4845-5b31-a861-93775f3609c0', '28e9dec6-9489-5205-a173-b3a2087c44ee', NULL, 30, 30, 'My skin grows black and peels from me. My bones are burned with heat.'),
  ('f9a97a00-f919-5729-aa7b-a2e8f1f4ea8f', '28e9dec6-9489-5205-a173-b3a2087c44ee', NULL, 31, 31, 'Therefore my harp has turned to mourning, and my pipe into the voice of those who weep.'),
  ('d0719ad3-d681-5ee6-a555-0b713b86b2d0', '4f8591d4-6340-5318-a598-0ea00bdc7d35', NULL, 1, 1, '"I made a covenant with my eyes, how then should I look lustfully at a young woman?'),
  ('255d803d-56be-5972-a4a3-5e686865d9e7', '4f8591d4-6340-5318-a598-0ea00bdc7d35', NULL, 2, 2, 'For what is the portion from God above, and the heritage from the Almighty on high?'),
  ('0e61817a-808b-5670-ae17-a63e6e002f1e', '4f8591d4-6340-5318-a598-0ea00bdc7d35', NULL, 3, 3, 'Is it not calamity to the unrighteous, and disaster to the workers of iniquity?'),
  ('628d134c-79f7-530b-aa7f-0eab0e76a915', '4f8591d4-6340-5318-a598-0ea00bdc7d35', NULL, 4, 4, 'Doesn''t he see my ways, and number all my steps?'),
  ('e86dba21-76a5-59bc-aca7-8e9d96bc6089', '4f8591d4-6340-5318-a598-0ea00bdc7d35', NULL, 5, 5, '"If I have walked with falsehood, and my foot has hurried to deceit'),
  ('e9ccbdc0-417b-5f9f-a944-0fb76d04710e', '4f8591d4-6340-5318-a598-0ea00bdc7d35', NULL, 6, 6, '(let me be weighed in an even balance, that God may know my integrity);'),
  ('16bbb2b9-71c4-5408-a1db-992d80d2ad24', '4f8591d4-6340-5318-a598-0ea00bdc7d35', NULL, 7, 7, 'if my step has turned out of the way, if my heart walked after my eyes, if any defilement has stuck to my hands,'),
  ('90f8c274-69a5-5e78-a3c1-b8702faf5e41', '4f8591d4-6340-5318-a598-0ea00bdc7d35', NULL, 8, 8, 'then let me sow, and let another eat. Yes, let the produce of my field be rooted out.'),
  ('893f7360-3f4d-5b8c-a7f5-341f7adfdf90', '4f8591d4-6340-5318-a598-0ea00bdc7d35', NULL, 9, 9, '"If my heart has been enticed to a woman, and I have laid wait at my neighbor''s door,'),
  ('ed69c0e3-c63c-59f4-afe2-1ff61c7a46d2', '4f8591d4-6340-5318-a598-0ea00bdc7d35', NULL, 10, 10, 'then let my wife grind for another, and let others sleep with her.'),
  ('a57be5c3-6be1-58fd-a549-825fd025639a', '4f8591d4-6340-5318-a598-0ea00bdc7d35', NULL, 11, 11, 'For that would be a heinous crime. Yes, it would be an iniquity to be punished by the judges:'),
  ('bf7e846a-0be9-5c42-a435-ee745c7bc0ac', '4f8591d4-6340-5318-a598-0ea00bdc7d35', NULL, 12, 12, 'For it is a fire that consumes to destruction, and would root out all my increase.'),
  ('6b1f9100-0e3c-5d26-af9a-20db8bc59983', '4f8591d4-6340-5318-a598-0ea00bdc7d35', NULL, 13, 13, '"If I have despised the cause of my male servant or of my female servant, when they contended with me;'),
  ('9eaff253-706a-5e95-a6b3-9421065f2cee', '4f8591d4-6340-5318-a598-0ea00bdc7d35', NULL, 14, 14, 'What then shall I do when God rises up? When he visits, what shall I answer him?'),
  ('7a9206ce-ff34-5971-aa25-cc5c49a5eb5b', '4f8591d4-6340-5318-a598-0ea00bdc7d35', NULL, 15, 15, 'Didn''t he who made me in the womb make him? Didn''t one fashion us in the womb?'),
  ('16386f39-018e-51e5-a01d-1640571ad6f7', '4f8591d4-6340-5318-a598-0ea00bdc7d35', NULL, 16, 16, '"If I have withheld the poor from their desire, or have caused the eyes of the widow to fail,'),
  ('34a42b6d-5713-50f6-ae6a-3f55e94c4688', '4f8591d4-6340-5318-a598-0ea00bdc7d35', NULL, 17, 17, 'or have eaten my morsel alone, and the fatherless has not eaten of it'),
  ('adb406b1-90b4-54ac-a293-46cef4e7bab1', '4f8591d4-6340-5318-a598-0ea00bdc7d35', NULL, 18, 18, '(no, from my youth he grew up with me as with a father, her have I guided from my mother''s womb);'),
  ('44a08772-3eb4-5807-ae4d-8dd7dde44758', '4f8591d4-6340-5318-a598-0ea00bdc7d35', NULL, 19, 19, 'if I have seen any perish for want of clothing, or that the needy had no covering;'),
  ('b9ca0ab6-6d0f-531c-aee5-17c5e50668af', '4f8591d4-6340-5318-a598-0ea00bdc7d35', NULL, 20, 20, 'if his heart hasn''t blessed me, if he hasn''t been warmed with my sheep''s fleece;'),
  ('a3785dd3-4052-58a6-a76f-4a714d5a9ba0', '4f8591d4-6340-5318-a598-0ea00bdc7d35', NULL, 21, 21, 'if I have lifted up my hand against the fatherless, because I saw my help in the gate,'),
  ('7b4f153e-3c6e-538c-a19e-d939574c6c9c', '4f8591d4-6340-5318-a598-0ea00bdc7d35', NULL, 22, 22, 'then let my shoulder fall from the shoulder blade, and my arm be broken from the bone.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('06053619-9b66-5a4b-a1c7-ecb65c67cc44', '4f8591d4-6340-5318-a598-0ea00bdc7d35', NULL, 23, 23, 'For calamity from God is a terror to me. Because his majesty, I can do nothing.'),
  ('be416f57-8314-5c9d-a704-243daf10de6c', '4f8591d4-6340-5318-a598-0ea00bdc7d35', NULL, 24, 24, '"If I have made gold my hope, and have said to the fine gold, ''You are my confidence;'''),
  ('bbd80172-d99b-51c6-aa6a-fab0d48eb15b', '4f8591d4-6340-5318-a598-0ea00bdc7d35', NULL, 25, 25, 'If I have rejoiced because my wealth was great, and because my hand had gotten much;'),
  ('158f035b-6daa-5767-affd-8fe335620fa6', '4f8591d4-6340-5318-a598-0ea00bdc7d35', NULL, 26, 26, 'if I have seen the sun when it shined, or the moon moving in splendor,'),
  ('57c0e24c-b971-5da8-a7a4-2be7dfdbdae3', '4f8591d4-6340-5318-a598-0ea00bdc7d35', NULL, 27, 27, 'and my heart has been secretly enticed, and my hand threw a kiss from my mouth,'),
  ('6edacab1-29c3-5334-a75b-e93505902d8a', '4f8591d4-6340-5318-a598-0ea00bdc7d35', NULL, 28, 28, 'this also would be an iniquity to be punished by the judges; for I should have denied the God who is above.'),
  ('b643c32b-2a72-5c7f-af1a-2b5c1dd83a2b', '4f8591d4-6340-5318-a598-0ea00bdc7d35', NULL, 29, 29, '"If I have rejoiced at the destruction of him who hated me, or lifted up myself when evil found him;'),
  ('f54d5f91-0ef9-598c-a8e5-8524596544a2', '4f8591d4-6340-5318-a598-0ea00bdc7d35', NULL, 30, 30, '(yes, I have not allowed my mouth to sin by asking his life with a curse);'),
  ('0acc70cb-811b-5f46-a4c5-f58d6bc80f94', '4f8591d4-6340-5318-a598-0ea00bdc7d35', NULL, 31, 31, 'if the men of my tent have not said, ''Who can find one who has not been filled with his meat?'''),
  ('a3ad7d6d-c933-5591-ad48-6650af8f1fb5', '4f8591d4-6340-5318-a598-0ea00bdc7d35', NULL, 32, 32, '(the foreigner has not lodged in the street, but I have opened my doors to the traveler);'),
  ('79fa42ce-1f8b-5f0e-a0e5-b38501623ecf', '4f8591d4-6340-5318-a598-0ea00bdc7d35', NULL, 33, 33, 'if like Adam I have covered my transgressions, by hiding my iniquity in my heart,'),
  ('c0e92e23-dcdc-5475-a519-22ea6a19f009', '4f8591d4-6340-5318-a598-0ea00bdc7d35', NULL, 34, 34, 'because I feared the great multitude, and the contempt of families terrified me, so that I kept silence, and didn''t go out of the door--'),
  ('cc2164e2-4523-5090-aa4b-534944ca2f34', '4f8591d4-6340-5318-a598-0ea00bdc7d35', NULL, 35, 35, 'oh that I had one to hear me! (behold, here is my signature, let the Almighty answer me); let the accuser write my indictment!'),
  ('1fd8b931-a0da-5605-a4bc-8460ef7bbbd9', '4f8591d4-6340-5318-a598-0ea00bdc7d35', NULL, 36, 36, 'Surely I would carry it on my shoulder; and I would bind it to me as a crown.'),
  ('0e66f953-3b63-5be9-adcf-d3ccd6b9aa1a', '4f8591d4-6340-5318-a598-0ea00bdc7d35', NULL, 37, 37, 'I would declare to him the number of my steps. as a prince would I go near to him.'),
  ('cf1b8835-c8f9-5a22-a7c4-41e91b2d0c94', '4f8591d4-6340-5318-a598-0ea00bdc7d35', NULL, 38, 38, 'If my land cries out against me, and its furrows weep together;'),
  ('55f99ee1-4e3d-5ff7-aec3-3a19d4e09d7c', '4f8591d4-6340-5318-a598-0ea00bdc7d35', NULL, 39, 39, 'if I have eaten its fruits without money, or have caused its owners to lose their life,'),
  ('2da9f69b-ef46-5368-a20d-b4f59ad336d7', '4f8591d4-6340-5318-a598-0ea00bdc7d35', NULL, 40, 40, 'let briars grow instead of wheat, and stinkweed instead of barley." The words of Job are ended.'),
  ('1f7fc2af-1d67-5f18-a41c-450acf9485f9', '055463ce-fc76-5759-a647-969f8182c815', NULL, 1, 1, 'So these three men ceased to answer Job, because he was righteous in his own eyes.'),
  ('9b6602ff-ad9a-5819-a584-d9d949619f23', '055463ce-fc76-5759-a647-969f8182c815', NULL, 2, 2, 'Then the wrath of Elihu the son of Barachel, the Buzite, of the family of Ram, was kindled against Job. His wrath was kindled because he justified himself rather than God.'),
  ('9a384a6b-2589-5968-ad36-7927d9ff26c0', '055463ce-fc76-5759-a647-969f8182c815', NULL, 3, 3, 'Also his wrath was kindled against his three friends, because they had found no answer, and yet had condemned Job.'),
  ('f966d6c0-7d2a-59c2-aa45-9c4eb16ad1b9', '055463ce-fc76-5759-a647-969f8182c815', NULL, 4, 4, 'Now Elihu had waited to speak to Job, because they were elder than he.'),
  ('0cc58578-aca3-5c73-ab2d-33a3a2ebd0f8', '055463ce-fc76-5759-a647-969f8182c815', NULL, 5, 5, 'When Elihu saw that there was no answer in the mouth of these three men, his wrath was kindled.'),
  ('ae1816b4-3573-54f5-a193-b912783df2c9', '055463ce-fc76-5759-a647-969f8182c815', NULL, 6, 6, 'Elihu the son of Barachel the Buzite answered, "I am young, and you are very old; Therefore I held back, and didn''t dare show you my opinion.'),
  ('323693b9-e0af-5af7-a1af-db24820c5fb3', '055463ce-fc76-5759-a647-969f8182c815', NULL, 7, 7, 'I said, ''Days should speak, and multitude of years should teach wisdom.'''),
  ('63b6c045-680e-5f51-a18e-5560b2d9a4cd', '055463ce-fc76-5759-a647-969f8182c815', NULL, 8, 8, 'But there is a spirit in man, and the breath of the Almighty gives them understanding.'),
  ('278fea3e-46e2-5a69-aff2-c275169a1b5f', '055463ce-fc76-5759-a647-969f8182c815', NULL, 9, 9, 'It is not the great who are wise, nor the aged who understand justice.'),
  ('bdfff001-3296-5f30-ac9f-baefbfa31ce5', '055463ce-fc76-5759-a647-969f8182c815', NULL, 10, 10, 'Therefore I said, ''Listen to me; I also will show my opinion.'''),
  ('1ac432ee-f17c-5c53-adc2-1486b40159ac', '055463ce-fc76-5759-a647-969f8182c815', NULL, 11, 11, '"Behold, I waited for your words, and I listened for your reasoning, while you searched out what to say.'),
  ('5f4890a5-dd2c-575b-a5dc-0808b63c7aef', '055463ce-fc76-5759-a647-969f8182c815', NULL, 12, 12, 'Yes, I gave you my full attention, but there was no one who convinced Job, or who answered his words, among you.'),
  ('81c96255-ba77-52d9-a6d4-2f905d2b6815', '055463ce-fc76-5759-a647-969f8182c815', NULL, 13, 13, 'Beware lest you say, ''We have found wisdom, God may refute him, not man;'''),
  ('ccf27553-2f4b-5288-abce-3dda862789dd', '055463ce-fc76-5759-a647-969f8182c815', NULL, 14, 14, 'for he has not directed his words against me; neither will I answer him with your speeches.'),
  ('1518fa9f-8a42-5cfb-a43d-9e05a7e8b96a', '055463ce-fc76-5759-a647-969f8182c815', NULL, 15, 15, '"They are amazed. They answer no more. They don''t have a word to say.'),
  ('604c9b45-d526-5826-aa9e-ce7253555d00', '055463ce-fc76-5759-a647-969f8182c815', NULL, 16, 16, 'Shall I wait, because they don''t speak, because they stand still, and answer no more?'),
  ('e0b1c9fc-50a3-55f8-a5ef-082a33eebeee', '055463ce-fc76-5759-a647-969f8182c815', NULL, 17, 17, 'I also will answer my part, and I also will show my opinion.'),
  ('12db0ac4-0f47-5693-aeea-983d71713503', '055463ce-fc76-5759-a647-969f8182c815', NULL, 18, 18, 'For I am full of words. The spirit within me constrains me.'),
  ('509d55d3-b368-5ea4-a81f-d1ad21ad15f1', '055463ce-fc76-5759-a647-969f8182c815', NULL, 19, 19, 'Behold, my breast is as wine which has no vent; like new wineskins it is ready to burst.'),
  ('030ec614-b203-56c5-a7d4-b41330ae92d1', '055463ce-fc76-5759-a647-969f8182c815', NULL, 20, 20, 'I will speak, that I may be refreshed. I will open my lips and answer.'),
  ('a0c47603-cb0c-5671-afc1-fc423ffb4e83', '055463ce-fc76-5759-a647-969f8182c815', NULL, 21, 21, 'Please don''t let me respect any man''s person, neither will I give flattering titles to any man.'),
  ('28e7a741-9b4a-5f49-a84b-d60c60bdd2d5', '055463ce-fc76-5759-a647-969f8182c815', NULL, 22, 22, 'For I don''t know how to give flattering titles; or else my Maker would soon take me away.'),
  ('361b935b-94b3-52b3-a7ce-01529d2a8a1b', 'f1a2e5bb-0b03-5d35-a1b4-857dbbf2ae33', NULL, 1, 1, '"However, Job, please hear my speech, and listen to all my words.'),
  ('82a7c02b-8d3b-50da-ac2a-2b90eff55ffb', 'f1a2e5bb-0b03-5d35-a1b4-857dbbf2ae33', NULL, 2, 2, 'See now, I have opened my mouth. My tongue has spoken in my mouth.'),
  ('f981c0c5-4d0c-5904-aa80-41db5991a3f1', 'f1a2e5bb-0b03-5d35-a1b4-857dbbf2ae33', NULL, 3, 3, 'My words shall utter the uprightness of my heart. That which my lips know they shall speak sincerely.'),
  ('0fa5e96d-1f4d-5a34-a902-2517c71531ba', 'f1a2e5bb-0b03-5d35-a1b4-857dbbf2ae33', NULL, 4, 4, 'The Spirit of God has made me, and the breath of the Almighty gives me life.'),
  ('011e5627-c88c-530f-a000-c958c17527be', 'f1a2e5bb-0b03-5d35-a1b4-857dbbf2ae33', NULL, 5, 5, 'If you can, answer me. Set your words in order before me, and stand forth.'),
  ('79d14617-66f4-5bb6-af0b-0be85a67424b', 'f1a2e5bb-0b03-5d35-a1b4-857dbbf2ae33', NULL, 6, 6, 'Behold, I am toward God even as you are. I am also formed out of the clay.'),
  ('e455fd7b-9f48-542d-ad69-97ed5a18874f', 'f1a2e5bb-0b03-5d35-a1b4-857dbbf2ae33', NULL, 7, 7, 'Behold, my terror shall not make you afraid, neither shall my pressure be heavy on you.'),
  ('c1882c27-dc2b-5683-a2b9-0300d6d3bfc0', 'f1a2e5bb-0b03-5d35-a1b4-857dbbf2ae33', NULL, 8, 8, '"Surely you have spoken in my hearing, I have heard the voice of your words, saying,'),
  ('f552ac09-cf5b-5162-ae78-eb12e66c65a4', 'f1a2e5bb-0b03-5d35-a1b4-857dbbf2ae33', NULL, 9, 9, '''I am clean, without disobedience. I am innocent, neither is there iniquity in me.'),
  ('b1296d7e-4994-5a65-a8a0-525f7e2a3342', 'f1a2e5bb-0b03-5d35-a1b4-857dbbf2ae33', NULL, 10, 10, 'Behold, he finds occasions against me. He counts me for his enemy.'),
  ('04bcccc2-c0f7-5280-a088-d933d21f494c', 'f1a2e5bb-0b03-5d35-a1b4-857dbbf2ae33', NULL, 11, 11, 'He puts my feet in the stocks. He marks all my paths.'''),
  ('b46b8f53-b213-5f3d-a461-2760bb649cdf', 'f1a2e5bb-0b03-5d35-a1b4-857dbbf2ae33', NULL, 12, 12, '"Behold, I will answer you. In this you are not just, for God is greater than man.'),
  ('4b1fe5aa-9ce2-584b-ac9e-c2574b52a134', 'f1a2e5bb-0b03-5d35-a1b4-857dbbf2ae33', NULL, 13, 13, 'Why do you strive against him, because he doesn''t give account of any of his matters?'),
  ('cb23561f-e02b-5c32-a8ec-91c527d90f83', 'f1a2e5bb-0b03-5d35-a1b4-857dbbf2ae33', NULL, 14, 14, 'For God speaks once, yes twice, though man pays no attention.'),
  ('454f5d77-dd52-5811-a799-55b89bda22c7', 'f1a2e5bb-0b03-5d35-a1b4-857dbbf2ae33', NULL, 15, 15, 'In a dream, in a vision of the night, when deep sleep falls on men, in slumbering on the bed;'),
  ('3f99005f-387c-52fa-aee5-31c89402cc70', 'f1a2e5bb-0b03-5d35-a1b4-857dbbf2ae33', NULL, 16, 16, 'Then he opens the ears of men, and seals their instruction,'),
  ('084a39ca-93c0-5208-a969-5dfd39ba483f', 'f1a2e5bb-0b03-5d35-a1b4-857dbbf2ae33', NULL, 17, 17, 'That he may withdraw man from his purpose, and hide pride from man.'),
  ('2a4c8b53-bc1b-50c6-a178-51d27cb7e257', 'f1a2e5bb-0b03-5d35-a1b4-857dbbf2ae33', NULL, 18, 18, 'He keeps back his soul from the pit, and his life from perishing by the sword.'),
  ('55193612-565c-5a33-a64b-4384db763872', 'f1a2e5bb-0b03-5d35-a1b4-857dbbf2ae33', NULL, 19, 19, 'He is chastened also with pain on his bed, with continual strife in his bones;'),
  ('598eb63e-8f83-5a3f-af04-1860367d0614', 'f1a2e5bb-0b03-5d35-a1b4-857dbbf2ae33', NULL, 20, 20, 'So that his life abhors bread, and his soul dainty food.'),
  ('47c83f0e-d1a1-562e-ab13-deaaed13a54e', 'f1a2e5bb-0b03-5d35-a1b4-857dbbf2ae33', NULL, 21, 21, 'His flesh is so consumed away, that it can''t be seen. His bones that were not seen stick out.'),
  ('68db0558-f481-5c7e-a565-f9b785cfc579', 'f1a2e5bb-0b03-5d35-a1b4-857dbbf2ae33', NULL, 22, 22, 'Yes, his soul draws near to the pit, and his life to the destroyers.'),
  ('b5660126-8ad8-5dbf-a916-ecae568141ee', 'f1a2e5bb-0b03-5d35-a1b4-857dbbf2ae33', NULL, 23, 23, '"If there is beside him an angel, an interpreter, one among a thousand, to show to man what is right for him;'),
  ('1f4beaf4-69d1-5bf0-a34d-e2d17b7412f0', 'f1a2e5bb-0b03-5d35-a1b4-857dbbf2ae33', NULL, 24, 24, 'then God is gracious to him, and says, ''Deliver him from going down to the pit, I have found a ransom.'''),
  ('664b54f4-3237-5d83-adfc-b06d16db3a43', 'f1a2e5bb-0b03-5d35-a1b4-857dbbf2ae33', NULL, 25, 25, 'His flesh shall be fresher than a child''s. He returns to the days of his youth.'),
  ('76706398-0b88-5808-ab61-16e24e738b0a', 'f1a2e5bb-0b03-5d35-a1b4-857dbbf2ae33', NULL, 26, 26, 'He prays to God, and he is favorable to him, so that he sees his face with joy. He restores to man his righteousness.'),
  ('d603d0b2-ed1e-53e8-a4fe-55b769201d9b', 'f1a2e5bb-0b03-5d35-a1b4-857dbbf2ae33', NULL, 27, 27, 'He sings before men, and says, ''I have sinned, and perverted that which was right, and it didn''t profit me.'),
  ('26e85309-565a-556f-ae4e-69503173c04d', 'f1a2e5bb-0b03-5d35-a1b4-857dbbf2ae33', NULL, 28, 28, 'He has redeemed my soul from going into the pit. My life shall see the light.'''),
  ('bf9d8b7b-3176-5502-a24c-bde0cb9dd3b6', 'f1a2e5bb-0b03-5d35-a1b4-857dbbf2ae33', NULL, 29, 29, '"Behold, God works all these things, twice, yes three times, with a man,'),
  ('6f361429-0586-51c3-a695-65fead18424a', 'f1a2e5bb-0b03-5d35-a1b4-857dbbf2ae33', NULL, 30, 30, 'to bring back his soul from the pit, that he may be enlightened with the light of the living.'),
  ('e164165d-1cac-5c00-a5b6-54439ac8f1e8', 'f1a2e5bb-0b03-5d35-a1b4-857dbbf2ae33', NULL, 31, 31, 'Mark well, Job, and listen to me. Hold your peace, and I will speak.'),
  ('7dc8987a-1bff-5fe6-a76c-211bae646e47', 'f1a2e5bb-0b03-5d35-a1b4-857dbbf2ae33', NULL, 32, 32, 'If you have anything to say, answer me. Speak, for I desire to justify you.'),
  ('5a806376-1468-5ec8-ad51-55beac831d30', 'f1a2e5bb-0b03-5d35-a1b4-857dbbf2ae33', NULL, 33, 33, 'If not, listen to me. Hold your peace, and I will teach you wisdom."'),
  ('c94c23b2-a076-5264-a13e-ff36f9aa7478', '975ffae4-ab7d-5c84-a8f8-315982668bab', NULL, 1, 1, 'Moreover Elihu answered,'),
  ('85444cbe-04b3-51b0-a08f-8c84a2e554ff', '975ffae4-ab7d-5c84-a8f8-315982668bab', NULL, 2, 2, '"Hear my words, you wise men. Give ear to me, you who have knowledge.'),
  ('34326004-a31f-5012-a5be-b5020359f484', '975ffae4-ab7d-5c84-a8f8-315982668bab', NULL, 3, 3, 'For the ear tries words, as the palate tastes food.'),
  ('4c67f28f-ad82-531b-a58b-387272959e1b', '975ffae4-ab7d-5c84-a8f8-315982668bab', NULL, 4, 4, 'Let us choose for us that which is right. Let us know among ourselves what is good.'),
  ('dbac18ba-1787-5425-a22a-5ee40461f06f', '975ffae4-ab7d-5c84-a8f8-315982668bab', NULL, 5, 5, 'For Job has said, ''I am righteous, God has taken away my right:'),
  ('6d449297-24b7-5f28-a8ec-8a9d1c85017c', '975ffae4-ab7d-5c84-a8f8-315982668bab', NULL, 6, 6, 'Notwithstanding my right I am considered a liar. My wound is incurable, though I am without disobedience.'''),
  ('c6dff38f-2b94-5d12-a6f2-7219e17b75b6', '975ffae4-ab7d-5c84-a8f8-315982668bab', NULL, 7, 7, 'What man is like Job, who drinks scorn like water,'),
  ('0f1ac446-c8f3-5e83-a69f-5615e327bf0c', '975ffae4-ab7d-5c84-a8f8-315982668bab', NULL, 8, 8, 'Who goes in company with the workers of iniquity, and walks with wicked men?'),
  ('2deac1b9-b840-52b0-ad3e-2c9a4a866c70', '975ffae4-ab7d-5c84-a8f8-315982668bab', NULL, 9, 9, 'For he has said, ''It profits a man nothing that he should delight himself with God.'''),
  ('b9c1d560-83ad-5d25-a248-60fa817853bc', '975ffae4-ab7d-5c84-a8f8-315982668bab', NULL, 10, 10, '"Therefore listen to me, you men of understanding: far be it from God, that he should do wickedness, from the Almighty, that he should commit iniquity.'),
  ('96ba4d37-24a3-522a-aad8-83bc0782b663', '975ffae4-ab7d-5c84-a8f8-315982668bab', NULL, 11, 11, 'For the work of a man he will render to him, and cause every man to find according to his ways.'),
  ('05dcfd50-9bd7-5995-abf7-cedefb64058b', '975ffae4-ab7d-5c84-a8f8-315982668bab', NULL, 12, 12, 'Yes surely, God will not do wickedly, neither will the Almighty pervert justice.'),
  ('e3de9f67-7d12-573c-abc7-56e4ee7953b0', '975ffae4-ab7d-5c84-a8f8-315982668bab', NULL, 13, 13, 'Who put him in charge of the earth? or who has appointed him over the whole world?'),
  ('6c54d999-a452-506f-a1a4-4dad7517477c', '975ffae4-ab7d-5c84-a8f8-315982668bab', NULL, 14, 14, 'If he set his heart on himself, If he gathered to himself his spirit and his breath,'),
  ('38b0b19e-77f3-556f-aa25-ec5f92171514', '975ffae4-ab7d-5c84-a8f8-315982668bab', NULL, 15, 15, 'all flesh would perish together, and man would turn again to dust.'),
  ('f9dea813-4139-5917-ac53-e51adc72ea5b', '975ffae4-ab7d-5c84-a8f8-315982668bab', NULL, 16, 16, '"If now you have understanding, hear this. Listen to the voice of my words.'),
  ('767982bc-9513-586f-aa0a-dfd0e92cd8cc', '975ffae4-ab7d-5c84-a8f8-315982668bab', NULL, 17, 17, 'Shall even one who hates justice govern? Will you condemn him who is righteous and mighty?--'),
  ('34924716-e330-5878-ab55-6250b6918f5d', '975ffae4-ab7d-5c84-a8f8-315982668bab', NULL, 18, 18, 'Who says to a king, ''Vile!'' or to nobles, ''Wicked!''?'),
  ('3b2578b6-cca4-58e5-a7cc-a1283c42a033', '975ffae4-ab7d-5c84-a8f8-315982668bab', NULL, 19, 19, 'Who doesn''t respect the persons of princes, nor respects the rich more than the poor; for they all are the work of his hands.'),
  ('0a374fc9-6f51-5877-a2f4-fead701c0b2c', '975ffae4-ab7d-5c84-a8f8-315982668bab', NULL, 20, 20, 'In a moment they die, even at midnight. The people are shaken and pass away. The mighty are taken away without a hand.'),
  ('19bb8331-883a-5a73-a771-34181ca5e729', '975ffae4-ab7d-5c84-a8f8-315982668bab', NULL, 21, 21, '"For his eyes are on the ways of a man. He sees all his goings.'),
  ('d2e267c2-8178-5607-a54a-def09e7269ec', '975ffae4-ab7d-5c84-a8f8-315982668bab', NULL, 22, 22, 'There is no darkness, nor thick gloom, where the workers of iniquity may hide themselves.'),
  ('0dea10cd-ddce-55b1-afbc-9337009bd1b2', '975ffae4-ab7d-5c84-a8f8-315982668bab', NULL, 23, 23, 'For he doesn''t need to consider a man further, that he should go before God in judgment.'),
  ('7bb4134a-5ca9-5405-a3fa-afd3a2aafae2', '975ffae4-ab7d-5c84-a8f8-315982668bab', NULL, 24, 24, 'He breaks in pieces mighty men in ways past finding out, and sets others in their place.'),
  ('bebbd443-d99b-5709-aa72-c0134693a40c', '975ffae4-ab7d-5c84-a8f8-315982668bab', NULL, 25, 25, 'Therefore he takes knowledge of their works. He overturns them in the night, so that they are destroyed.'),
  ('6313f702-bf77-531d-a9e5-99203950e0bd', '975ffae4-ab7d-5c84-a8f8-315982668bab', NULL, 26, 26, 'He strikes them as wicked men in the open sight of others;'),
  ('8f1fdf8e-a7cd-5320-ac4c-765f801aefe6', '975ffae4-ab7d-5c84-a8f8-315982668bab', NULL, 27, 27, 'because they turned aside from following him, and wouldn''t pay attention to any of his ways,'),
  ('af6ba7df-eb5b-5cf1-a1e2-ad296dbc574c', '975ffae4-ab7d-5c84-a8f8-315982668bab', NULL, 28, 28, 'so that they caused the cry of the poor to come to him. He heard the cry of the afflicted.'),
  ('ed48a868-9663-5130-aa2b-a611f35a4171', '975ffae4-ab7d-5c84-a8f8-315982668bab', NULL, 29, 29, 'When he gives quietness, who then can condemn? When he hides his face, who then can see him? Alike whether to a nation, or to a man,'),
  ('39e40505-e6ea-5379-ae00-2b4a687a1cfe', '975ffae4-ab7d-5c84-a8f8-315982668bab', NULL, 30, 30, 'that the godless man may not reign, that there be no one to ensnare the people.'),
  ('4820453d-a178-5877-a169-364da0b77b12', '975ffae4-ab7d-5c84-a8f8-315982668bab', NULL, 31, 31, '"For has any said to God, ''I am guilty, but I will not offend any more.'),
  ('6607a4b7-8398-5053-afe3-8cf8f27331c8', '975ffae4-ab7d-5c84-a8f8-315982668bab', NULL, 32, 32, 'Teach me that which I don''t see. If I have done iniquity, I will do it no more''?'),
  ('25bbf795-e1d7-5961-a1be-260c288d522f', '975ffae4-ab7d-5c84-a8f8-315982668bab', NULL, 33, 33, 'Shall his recompense be as you desire, that you refuse it? For you must choose, and not I. Therefore speak what you know.'),
  ('eb5d6310-4d92-5b8e-ad81-bca79df6ec33', '975ffae4-ab7d-5c84-a8f8-315982668bab', NULL, 34, 34, 'Men of understanding will tell me, yes, every wise man who hears me:'),
  ('2055a25d-827b-58c4-a659-603b9d7da20f', '975ffae4-ab7d-5c84-a8f8-315982668bab', NULL, 35, 35, '''Job speaks without knowledge. His words are without wisdom.'''),
  ('0b2e1318-22f7-5271-acae-3b465265b9d9', '975ffae4-ab7d-5c84-a8f8-315982668bab', NULL, 36, 36, 'I wish that Job were tried to the end, because of his answering like wicked men.'),
  ('8129019d-7bcb-58d0-ac71-d06699cc1696', '975ffae4-ab7d-5c84-a8f8-315982668bab', NULL, 37, 37, 'For he adds rebellion to his sin. He claps his hands among us, and multiplies his words against God."'),
  ('412cc2c6-9eca-55f6-af45-fffc2c89c404', 'd3b3c902-a555-52d5-ae51-d382859c5944', NULL, 1, 1, 'Moreover Elihu answered,'),
  ('bd34a51c-28c5-5878-abe9-07c66950bbaf', 'd3b3c902-a555-52d5-ae51-d382859c5944', NULL, 2, 2, '"Do you think this to be your right, or do you say, ''My righteousness is more than God''s,'''),
  ('b4fddea6-beee-51bc-ae72-bd8e9ab82951', 'd3b3c902-a555-52d5-ae51-d382859c5944', NULL, 3, 3, 'That you ask, ''What advantage will it be to you? What profit shall I have, more than if I had sinned?'''),
  ('f6a090fd-e97d-5981-a308-c15083845630', 'd3b3c902-a555-52d5-ae51-d382859c5944', NULL, 4, 4, 'I will answer you, and your companions with you.'),
  ('f97033d0-1c1c-5357-a671-c722e36d431e', 'd3b3c902-a555-52d5-ae51-d382859c5944', NULL, 5, 5, 'Look to the heavens, and see. See the skies, which are higher than you.'),
  ('c31a7705-9783-5403-a94f-3a2a91e15793', 'd3b3c902-a555-52d5-ae51-d382859c5944', NULL, 6, 6, 'If you have sinned, what effect do you have against him? If your transgressions are multiplied, what do you do to him?'),
  ('71115c6f-0ee2-5941-ab9d-6df56a6c49b2', 'd3b3c902-a555-52d5-ae51-d382859c5944', NULL, 7, 7, 'If you are righteous, what do you give him? Or what does he receive from your hand?'),
  ('e7c6c38f-d7a8-5842-a0b2-4c344c95e3db', 'd3b3c902-a555-52d5-ae51-d382859c5944', NULL, 8, 8, 'Your wickedness may hurt a man as you are, and your righteousness may profit a son of man.'),
  ('cc7aa2f9-9253-5174-a9e9-f0fafcd79740', 'd3b3c902-a555-52d5-ae51-d382859c5944', NULL, 9, 9, '"By reason of the multitude of oppressions they cry out. They cry for help by reason of the arm of the mighty.'),
  ('4254b2b3-5d8a-5405-af1b-2b8c2e5f60e2', 'd3b3c902-a555-52d5-ae51-d382859c5944', NULL, 10, 10, 'But none says, ''Where is God my Maker, who gives songs in the night,'),
  ('7d2861ad-fd67-5e52-a5d3-15221c69a831', 'd3b3c902-a555-52d5-ae51-d382859c5944', NULL, 11, 11, 'who teaches us more than the animals of the earth, and makes us wiser than the birds of the sky?'''),
  ('b7fdc8d9-0511-561a-a589-521db5e341b6', 'd3b3c902-a555-52d5-ae51-d382859c5944', NULL, 12, 12, 'There they cry, but none gives answer, because of the pride of evil men.'),
  ('d1245193-1de1-5703-a75e-30c448df4a6e', 'd3b3c902-a555-52d5-ae51-d382859c5944', NULL, 13, 13, 'Surely God will not hear an empty cry, neither will the Almighty regard it.'),
  ('08f721b6-2cc9-5b1b-ac89-023a1e4d57fa', 'd3b3c902-a555-52d5-ae51-d382859c5944', NULL, 14, 14, 'How much less when you say you don''t see him. The cause is before him, and you wait for him!'),
  ('8aa23b0f-2610-54f5-a8f8-b7254dd34e7b', 'd3b3c902-a555-52d5-ae51-d382859c5944', NULL, 15, 15, 'But now, because he has not visited in his anger, neither does he greatly regard arrogance.'),
  ('6f466316-e9e3-562c-a53f-c93ad7b13758', 'd3b3c902-a555-52d5-ae51-d382859c5944', NULL, 16, 16, 'Therefore Job opens his mouth with empty talk, and he multiplies words without knowledge."'),
  ('10d32bc8-49e7-5fba-a7a5-cd1699ea7ea0', 'ac57e4c3-5720-5c6e-a28f-7a0aff1887cf', NULL, 1, 1, 'Elihu also continued, and said,'),
  ('3f1c901a-5939-5294-a737-3b426651d144', 'ac57e4c3-5720-5c6e-a28f-7a0aff1887cf', NULL, 2, 2, '"Bear with me a little, and I will show you; for I still have something to say on God''s behalf.'),
  ('af29d31d-eb7f-547c-ae2b-eee258569b23', 'ac57e4c3-5720-5c6e-a28f-7a0aff1887cf', NULL, 3, 3, 'I will get my knowledge from afar, and will ascribe righteousness to my Maker.'),
  ('c79622f0-54b3-5ad3-a9e0-e9f7e2ab330d', 'ac57e4c3-5720-5c6e-a28f-7a0aff1887cf', NULL, 4, 4, 'For truly my words are not false. One who is perfect in knowledge is with you.'),
  ('6738e6b2-c4da-5d09-aba9-411798227ea8', 'ac57e4c3-5720-5c6e-a28f-7a0aff1887cf', NULL, 5, 5, '"Behold, God is mighty, and doesn''t despise anyone. He is mighty in strength of understanding.'),
  ('98480b92-c707-5b6b-a00e-ecaf8e561ac5', 'ac57e4c3-5720-5c6e-a28f-7a0aff1887cf', NULL, 6, 6, 'He doesn''t preserve the life of the wicked, but gives to the afflicted their right.'),
  ('131761ca-76ec-5a59-a8b4-a2442a1ba19a', 'ac57e4c3-5720-5c6e-a28f-7a0aff1887cf', NULL, 7, 7, 'He doesn''t withdraw his eyes from the righteous, but with kings on the throne, he sets them forever, and they are exalted.'),
  ('99b53d68-5797-5038-ac70-704e85489b04', 'ac57e4c3-5720-5c6e-a28f-7a0aff1887cf', NULL, 8, 8, 'If they are bound in fetters, and are taken in the cords of afflictions,'),
  ('694b5170-5d23-593b-ad57-b12e76a2807c', 'ac57e4c3-5720-5c6e-a28f-7a0aff1887cf', NULL, 9, 9, 'then he shows them their work, and their transgressions, that they have behaved themselves proudly.'),
  ('1e0147bc-6b24-5d01-afe9-a25c374299dd', 'ac57e4c3-5720-5c6e-a28f-7a0aff1887cf', NULL, 10, 10, 'He also opens their ears to instruction, and commands that they return from iniquity.'),
  ('7ac73b2b-0dfb-5c9c-aeee-8e79ede280db', 'ac57e4c3-5720-5c6e-a28f-7a0aff1887cf', NULL, 11, 11, 'If they listen and serve him, they shall spend their days in prosperity, and their years in pleasures.'),
  ('7a26de84-d44b-594a-ae95-66e6ed5c297d', 'ac57e4c3-5720-5c6e-a28f-7a0aff1887cf', NULL, 12, 12, 'But if they don''t listen, they shall perish by the sword; they shall die without knowledge.'),
  ('b39acfe4-f33c-5813-aa38-495ebd08b91a', 'ac57e4c3-5720-5c6e-a28f-7a0aff1887cf', NULL, 13, 13, '"But those who are godless in heart lay up anger. They don''t cry for help when he binds them.'),
  ('67172906-e50c-5611-a0c1-f57976e919b6', 'ac57e4c3-5720-5c6e-a28f-7a0aff1887cf', NULL, 14, 14, 'They die in youth. Their life perishes among the unclean.'),
  ('a6e46d63-ed38-5692-aa82-6e5670cf4637', 'ac57e4c3-5720-5c6e-a28f-7a0aff1887cf', NULL, 15, 15, 'He delivers the afflicted by their affliction, and opens their ear in oppression.'),
  ('39efdc7d-2beb-5ccb-a5ce-fac51578d199', 'ac57e4c3-5720-5c6e-a28f-7a0aff1887cf', NULL, 16, 16, 'Yes, he would have allured you out of distress, into a broad place, where there is no restriction. That which is set on your table would be full of fatness.'),
  ('c2d46ef4-cafa-5e09-a4ed-4049a67b407c', 'ac57e4c3-5720-5c6e-a28f-7a0aff1887cf', NULL, 17, 17, '"But you are full of the judgment of the wicked. Judgment and justice take hold of you.'),
  ('9c73fad2-5256-5946-ad93-328b53b04d74', 'ac57e4c3-5720-5c6e-a28f-7a0aff1887cf', NULL, 18, 18, 'Don''t let riches entice you to wrath, neither let the great size of a bribe turn you aside.'),
  ('8a406e36-5df8-50f6-a44a-984216bf53a6', 'ac57e4c3-5720-5c6e-a28f-7a0aff1887cf', NULL, 19, 19, 'Would your wealth sustain you in distress, or all the might of your strength?'),
  ('bc859dd4-fea0-5e67-acfa-a7ee8f8fa418', 'ac57e4c3-5720-5c6e-a28f-7a0aff1887cf', NULL, 20, 20, 'Don''t desire the night, when people are cut off in their place.'),
  ('f1114320-2935-5e58-acd3-814c083e170a', 'ac57e4c3-5720-5c6e-a28f-7a0aff1887cf', NULL, 21, 21, 'Take heed, don''t regard iniquity; for you have chosen this rather than affliction.'),
  ('b4abe08b-07c1-518a-adae-36aa80ae76de', 'ac57e4c3-5720-5c6e-a28f-7a0aff1887cf', NULL, 22, 22, 'Behold, God is exalted in his power. Who is a teacher like him?'),
  ('c2ccbc77-7109-5134-a3e1-7f66b7fa8a04', 'ac57e4c3-5720-5c6e-a28f-7a0aff1887cf', NULL, 23, 23, 'Who has prescribed his way for him? Or who can say, ''You have committed unrighteousness?'''),
  ('de44b304-425c-5c93-ab80-bb94fd27a9c7', 'ac57e4c3-5720-5c6e-a28f-7a0aff1887cf', NULL, 24, 24, '"Remember that you magnify his work, whereof men have sung.'),
  ('c6a889c6-e892-5adc-a10e-9a983ee52ffe', 'ac57e4c3-5720-5c6e-a28f-7a0aff1887cf', NULL, 25, 25, 'All men have looked thereon. Man sees it afar off.'),
  ('ebf7d89a-c479-5cd4-a4b9-ad0e1d7655f4', 'ac57e4c3-5720-5c6e-a28f-7a0aff1887cf', NULL, 26, 26, 'Behold, God is great, and we don''t know him. The number of his years is unsearchable.'),
  ('9c71e9e9-fdd8-5563-ac4d-d70151f42c31', 'ac57e4c3-5720-5c6e-a28f-7a0aff1887cf', NULL, 27, 27, 'For he draws up the drops of water, which distill in rain from his vapor,'),
  ('80ae2604-7332-539a-ae59-5b2070ebbdc2', 'ac57e4c3-5720-5c6e-a28f-7a0aff1887cf', NULL, 28, 28, 'Which the skies pour down and which drop on man abundantly.'),
  ('6c427e8a-c961-5710-a90d-e0660ff84929', 'ac57e4c3-5720-5c6e-a28f-7a0aff1887cf', NULL, 29, 29, 'Yes, can any understand the spreading of the clouds, and the thunderings of his pavilion?'),
  ('5660a03a-7c20-5abb-a206-3c549c58016a', 'ac57e4c3-5720-5c6e-a28f-7a0aff1887cf', NULL, 30, 30, 'Behold, he spreads his light around him. He covers the bottom of the sea.'),
  ('938b34d7-8ebb-51a7-afb4-224e318bac6c', 'ac57e4c3-5720-5c6e-a28f-7a0aff1887cf', NULL, 31, 31, 'For by these he judges the people. He gives food in abundance.'),
  ('22da8d61-3558-57da-a9eb-2bc68063f08c', 'ac57e4c3-5720-5c6e-a28f-7a0aff1887cf', NULL, 32, 32, 'He covers his hands with the lightning, and commands it to strike the mark.'),
  ('e3ce33f1-c449-5c92-a866-a26cdd2e744d', 'ac57e4c3-5720-5c6e-a28f-7a0aff1887cf', NULL, 33, 33, 'Its noise tells about him, and the livestock also concerning the storm that comes up.'),
  ('9e33a06a-e161-5aec-a935-7df719f20e26', '316274fe-009d-529d-a234-1c741187f787', NULL, 1, 1, '"Yes, at this my heart trembles, and is moved out of its place.'),
  ('d402ee6f-8aee-5f53-abc2-8846a5a4d275', '316274fe-009d-529d-a234-1c741187f787', NULL, 2, 2, 'Hear, oh, hear the noise of his voice, the sound that goes out of his mouth.'),
  ('a8b6927e-65f2-5561-acc3-24819a50eb05', '316274fe-009d-529d-a234-1c741187f787', NULL, 3, 3, 'He sends it forth under the whole sky, and his lightning to the ends of the earth.'),
  ('e8090fe3-1d94-56a2-aee0-7ea4aec7ce5f', '316274fe-009d-529d-a234-1c741187f787', NULL, 4, 4, 'After it a voice roars. He thunders with the voice of his majesty. He doesn''t hold back anything when his voice is heard.'),
  ('c3169ade-7591-57a5-abe7-efb648669471', '316274fe-009d-529d-a234-1c741187f787', NULL, 5, 5, 'God thunders marvelously with his voice. He does great things, which we can''t comprehend.'),
  ('23804334-1b2c-5c2a-a30b-81c839671487', '316274fe-009d-529d-a234-1c741187f787', NULL, 6, 6, 'For he says to the snow, ''Fall on the earth;'' likewise to the shower of rain, and to the showers of his mighty rain.'),
  ('8f88e95e-ce2e-5c1b-a5a7-fd90acd8b19d', '316274fe-009d-529d-a234-1c741187f787', NULL, 7, 7, 'He seals up the hand of every man, that all men whom he has made may know it.'),
  ('6c837f9e-56a0-5495-a1ae-3e9721050f3a', '316274fe-009d-529d-a234-1c741187f787', NULL, 8, 8, 'Then the animals take cover, and remain in their dens.'),
  ('a3f21fad-aff5-5a2b-a66f-7d75a7ab3643', '316274fe-009d-529d-a234-1c741187f787', NULL, 9, 9, 'Out of its room comes the storm, and cold out of the north.'),
  ('699692f8-612d-5bd0-ae93-0329fbf21f77', '316274fe-009d-529d-a234-1c741187f787', NULL, 10, 10, 'By the breath of God, ice is given, and the breadth of the waters is frozen.'),
  ('de9c931a-dcd8-5977-a61c-a5a215fe3ee3', '316274fe-009d-529d-a234-1c741187f787', NULL, 11, 11, 'Yes, he loads the thick cloud with moisture. He spreads abroad the cloud of his lightning.'),
  ('6ae06549-03d1-5be5-acb6-5ebd8ee82bd2', '316274fe-009d-529d-a234-1c741187f787', NULL, 12, 12, 'It is turned around by his guidance, that they may do whatever he commands them on the surface of the habitable world,'),
  ('bfde6875-2f41-5f7d-a53c-83d0e6da486a', '316274fe-009d-529d-a234-1c741187f787', NULL, 13, 13, 'Whether it is for correction, or for his land, or for loving kindness, that he causes it to come.'),
  ('3a0c1498-ea76-5641-a068-f9852f0d2f05', '316274fe-009d-529d-a234-1c741187f787', NULL, 14, 14, '"Listen to this, Job. Stand still, and consider the wondrous works of God.'),
  ('3c05974b-c4df-50fb-a0f5-966d4702fda5', '316274fe-009d-529d-a234-1c741187f787', NULL, 15, 15, 'Do you know how God controls them, and causes the lightning of his cloud to shine?'),
  ('b993a7ec-7e2b-574e-a821-482efd6af3b5', '316274fe-009d-529d-a234-1c741187f787', NULL, 16, 16, 'Do you know the workings of the clouds, the wondrous works of him who is perfect in knowledge?'),
  ('25562267-3f03-52e5-a2f7-8418b08b889f', '316274fe-009d-529d-a234-1c741187f787', NULL, 17, 17, 'You whose clothing is warm, when the earth is still by reason of the south wind?'),
  ('f3799a76-3681-55fd-adb8-6568762da0ca', '316274fe-009d-529d-a234-1c741187f787', NULL, 18, 18, 'Can you, with him, spread out the sky, which is strong as a cast metal mirror?'),
  ('78d285db-a826-5692-af6b-03b215173728', '316274fe-009d-529d-a234-1c741187f787', NULL, 19, 19, 'Teach us what we shall tell him, for we can''t make our case by reason of darkness.'),
  ('8d543a57-a8e3-56d1-aa3c-4b2efc73415e', '316274fe-009d-529d-a234-1c741187f787', NULL, 20, 20, 'Shall it be told him that I would speak? Or should a man wish that he were swallowed up?'),
  ('bed31622-7881-553a-a2cb-dc230b2e137b', '316274fe-009d-529d-a234-1c741187f787', NULL, 21, 21, 'Now men don''t see the light which is bright in the skies, but the wind passes, and clears them.'),
  ('adce1dc8-028d-5b06-a878-c30bf106e1ce', '316274fe-009d-529d-a234-1c741187f787', NULL, 22, 22, 'Out of the north comes golden splendor. With God is awesome majesty.'),
  ('987e37c1-3585-5a84-a9e8-ed98dc5a9ec6', '316274fe-009d-529d-a234-1c741187f787', NULL, 23, 23, 'We can''t reach the Almighty. He is exalted in power. In justice and great righteousness, he will not oppress.'),
  ('c0c6706c-0179-5439-a76f-083f30a46f72', '316274fe-009d-529d-a234-1c741187f787', NULL, 24, 24, 'Therefore men revere him. He doesn''t regard any who are wise of heart."'),
  ('cd63d977-ab3e-510d-aaf2-171e07354225', 'f5fa55ad-289c-5f7c-a42f-706e485ba78c', NULL, 1, 1, 'Then Yahweh answered Job out of the whirlwind,'),
  ('48993de3-1d82-5230-a683-b81654729993', 'f5fa55ad-289c-5f7c-a42f-706e485ba78c', NULL, 2, 2, '"Who is this who darkens counsel by words without knowledge?'),
  ('c108d702-1be7-5ab3-a44a-9c25d5d67571', 'f5fa55ad-289c-5f7c-a42f-706e485ba78c', NULL, 3, 3, 'Brace yourself like a man, for I will question you, then you answer me!'),
  ('9271c532-cc24-577f-a0c0-929c43989836', 'f5fa55ad-289c-5f7c-a42f-706e485ba78c', NULL, 4, 4, '"Where were you when I laid the foundations of the earth? Declare, if you have understanding.'),
  ('2ac22243-090a-5a29-aa68-f9982fbbd24a', 'f5fa55ad-289c-5f7c-a42f-706e485ba78c', NULL, 5, 5, 'Who determined its measures, if you know? Or who stretched the line on it?'),
  ('bfec09fb-e942-53b6-ab22-f4def4ef4f77', 'f5fa55ad-289c-5f7c-a42f-706e485ba78c', NULL, 6, 6, 'Whereupon were its foundations fastened? Or who laid its cornerstone,'),
  ('cfc189f6-3a39-57a4-a04c-8ce679e41268', 'f5fa55ad-289c-5f7c-a42f-706e485ba78c', NULL, 7, 7, 'when the morning stars sang together, and all the sons of God shouted for joy?'),
  ('2b502c1d-8816-5fce-a951-342d609b81bd', 'f5fa55ad-289c-5f7c-a42f-706e485ba78c', NULL, 8, 8, '"Or who shut up the sea with doors, when it broke forth from the womb,'),
  ('94747a9e-25a6-5788-ac22-a4b7e607c4d6', 'f5fa55ad-289c-5f7c-a42f-706e485ba78c', NULL, 9, 9, 'when I made clouds its garment, and wrapped it in thick darkness,'),
  ('db82055f-56ae-5066-a4f1-1bdd87a0e559', 'f5fa55ad-289c-5f7c-a42f-706e485ba78c', NULL, 10, 10, 'marked out for it my bound, set bars and doors,'),
  ('5894f12f-c651-52cb-ac31-279f24526d9b', 'f5fa55ad-289c-5f7c-a42f-706e485ba78c', NULL, 11, 11, 'and said, ''Here you may come, but no further. Here your proud waves shall be stayed?'''),
  ('85b924d1-5d2c-5bc6-a72c-148672748a1a', 'f5fa55ad-289c-5f7c-a42f-706e485ba78c', NULL, 12, 12, '"Have you commanded the morning in your days, and caused the dawn to know its place;'),
  ('21299cf6-90fc-5133-adb7-acafd3a7ddd3', 'f5fa55ad-289c-5f7c-a42f-706e485ba78c', NULL, 13, 13, 'that it might take hold of the ends of the earth, and shake the wicked out of it?'),
  ('162f9d91-e930-5b23-aaff-d720336ce950', 'f5fa55ad-289c-5f7c-a42f-706e485ba78c', NULL, 14, 14, 'It is changed as clay under the seal, and stands forth as a garment.'),
  ('6b74eb75-0520-5c13-af4f-c54f85cf88c1', 'f5fa55ad-289c-5f7c-a42f-706e485ba78c', NULL, 15, 15, 'From the wicked, their light is withheld. The high arm is broken.'),
  ('f2577003-6b5c-561d-adfe-f9aca7023ab4', 'f5fa55ad-289c-5f7c-a42f-706e485ba78c', NULL, 16, 16, '"Have you entered into the springs of the sea? Or have you walked in the recesses of the deep?'),
  ('aa09c044-f7ab-5e17-ae87-bcdfb8fabcf0', 'f5fa55ad-289c-5f7c-a42f-706e485ba78c', NULL, 17, 17, 'Have the gates of death been revealed to you? Or have you seen the gates of the shadow of death?'),
  ('563ae493-44f1-5564-a70e-1dc29ade2dec', 'f5fa55ad-289c-5f7c-a42f-706e485ba78c', NULL, 18, 18, 'Have you comprehended the earth in its breadth? Declare, if you know it all.'),
  ('74281a4b-94f4-5563-a1b7-e8765a81f629', 'f5fa55ad-289c-5f7c-a42f-706e485ba78c', NULL, 19, 19, '"What is the way to the dwelling of light? As for darkness, where is its place,'),
  ('a4d816be-a0b8-548c-a57f-86243252ec8a', 'f5fa55ad-289c-5f7c-a42f-706e485ba78c', NULL, 20, 20, 'that you should take it to its bound, that you should discern the paths to its house?'),
  ('0b0fad9e-4a91-5604-a5a5-735ea32a1508', 'f5fa55ad-289c-5f7c-a42f-706e485ba78c', NULL, 21, 21, 'Surely you know, for you were born then, and the number of your days is great!'),
  ('d960e72d-ccbf-5747-a1b7-8b5c38c8a29c', 'f5fa55ad-289c-5f7c-a42f-706e485ba78c', NULL, 22, 22, 'Have you entered the treasuries of the snow, or have you seen the treasures of the hail,'),
  ('ce1f14be-1955-524b-a816-c9cd9e1f5cd5', 'f5fa55ad-289c-5f7c-a42f-706e485ba78c', NULL, 23, 23, 'which I have reserved against the time of trouble, against the day of battle and war?'),
  ('e4493804-7633-5061-a609-36ac53d52288', 'f5fa55ad-289c-5f7c-a42f-706e485ba78c', NULL, 24, 24, 'By what way is the lightning distributed, or the east wind scattered on the earth?'),
  ('fc4d629f-2434-5bc8-a9c9-ccb40fd67523', 'f5fa55ad-289c-5f7c-a42f-706e485ba78c', NULL, 25, 25, 'Who has cut a channel for the flood water, or the path for the thunderstorm;'),
  ('04666d89-41bf-5864-a359-58f502f1b7e6', 'f5fa55ad-289c-5f7c-a42f-706e485ba78c', NULL, 26, 26, 'To cause it to rain on a land where no man is; on the wilderness, in which there is no man;'),
  ('119bbf63-87d8-5cca-a1e8-96cfb2fe945e', 'f5fa55ad-289c-5f7c-a42f-706e485ba78c', NULL, 27, 27, 'to satisfy the waste and desolate ground, to cause the tender grass to spring forth?'),
  ('f60e46ef-00b1-55d1-a79d-ea1d62c3e5d0', 'f5fa55ad-289c-5f7c-a42f-706e485ba78c', NULL, 28, 28, 'Does the rain have a father? Or who fathers the drops of dew?'),
  ('55a08945-5fc2-553b-a483-c00deee6dea5', 'f5fa55ad-289c-5f7c-a42f-706e485ba78c', NULL, 29, 29, 'Out of whose womb came the ice? The gray frost of the sky, who has given birth to it?'),
  ('a4c5353a-5a42-5e5d-a8fe-2d1e7d6438f0', 'f5fa55ad-289c-5f7c-a42f-706e485ba78c', NULL, 30, 30, 'The waters become hard like stone, when the surface of the deep is frozen.'),
  ('060abd08-5a7d-5f05-ac3e-6da7b2f6ae56', 'f5fa55ad-289c-5f7c-a42f-706e485ba78c', NULL, 31, 31, '"Can you bind the cluster of the Pleiades, or loosen the cords of Orion?'),
  ('2d72f9a3-fc33-58fa-a6a7-a0ffdef4f514', 'f5fa55ad-289c-5f7c-a42f-706e485ba78c', NULL, 32, 32, 'Can you lead forth the constellations in their season? Or can you guide the Bear with her cubs?'),
  ('b450c9db-f367-5adf-acdb-0e9b1089098c', 'f5fa55ad-289c-5f7c-a42f-706e485ba78c', NULL, 33, 33, 'Do you know the laws of the heavens? Can you establish its dominion over the earth?'),
  ('07ace33b-b4aa-51de-a114-00f096daf127', 'f5fa55ad-289c-5f7c-a42f-706e485ba78c', NULL, 34, 34, '"Can you lift up your voice to the clouds, That abundance of waters may cover you?'),
  ('cbd18382-7ad7-5299-a75c-1895ac940ed5', 'f5fa55ad-289c-5f7c-a42f-706e485ba78c', NULL, 35, 35, 'Can you send forth lightnings, that they may go? Do they report to you, ''Here we are?'''),
  ('0ee2c54b-b300-5764-a268-214f87b8b392', 'f5fa55ad-289c-5f7c-a42f-706e485ba78c', NULL, 36, 36, 'Who has put wisdom in the inward parts? Or who has given understanding to the mind?'),
  ('5a0a7623-8b43-51f0-ad42-220412ce06f7', 'f5fa55ad-289c-5f7c-a42f-706e485ba78c', NULL, 37, 37, 'Who can number the clouds by wisdom? Or who can pour out the bottles of the sky,'),
  ('66924888-cac0-52bb-ab6d-9c7990c2808e', 'f5fa55ad-289c-5f7c-a42f-706e485ba78c', NULL, 38, 38, 'when the dust runs into a mass, and the clods of earth stick together?'),
  ('b0abaf1b-06ba-5a26-a56d-e4374b77de41', 'f5fa55ad-289c-5f7c-a42f-706e485ba78c', NULL, 39, 39, '"Can you hunt the prey for the lioness, or satisfy the appetite of the young lions,'),
  ('8de4e01d-8c27-597e-a47b-508d1ffcff6a', 'f5fa55ad-289c-5f7c-a42f-706e485ba78c', NULL, 40, 40, 'when they crouch in their dens, and lie in wait in the thicket?'),
  ('58882d91-f934-5257-a63a-3e7256a0c7a0', 'f5fa55ad-289c-5f7c-a42f-706e485ba78c', NULL, 41, 41, 'Who provides for the raven his prey, when his young ones cry to God, and wander for lack of food?'),
  ('e15d3ff2-926f-5e66-ae8a-10eff59edf2a', '913b1f75-09d0-5474-ad74-a2dc25a43f0b', NULL, 1, 1, '"Do you know the time when the mountain goats give birth? Do you watch when the doe bears fawns?'),
  ('bc4af121-8865-5d6c-a2bd-b316d527c7b4', '913b1f75-09d0-5474-ad74-a2dc25a43f0b', NULL, 2, 2, 'Can you number the months that they fulfill? Or do you know the time when they give birth?'),
  ('0f7bf59e-36f0-5f85-a5d1-fc6779ee8371', '913b1f75-09d0-5474-ad74-a2dc25a43f0b', NULL, 3, 3, 'They bow themselves, they bring forth their young, they end their labor pains.'),
  ('425bac23-1c4a-5408-ab5c-c7b9deda45e9', '913b1f75-09d0-5474-ad74-a2dc25a43f0b', NULL, 4, 4, 'Their young ones become strong. They grow up in the open field. They go forth, and don''t return again.'),
  ('4bd13d0b-5ca2-5cf8-a01d-75d64577a653', '913b1f75-09d0-5474-ad74-a2dc25a43f0b', NULL, 5, 5, '"Who has set the wild donkey free? Or who has loosened the bonds of the swift donkey,'),
  ('bcc0ceef-3c1e-5cbe-a051-3c84f087fe7f', '913b1f75-09d0-5474-ad74-a2dc25a43f0b', NULL, 6, 6, 'Whose home I have made the wilderness, and the salt land his dwelling place?'),
  ('29519905-7965-5efd-a1ae-b571222a55b7', '913b1f75-09d0-5474-ad74-a2dc25a43f0b', NULL, 7, 7, 'He scorns the tumult of the city, neither does he hear the shouting of the driver.'),
  ('4d618900-2dfe-5837-a2db-7084c3091e8c', '913b1f75-09d0-5474-ad74-a2dc25a43f0b', NULL, 8, 8, 'The range of the mountains is his pasture, He searches after every green thing.'),
  ('6d349457-18d3-5ff1-a0c4-8aa7ce379391', '913b1f75-09d0-5474-ad74-a2dc25a43f0b', NULL, 9, 9, '"Will the wild ox be content to serve you? Or will he stay by your feeding trough?'),
  ('8c43df47-04b3-5e32-a09b-684a970afc0a', '913b1f75-09d0-5474-ad74-a2dc25a43f0b', NULL, 10, 10, 'Can you hold the wild ox in the furrow with his harness? Or will he till the valleys after you?'),
  ('fb12e551-6da3-5f30-a3e5-ac519faa0ebe', '913b1f75-09d0-5474-ad74-a2dc25a43f0b', NULL, 11, 11, 'Will you trust him, because his strength is great? Or will you leave to him your labor?'),
  ('a731a015-2961-5d7b-ada4-54e6b935ecb5', '913b1f75-09d0-5474-ad74-a2dc25a43f0b', NULL, 12, 12, 'Will you confide in him, that he will bring home your seed, and gather the grain of your threshing floor?'),
  ('557dd141-ba28-5994-a458-38326775398d', '913b1f75-09d0-5474-ad74-a2dc25a43f0b', NULL, 13, 13, '"The wings of the ostrich wave proudly; but are they the feathers and plumage of love?'),
  ('5ed372cb-c0c1-5b12-addf-f016cdaab501', '913b1f75-09d0-5474-ad74-a2dc25a43f0b', NULL, 14, 14, 'For she leaves her eggs on the earth, warms them in the dust,'),
  ('072ba748-96b0-580c-af22-3d2113e68a8a', '913b1f75-09d0-5474-ad74-a2dc25a43f0b', NULL, 15, 15, 'and forgets that the foot may crush them, or that the wild animal may trample them.'),
  ('4df21d19-ba11-5b38-a330-22747e7d45d2', '913b1f75-09d0-5474-ad74-a2dc25a43f0b', NULL, 16, 16, 'She deals harshly with her young ones, as if they were not hers. Though her labor is in vain, she is without fear,'),
  ('aa118798-9f8f-5325-a438-0cd47714bd6b', '913b1f75-09d0-5474-ad74-a2dc25a43f0b', NULL, 17, 17, 'because God has deprived her of wisdom, neither has he imparted to her understanding.'),
  ('4ffd4670-e390-589a-a50d-b4c7f1a8e70d', '913b1f75-09d0-5474-ad74-a2dc25a43f0b', NULL, 18, 18, 'When she lifts up herself on high, she scorns the horse and his rider.'),
  ('c1732ae6-e96d-527d-aaeb-0aa0380bf13f', '913b1f75-09d0-5474-ad74-a2dc25a43f0b', NULL, 19, 19, '"Have you given the horse might? Have you clothed his neck with a quivering mane?'),
  ('d6753c12-941c-5a5b-a1d7-688bc630e781', '913b1f75-09d0-5474-ad74-a2dc25a43f0b', NULL, 20, 20, 'Have you made him to leap as a locust? The glory of his snorting is awesome.'),
  ('52c524ab-f579-58fd-a092-e541419b461f', '913b1f75-09d0-5474-ad74-a2dc25a43f0b', NULL, 21, 21, 'He paws in the valley, and rejoices in his strength. He goes out to meet the armed men.'),
  ('a80b1e53-f68c-51dd-a01e-8cd6cd10c00a', '913b1f75-09d0-5474-ad74-a2dc25a43f0b', NULL, 22, 22, 'He mocks at fear, and is not dismayed, neither does he turn back from the sword.'),
  ('288c67b6-af58-5ece-ad7c-46cc969906d5', '913b1f75-09d0-5474-ad74-a2dc25a43f0b', NULL, 23, 23, 'The quiver rattles against him, the flashing spear and the javelin.'),
  ('c55220c3-f395-5e1c-add9-541978686adb', '913b1f75-09d0-5474-ad74-a2dc25a43f0b', NULL, 24, 24, 'He eats up the ground with fierceness and rage, neither does he stand still at the sound of the trumpet.'),
  ('d07fd91e-93c3-523a-a060-6b75c89e95b4', '913b1f75-09d0-5474-ad74-a2dc25a43f0b', NULL, 25, 25, 'As often as the trumpet sounds he snorts, ''Aha!'' He smells the battle afar off, the thunder of the captains, and the shouting.'),
  ('45541aa5-fa87-56fa-afe5-53cee7241106', '913b1f75-09d0-5474-ad74-a2dc25a43f0b', NULL, 26, 26, '"Is it by your wisdom that the hawk soars, and stretches her wings toward the south?')
